// Pure presentation policy for the Omarchy startup overlay. The loader owns the lifecycle
// events and the real desktop-readiness probe; this module only makes those events honest and
// keeps the bounded guest-response wait deterministic in tests.

export const OMARCHY_GUEST_RESPONSE_WAIT_MS = 15_000;

const ROLE_LABELS = Object.freeze({
  kernel: "kernel",
  chunkManifest: "chunk manifest",
  overlayDelta: "overlay delta",
  bootSnapshot: "boot snapshot",
  gpuCheckpoint: "GPU desktop checkpoint",
});

const PHASE_LABELS = Object.freeze({
  downloading: "Downloading",
  "reading cache": "Reading cache for",
  unpacking: "Unpacking",
});

const STATE_LABELS = Object.freeze({
  fetching: "Fetching Omarchy image…",
  verifying: "Verifying Omarchy image…",
  instantiating: "Starting Omarchy VM…",
  restoring: "Restoring Omarchy desktop…",
  restored: "Desktop restored; waiting for guest response…",
  booting: "Booting Omarchy…",
  done: "Guest finished; desktop readiness is not confirmed.",
});

function humanizeRole(role) {
  const value = String(role ?? "").trim();
  if (ROLE_LABELS[value]) return ROLE_LABELS[value];
  if (!value) return "guest asset";
  return value
    .replace(/([a-z])([A-Z])/g, "$1 $2")
    .replace(/[-_]+/g, " ")
    .toLowerCase();
}

function finiteNumber(value) {
  return typeof value === "number" && Number.isFinite(value) ? value : null;
}

export function omarchyGuestStateLabel(state) {
  return STATE_LABELS[state] || null;
}

export function formatOmarchyProgress(detail = {}) {
  const rawPhase = String(detail.phase ?? "").trim();
  const match = /^(.+?)\s*:\s*(downloading|reading cache|unpacking)(?:\s*\(([^)]+)\))?$/i.exec(rawPhase);
  const role = match ? match[1].trim() : rawPhase;
  const phase = match ? match[2].toLowerCase() : null;
  const note = match?.[3]?.trim().toLowerCase() || null;
  const roleLabel = humanizeRole(role);
  const loaded = finiteNumber(detail.loaded);
  const total = finiteNumber(detail.total);
  const determinate = phase !== "unpacking" && total !== null && total > 0 && loaded !== null && loaded >= 0;

  let text;
  if (phase && PHASE_LABELS[phase]) {
    text = `${PHASE_LABELS[phase]} ${roleLabel}${note ? ` (${note})` : ""}…`;
  } else if (role) {
    text = `Loading ${roleLabel}…`;
  } else {
    text = "Loading guest…";
  }

  return {
    text,
    role,
    roleLabel,
    phase,
    note,
    loaded,
    total,
    determinate,
  };
}

export function createOmarchyStartupLifecycle({
  onWaiting = () => {},
  waitMs = OMARCHY_GUEST_RESPONSE_WAIT_MS,
  setTimeoutFn = globalThis.setTimeout,
  clearTimeoutFn = globalThis.clearTimeout,
} = {}) {
  let timer = null;
  let generation = 0;
  let desktopReady = false;
  let terminal = false;

  const cancelWait = () => {
    generation += 1;
    if (timer !== null) clearTimeoutFn(timer);
    timer = null;
  };

  const armGuestResponseWait = () => {
    if (desktopReady || terminal) return;
    if (timer !== null) clearTimeoutFn(timer);
    generation += 1;
    const token = generation;
    timer = setTimeoutFn(() => {
      timer = null;
      if (token !== generation || desktopReady || terminal) return;
      onWaiting();
    }, waitMs);
  };

  const finish = () => {
    terminal = true;
    desktopReady = false;
    cancelWait();
  };

  return {
    booting() {
      desktopReady = false;
      terminal = false;
      cancelWait();
    },
    state(state) {
      if (terminal) return false;
      if (state === "done") {
        finish();
        return true;
      }
      if (desktopReady) return false;
      if (state === "restored") armGuestResponseWait();
      return true;
    },
    guestReady() {
      if (desktopReady || terminal) return false;
      armGuestResponseWait();
      return true;
    },
    desktopReady() {
      if (desktopReady || terminal) return false;
      desktopReady = true;
      cancelWait();
      return true;
    },
    error() {
      finish();
    },
    halted() {
      finish();
    },
    isPending() {
      return !desktopReady && !terminal;
    },
    isDesktopReady() {
      return desktopReady;
    },
  };
}

// E4-T22: page-side registration for the COOP/COEP header-injection shim (coi-serviceworker.js).
//
// On a header-LESS host (GitHub Pages), the first load is not yet cross-origin isolated. This
// registers the shim SW and, once it controls the client, reloads ONCE so the reloaded document is
// served through the SW's synthesized COOP/COEP headers → crossOriginIsolated === true. On a host
// that already sends the headers (our dev server, or a proper prod config), it is a no-op.
//
// Discipline (no half-init): if isolation cannot be achieved, this resolves to `false` and the
// caller selects the single-threaded fallback via cpu-isolation.selectCpuBackend — never a
// partially-started threaded backend.

const RELOAD_FLAG = "__coi_reloaded";
const SW_READY_TIMEOUT_MS = 5_000;

function withTimeout(promise, label) {
  let timer;
  const timeout = new Promise((_, reject) => {
    timer = setTimeout(() => reject(new Error(`${label} timed out`)), SW_READY_TIMEOUT_MS);
  });
  return Promise.race([promise, timeout]).finally(() => clearTimeout(timer));
}

/**
 * Ensure the page is cross-origin isolated, registering the shim if needed.
 * @param {object} [opts]
 * @param {string} [opts.swUrl] URL of coi-serviceworker.js (default "./coi-serviceworker.js")
 * @param {boolean} [opts.allowReload] permit the one-time reload (default true)
 * @returns {Promise<boolean>} whether the page is (now) cross-origin isolated
 */
export async function ensureCrossOriginIsolated(opts = {}) {
  const { swUrl = "./coi-serviceworker.js", allowReload = true } = opts;

  if (globalThis.crossOriginIsolated === true) return true;
  if (typeof navigator === "undefined" || !navigator.serviceWorker) return false;
