    return { ok: false, conflict: true, error: `${boot?.winner ?? "another guest"} boot already owns the VM` };
  }
  return linuxCtl
    ? { ok: true, ...(boot?.already ? { already: true } : {}) }
    : { ok: false, error: lastBootError || "boot failed" };
}

