// E2-T22: xterm.js ↔ 16550 UART bridge. Makes the in-page terminal byte-for-byte equivalent
// to the native CLI's pty: guest output written verbatim (xterm renders VT100/xterm sequences
// natively — we never filter or translate), keystrokes/paste encoded to UTF-8 and delivered to
// the guest's ttyS0 RX with backpressure, and an explicit resize story (fit addon + `stty` hint).
//
// UMD globals loaded via <script> in index.html (no bundler): `Terminal` (@xterm/xterm) and
// `FitAddon` (@xterm/addon-fit).

import { createOsc52Handler } from "./osc52.js";
import { BRACKET_END, BRACKET_START, framePaste } from "./paste.js";

// Bytes handed to the guest per drain tick. Bounds a single JS→wasm copy so a huge paste never
// becomes one giant allocation; the guest's RX FIFO paces the actual consumption underneath.
const INPUT_CHUNK = 4096;

/**
 * Build the terminal and its input bridge over an existing container element.
 * Returns a controller:
 *   term            the xterm.js Terminal (existing ELF-console code keeps using this)
 *   write(u8)       write guest output bytes to the screen
 *   attachSink(fn)  route keyboard/paste bytes to `fn(Uint8Array)` (e.g. linuxCtl.sendInput);
 *                   immediately drains anything typed before the guest existed
 *   detachSink()    stop routing (guest gone) — typed bytes queue until the next attach
 *   fitNow()        re-fit the rendered grid to the container; returns {cols, rows}
 *   sttyHint()      the `stty rows R cols C` line matching the current fit
 *   highWater()     max bytes ever queued in JS awaiting the guest (backpressure metric)
 *   typeBytes(u8)   inject raw bytes as if typed (used by tests)
 */
export function createLinuxTerminal(containerEl) {
  const term = new Terminal({
    convertEol: true, // bare \n from earlycon → column 0; the guest's onlcr \r\n passes through unchanged
    cursorBlink: true,
    scrollback: 5000,
    fontFamily: "ui-monospace, monospace",
    fontSize: 13,
    theme: { background: "#0b0e14", foreground: "#cdd6f4" },
    // E3-T22b: we OWN paste framing (framePaste: newline normalization + bracketed wrap + embedded
    // end-marker neutralization). Tell xterm not to also add 200~/201~, so paste is never double-framed
    // and the paste-injection defense is ours, not the library's.
    ignoreBracketedPasteMode: true,
  });
  const fit = new FitAddon.FitAddon();
  term.loadAddon(fit);
  term.open(containerEl);
  try { fit.fit(); } catch { /* container not laid out yet — caller can fitNow() later */ }

  // Key policy: a BARE Ctrl+C must always reach the guest as ^C (SIGINT) — that reliability is
  // the whole point of a real console — so copy is bound to Ctrl+Shift+C (Cmd+C on mac), and
  // paste to Ctrl+Shift+V / Cmd+V. Those combos return false (browser handles them; xterm's DOM
  // paste path still re-emits pasted text through onData). Everything else goes to the guest.
  term.attachCustomKeyEventHandler((e) => {
    if (e.type !== "keydown") return true;
    if (e.metaKey && (e.key === "c" || e.key === "v")) return false; // mac copy/paste
    if ((e.ctrlKey || e.metaKey) && e.shiftKey && (e.key === "C" || e.key === "V")) return false;
    return true;
  });

  // Input backpressure queue. The authoritative no-drop guarantee lives in the Rust pending→RX
  // path (it respects rx_free and never drops on a full FIFO — only genuine overrun sets OE).
  // This JS queue bounds per-call copy size for big pastes and exposes a high-water metric.
  const queue = []; // Uint8Array chunks, FIFO
  let pendingBracketedPaste = null; // Uint8Array chunks held until an explicit Enter or Ctrl-C
  let queued = 0;
  let highWater = 0;
  let draining = false;
  let sink = null;
  const enc = new TextEncoder();

  function pump() {
    if (!sink || queued === 0) { draining = false; return; }
    draining = true;
    const want = Math.min(INPUT_CHUNK, queued);
    const chunk = new Uint8Array(want);
    let off = 0;
    while (off < want && queue.length) {
      const head = queue[0];
      const take = Math.min(head.length, want - off);
      chunk.set(head.subarray(0, take), off);
      off += take;
      if (take === head.length) queue.shift();
      else queue[0] = head.subarray(take);
    }
    queued -= off;
    sink(chunk);
    if (queued > 0) setTimeout(pump, 0);
    else draining = false;
  }

  function feed(bytes) {
    if (bytes.length === 0) return;
    queue.push(bytes);
    queued += bytes.length;
    if (queued > highWater) highWater = queued;
    if (!draining) pump();
  }

  // Busybox ash (the fast guest used by the demo) does not consume DECSET-2004 markers itself. Hold a
  // bracketed paste in the host until the user supplies a terminating Enter, then release the sanitized
  // body as one ordered input sequence. Ctrl-C cancels the held paste. Guests with a bracket-aware line
  // editor get the same user-visible guarantee; the host hold is a compatibility fallback, not a second
  // framing layer. Ordinary typed bytes while a paste is held are buffered in order and released with it.
  function typeBytes(bytes) {
    if (!pendingBracketedPaste) {
      feed(bytes);
      return;
    }
    let boundary = -1;
    for (let index = 0; index < bytes.length; index += 1) {
      if (bytes[index] === 0x03 || bytes[index] === 0x0a || bytes[index] === 0x0d) {
        boundary = index;
        break;
      }
    }
    if (boundary < 0) {
      if (bytes.length > 0) pendingBracketedPaste.push(bytes.slice());
      return;
    }
    if (boundary > 0) pendingBracketedPaste.push(bytes.slice(0, boundary));
    const control = bytes[boundary];
    if (control === 0x03) {
      pendingBracketedPaste = null;
      feed(bytes.subarray(boundary));
      return;
    }
    const held = pendingBracketedPaste;
    pendingBracketedPaste = null;
    for (const chunk of held) feed(chunk);
    feed(bytes.subarray(boundary));
  }

  term.onData((str) => typeBytes(enc.encode(str)));

  // E3-T22a: OSC 52 clipboard copy. A guest `ESC]52;c;<base64>` sets the host clipboard; a rejected
  // write (denied permission / no transient activation / insecure context) surfaces a non-destructive
  // affordance instead of dropping silently. The clipboard-READ query (`52;c;?`) stays OFF by default
  // (a guest read of the host clipboard is an exfiltration channel); `setClipboardRead(true)` opts in.
  let allowClipboardRead = false;
  let onCopyBlocked = null; // set by the host UI to show a "copied — click to confirm" affordance
  let onCopied = null; // set by the host UI to show a "copied!" confirmation on a successful write
  const oscHandler = createOsc52Handler({
    writeClipboard: (text) =>
      navigator.clipboard?.writeText
        ? navigator.clipboard.writeText(text)
        : Promise.reject(new Error("clipboard unavailable")),
    readClipboard: () => navigator.clipboard.readText(),
    allowRead: () => allowClipboardRead, // thunk — the live toggle is honored per-invocation
    onCopied: (text) => { if (onCopied) onCopied(text); },
    onCopyBlocked: (text) => { if (onCopyBlocked) onCopyBlocked(text); },
    respond: (payload) => feed(enc.encode(`\x1b]52;${payload}\x07`)),
  });
  // xterm strips the `ESC]52;` framing and passes the handler the data string. In xterm.js 5.x the
  // parser owns this API (`term.parser.registerOscHandler`); retain the terminal-level fallback for
  // older builds. A silent no-op here would turn every guest OSC 52 copy into an unobservable drop.
  try {
    if (term.parser && typeof term.parser.registerOscHandler === "function") {
      term.parser.registerOscHandler(52, oscHandler);
    } else if (typeof term.registerOscHandler === "function") {
      term.registerOscHandler(52, oscHandler);
    }
  } catch { /* xterm without OSC hooks — deterministic handler tests still cover the pure path */ }

  // E3-T22b: frame + inject a paste. `bracketed` is snapshotted from the guest's live DECSET-2004
  // state ONCE per paste (no torn half-bracket if the guest toggles mid-paste). Unbracketed input feeds
  // the same backpressure queue immediately; bracketed input holds the sanitized body until Enter.
  function pasteText(text) {
    const bracketed = !!(term.modes && term.modes.bracketedPasteMode);
    const value = String(text ?? "");
    if (!bracketed) {
      feed(enc.encode(framePaste(value, { bracketed: false })));
      return;
    }
    const framed = framePaste(value, { bracketed: true });
    // Keep framePaste's newline normalization and end-marker neutralization, but remove the wrapper:
    // the host hold supplies the no-early-execute boundary for ash, which does not parse the markers.
    const body = enc.encode(framed.slice(BRACKET_START.length, -BRACKET_END.length));
    if (pendingBracketedPaste) pendingBracketedPaste.push(body);
    else pendingBracketedPaste = [body];
  }
  // Own the paste at the DOM level (capture phase → before xterm's textarea handler), so our framing
  // is the only framing and the injection defense is enforced. `ignoreBracketedPasteMode` above keeps
  // xterm from re-wrapping if this ever doesn't fire (degraded but never double-framed).
  try {
    containerEl.addEventListener(
      "paste",
      (e) => {
        const text = (e.clipboardData && e.clipboardData.getData("text")) || "";
        e.preventDefault();
        e.stopImmediatePropagation();
        pasteText(text);
      },
      true,
    );
  } catch { /* no DOM (unit env) — pasteText() is still callable directly */ }

  return {
    term,
    fit,
    write: (u8) => term.write(u8),
    attachSink(fn) { sink = fn; if (queued && !draining) pump(); },
    detachSink() { sink = null; },
    fitNow() { try { fit.fit(); } catch { /* ignore */ } return { cols: term.cols, rows: term.rows }; },
    sttyHint() { return `stty rows ${term.rows} cols ${term.cols}`; },
    highWater: () => highWater,
    typeBytes,
    // xterm only captures keystrokes while its hidden textarea is focused. Nothing focuses
    // it implicitly, so manual typing silently goes nowhere until this is called (after boot
    // and whenever the Terminal tab is (re)shown from a display:none panel).
    focus() { try { term.focus(); } catch { /* ignore */ } },
    // E3-T22a: opt in to answering guest clipboard-READ queries (`OSC 52 ; c ; ?`). Default off —
    // a guest reading the host clipboard is an exfiltration channel, so this must be explicit.
    setClipboardRead(enabled) { allowClipboardRead = !!enabled; },
    clipboardReadEnabled: () => allowClipboardRead,
    // E3-T22a: register a callback shown when a clipboard WRITE is blocked (denied permission / no
    // transient activation / insecure context) — the "copied — click to confirm" affordance. The
    // payload is preserved so the click can complete the write; nothing is ever dropped silently.
    onClipboardCopyBlocked(fn) { onCopyBlocked = fn; },
    // E3-T22a: register a callback fired when a clipboard WRITE succeeds (the "copied!" confirmation),
    // carrying the decoded text. Symmetric with onClipboardCopyBlocked.
    onClipboardCopied(fn) { onCopied = fn; },
    // E3-T22b: frame + inject pasted text (newline-normalized, bracketed per the guest's live mode
    // 2004, embedded end-markers neutralized). Used by the DOM paste interceptor and by E2E tests.
    pasteText,
    bracketedPasteEnabled: () => !!(term.modes && term.modes.bracketedPasteMode),
  };
}

// E3-T24a: binds the pure boot-progress model (progress.js) to an accessible DOM surface and
// translates the loader's existing callbacks (onState / onProgress / onOutput / onError) plus the
// pollable chunk-fetch counter into the typed event stream the model consumes. Kept separate from
// the model so the invariants stay headlessly testable and the DOM here stays a thin renderer.

import { applyProgress, initialProgress, percent } from "./progress.js";

// onState string → typed events. The loader's six states map onto stage milestones; entering a later
// stage fills the earlier ones in the model, so a skipped state cannot strand the bar.
const STATE_EVENTS = {
  fetching: [
    { kind: "complete", stage: "wasm" },
    { kind: "complete", stage: "manifest" },
    { kind: "enter", stage: "kernel" },
  ],
  verifying: [
    { kind: "complete", stage: "kernel" },
    { kind: "complete", stage: "chunk" },
  ],
  instantiating: [{ kind: "complete", stage: "wasm" }],
  booting: [{ kind: "enter", stage: "login" }],
  // `done` = guest halt, NOT prompt-usable, so it is deliberately NOT a `ready`.
};

// onProgress role → measurable stage.
const ROLE_STAGE = { kernel: "kernel", rootfs: "chunk", initramfs: "chunk" };

// Terminal markers that mean "the prompt is usable" — the honest definition of 100%. These are the
// exact banners the existing boot tests treat as "booted" (chunked-boot waits on `login:`, the
// busybox cold boot on `userland up`). Deliberately specific: a looser generic-shell-prompt regex
// matches kernel-log noise mid-boot and would fire 100% early, so it is NOT used.
const READY_MARKERS = [/login:/, /userland up/];

/** Bind a progress surface to its DOM. `bar` is the role="progressbar" element, `label` the
 * aria-live status element, `detail` an optional per-role byte-text element (back-compat). */
export function createBootProgressSurface({ bar, label, root }) {
  let state = initialProgress();

  function render() {
    const pct = percent(state);
    if (bar) {
      bar.setAttribute("aria-valuenow", String(pct));
      bar.setAttribute("aria-valuetext", state.error ? state.label : `${state.label} — ${pct}%`);
      bar.dataset.indeterminate = state.indeterminate ? "true" : "false";
      bar.dataset.error = state.error ? "true" : "false";
      bar.dataset.ready = state.ready ? "true" : "false";
      const fill = bar.querySelector(".bp-fill");
      if (fill) fill.style.width = `${pct}%`;
    }
    if (label) label.textContent = state.label;
    if (root) root.hidden = false;
  }

  function dispatch(evt) {
    const next = applyProgress(state, evt);
    if (next !== state) {
      state = next;
      render();
    }
    return state;
  }

  return {
    /** Reset for a fresh boot and show the surface at 0%. */
    begin() {
      state = initialProgress();
      dispatch({ kind: "enter", stage: "wasm" });
      render();
    },
    dispatch,
    onState(s) {
      for (const evt of STATE_EVENTS[s] ?? []) dispatch(evt);
    },
    onProgress(role, loaded, total) {
      const stage = ROLE_STAGE[role];
      if (!stage) return;
      if (stage === "chunk") dispatch({ kind: "complete", stage: "kernel" });
      dispatch({ kind: "bytes", stage, loaded, total: total ?? null });
    },
    /** Emit measured chunk bytes for a lazy/chunked image (no per-fetch callback exists; the loader
     * exposes a running byte counter instead). `total` is the full image length — honest "fraction of
     * the image fetched", capped at 1. */
    onChunkBytes(loaded, total) {
      dispatch({ kind: "complete", stage: "kernel" });
      dispatch({ kind: "bytes", stage: "chunk", loaded, total: total ?? null });
    },
    /** Scan guest console bytes for a usable-prompt marker; the first match completes the bar. */
    scanOutput(text) {
      if (state.ready) return;
      if (READY_MARKERS.some((re) => re.test(text))) dispatch({ kind: "ready" });
    },
    fail(message) {
      dispatch({ kind: "error", stage: state.activeStage ?? "wasm", message });
    },
    get state() {
      return state;
    },
  };
}

export { READY_MARKERS };

// E3.5-T05e: the fenced request/response protocol over the single ttyS0 console, extracted as a pure,
// node-testable module. The browser Docker tab drives `wvrun ps/logs/run/exec` over ONE serial console
// and must parse STRUCTURED results, not scrape free-form text — so each RPC is fenced with a unique
// request id and an END marker that embeds the guest-computed exit code. This file is the parser +
// command formatter that logic; `web/main.js`'s `guestExec` consumes this module for the live bridge.
// Keeping it pure lets the adversarial cases — marker-spoof, stream-split, echo-strip — be proven
// deterministically without a browser boot.
//
// Protocol: to run `<cmd>` under request id `<rid>`, send
//   printf '\n__WVBEGIN_<rid>\n'; <cmd>; printf '\n__WVEND_<rid>_%s\n' "$?"\r
// The guest echoes the command line, then emits a full-line BEGIN, the command's stdout, and a
// full-line END containing the guest-computed exit code. The parser ignores everything before BEGIN
// (including the shell prompt and echoed command) and returns only the bytes between the two nonce
// lines. It never heuristically strips a prompt or output line.

// Strip xterm/ANSI control sequences and carriage returns, matching what main.js does before parsing.
export function stripConsole(text) {
  return text
    // systemd/Bash OSC 3008 metadata and terminal DCS replies are not command stdout. Hide a
    // partial control through the current end; the RPC retains raw bytes for the next feed.
    .replace(/\x1b\][\s\S]*?(?:\x07|\x1b\\|$)/g, "")
    .replace(/\x1bP[\s\S]*?(?:\x1b\\|$)/g, "")
    .replace(/\x1b\[[0-?]*[ -/]*[@-~]/g, "")
    .replace(/\x1b\[[0-?]*[ -/]*$/g, "")
    .replace(/\r/g, "");
}

// The END-marker matcher for a given request id. Both line boundaries are load-bearing: the command's
// own echoed `printf '…__WVEND_<rid>_%s\n'` ends in `%s`, NOT a digit, and a marker-looking substring
// inside ordinary output cannot satisfy this fence.
export function endMarkerRegex(rid) {
  return new RegExp(`(?:^|\\n)__WVEND_${escapeRegExp(rid)}_(\\d+)\\n`);
}

// The exact bytes to send for one fenced RPC. `\r` (CR) is the Enter the tty maps to NL; the leading
// newline in the END printf makes its marker a complete line even when command output lacks a newline.
export function formatRpcCommand(cmd, rid) {
  return `printf '\\n__WVBEGIN_${rid}\\n'; ${cmd}; printf '\\n__WVEND_${rid}_%s\\n' "$?"\r`;
}

// A stateful parser for ONE in-flight RPC. `feed(chunk)` accepts a string (already UTF-8 decoded) OR a
// Uint8Array; it accumulates, and returns { stdout, exit } once both nonce fences for `rid` arrive, or
// null while still waiting. Byte-stream robust: markers and OSC metadata may split across feeds.
export function createFencedRpc(rid, { decoder } = {}) {
  const re = endMarkerRegex(rid);
  const beginRe = new RegExp(`(?:^|\\n)__WVBEGIN_${escapeRegExp(rid)}\\n`);
  const dec = decoder || (typeof TextDecoder !== "undefined" ? new TextDecoder() : null);
  let buf = "";
  let done = false;
  return {
    feed(chunk) {
      if (done) return null;
      const text = typeof chunk === "string" ? chunk : dec.decode(chunk, { stream: true });
      buf += text;
      const plain = stripConsole(buf);
      const begin = plain.match(beginRe);
      if (!begin) return null;
      const bodyStart = begin.index + begin[0].length;
      const m = plain.slice(bodyStart).match(re);
      if (!m) return null;
      done = true;
      const exit = parseInt(m[1], 10);
      // The END regex includes its line-start newline when it is not at body start. Keep the
      // complete payload between marker lines, including any command-output newline before END.
      const endStart = bodyStart + m.index + (m[0].startsWith("\n") ? 1 : 0);
      return { stdout: plain.slice(bodyStart, endStart), exit };
    },
    get settled() {
      return done;
    },
  };
}

function escapeRegExp(s) {
  return String(s).replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

// E5-T12b: DOM KeyboardEvent normalization and the T11 evdev frame adapter.
// This file intentionally uses JavaScript-compatible TypeScript so the no-bundler demo can use the
// byte-identical keyboard.js projection. Capture/preventDefault policy is owned by E5-T12c.

import { evdevForCode } from "./keymap.js";
import { createHeldKeyLedger } from "./held-keys.js";

export const EV_SYN = 0;
export const SYN_REPORT = 0;
export const EV_KEY = 1;
export const IME_KEY_CODE = 229;

const MODIFIER_CODES = new Set([
  "ShiftLeft",
  "ShiftRight",
  "ControlLeft",
  "ControlRight",
  "AltLeft",
  "AltRight",
  "MetaLeft",
  "MetaRight",
]);

function result(code, reason, extra = {}) {
  return { forwarded: false, code, reason, ...extra };
}

function isImeEvent(event) {
  return event?.isComposing === true
    || Number(event?.keyCode) === IME_KEY_CODE
    || Number(event?.which) === IME_KEY_CODE;
}

/** Adapt either a direct WasmLinux controller or the whole-machine-worker proxy. */
export function createWasmKeyboardAdapter(controller) {
  if (typeof controller?.sendKeyboardEvent !== "function") {
    throw new TypeError("keyboard adapter requires sendKeyboardEvent");
  }
  if (typeof controller?.syncKeyboard !== "function") {
    throw new TypeError("keyboard adapter requires syncKeyboard");
  }
  return {
    sendKeyboardEvent: (...args) => controller.sendKeyboardEvent(...args),
    syncKeyboard: () => controller.syncKeyboard(),
  };
}

/**
 * Create the physical-code bridge. Each accepted key transition emits one EV_KEY event followed
 * by one T11 sync frame. The adapter methods may be synchronous (direct WasmLinux) or return
 * promises (the worker proxy); the worker protocol already serializes the posted calls in order.
 */
export function createKeyboardBridge(adapter, { onDiagnostic = () => {}, onFrame = () => {} } = {}) {
  if (typeof adapter?.sendKeyboardEvent !== "function") {
    throw new TypeError("keyboard bridge requires sendKeyboardEvent");
  }
  if (typeof adapter?.syncKeyboard !== "function") {
    throw new TypeError("keyboard bridge requires syncKeyboard");
  }

  function diagnostic(reason, event) {
    try {
      onDiagnostic({
        reason,
        code: typeof event?.code === "string" ? event.code : "",
        eventType: event?.type ?? "",
      });
    } catch {
      // Diagnostics must never break the input path.
    }
  }

  // The reusable T13a ledger is the source of truth for what the guest believes is physically
  // down. Modifier metadata remains mutable so a deferred break can be cancelled by a later
  // duplicate make from a browser recovery path.
  const held = createHeldKeyLedger({
    onDiagnostic: ({ reason, code }) => diagnostic(reason, { type: "ledger", code }),
  });

  function publish(code, evdev, value) {
    adapter.sendKeyboardEvent(EV_KEY, evdev, value);
    adapter.syncKeyboard();
    const frame = { eventType: EV_KEY, code, evdev, value, sync: SYN_REPORT };
    try { onFrame(frame); } catch { /* instrumentation must not break input */ }
    return { forwarded: true, code, evdev, value, frame };
  }

  function hasDependentKey() {
    for (const [, state] of held.entries()) {
      if (!state.modifier) return true;
    }
    return false;
  }

  function flushDeferredModifiers() {
    if (hasDependentKey()) return [];
    const flushed = [];
    const pending = held.entries()
      .filter(([, state]) => state.modifier && state.pendingRelease)
      .reverse();
    for (const [code, state] of pending) {
      flushed.push(publish(code, state.evdev, 0));
      held.release(code);
    }
    return flushed;
  }

  function handleKeyEvent(event) {
    const eventType = event?.type;
    if (eventType !== "keydown" && eventType !== "keyup") {
      diagnostic("unsupported-event", event);
      return result(typeof event?.code === "string" ? event.code : "", "unsupported-event");
    }
    if (isImeEvent(event)) {
      diagnostic("ime-event", event);
      return result(typeof event?.code === "string" ? event.code : "", "ime-event");
    }

    const code = typeof event.code === "string" ? event.code : "";
    const evdev = evdevForCode(code);
    if (evdev === null) {
      diagnostic("unmapped-code", event);
      return result(code, "unmapped-code");
    }

    const modifier = MODIFIER_CODES.has(code);
    if (eventType === "keydown") {
      if (event.repeat === true) {
        diagnostic("repeat-keydown", event);
        return result(code, "repeat-keydown", { evdev });
      }
      const prior = held.get(code);
      if (prior) {
        // A second non-repeat keydown is still a duplicate physical make. If a modifier's release
        // was deferred, this keydown means it stayed held and cancels that pending break.
        prior.pendingRelease = false;
        diagnostic("duplicate-keydown", event);
        return result(code, "duplicate-keydown", { evdev });
      }
      const forwarded = publish(code, evdev, 1);
      held.press(code, { evdev, modifier, pendingRelease: false });
      return forwarded;
    }

    const prior = held.get(code);
    if (!prior) {
      diagnostic("orphan-keyup", event);
      return result(code, "orphan-keyup", { evdev });
    }
    if (prior.modifier && hasDependentKey() && event?.reconciliation !== true) {
      prior.pendingRelease = true;
      return result(code, "modifier-release-deferred", { evdev });
    }

    const forwarded = publish(code, evdev, 0);
    held.release(code);
    if (!prior.modifier) flushDeferredModifiers();
    return forwarded;
  }

  function releaseAll() {
    const releases = [];
    held.releaseAll((code, state) => releases.push(publish(code, state.evdev, 0)));
    return releases;
  }

  return {
    handleKeyEvent,
    keydown: (event) => handleKeyEvent({ ...event, type: "keydown" }),
    keyup: (event) => handleKeyEvent({ ...event, type: "keyup" }),
    releaseAll,
    heldCodes: held.codes,
    heldSnapshot: held.snapshot,
    resetHeld: held.reset,
    isHeld: (code) => held.has(code),
    pendingModifierCodes: () => [...held.entries()]
      .filter(([, state]) => state.modifier && state.pendingRelease)
      .map(([code]) => code),
  };
}

/** Attach only event translation; capture and browser-default policy are deliberately separate. */
export function attachKeyboardBridge(target, bridge, options = {}) {
  if (!target || typeof target.addEventListener !== "function") {
    throw new TypeError("keyboard bridge target must support addEventListener");
  }
  if (typeof bridge?.handleKeyEvent !== "function") {
    throw new TypeError("keyboard bridge requires handleKeyEvent");
  }
  const listener = (event) => bridge.handleKeyEvent(event);
  target.addEventListener("keydown", listener, options);
  target.addEventListener("keyup", listener, options);
  return () => {
    target.removeEventListener?.("keydown", listener, options);
    target.removeEventListener?.("keyup", listener, options);
  };
}

const MAX_SELECTED_FILES = 32;
const MAX_RETAINED_ROWS = 64;
const UPLOAD_WORKERS = 2;
const POLL_MS = 24;

const delay = (ms = POLL_MS) => new Promise((resolve) => setTimeout(resolve, ms));
const ignoreRejection = (operation) => {
  try {
    const value = typeof operation === "function" ? operation() : operation;
    void Promise.resolve(value).catch(() => {});
  } catch { /* legacy synchronous controller parity */ }
};

function formatBytes(value) {
  if (value < 1024) return `${value} B`;
  if (value < 1024 * 1024) return `${(value / 1024).toFixed(1)} KiB`;
  return `${(value / 1024 / 1024).toFixed(1)} MiB`;
}

function safePercent(done, total) {
  return total === 0 ? 100 : Math.min(100, Math.floor((done / total) * 100));
}

function terminalUploadError(record) {
  const terminal = record?.diagnostic?.terminal;
  const code = record?.error || terminal?.error || "Unknown";
  const transition = terminal?.transition ? ` during ${terminal.transition}` : "";
  const error = new Error(`guest upload ${code}${transition}`);
  error.diagnostic = record?.diagnostic ?? null;
  return error;
}

async function hashFile(file, FileSha256, signal) {
  const hasher = new FileSha256();
  const reader = file.stream().getReader();
  try {
    while (true) {
      if (signal.aborted) throw new DOMException("Upload cancelled", "AbortError");
      const { done, value } = await reader.read();
      if (done) break;
      hasher.update(value);
    }
    return hasher.finish();
  } finally {
    reader.releaseLock();
    hasher.free?.();
  }
}

function transferRow(document, transfer, cancel) {
  const row = document.createElement("li");
  row.className = `transfer-row ${transfer.state}`;
  row.dataset.transferId = transfer.key;

  const head = document.createElement("div");
  head.className = "transfer-row-head";
  const name = document.createElement("strong");
  name.textContent = transfer.name;
  const state = document.createElement("span");
  state.className = "transfer-state";
  state.textContent = transfer.label;
  head.append(name, state);

  const progress = document.createElement("progress");
  progress.max = Math.max(1, transfer.total);
  progress.value = transfer.total === 0 ? 1 : transfer.done;
  progress.setAttribute("aria-label", `${transfer.name}: ${transfer.label}`);

  const detail = document.createElement("div");
  detail.className = "transfer-detail";
  detail.textContent =
    `${transfer.direction} · ${formatBytes(transfer.done)} / ${formatBytes(transfer.total)} · ${safePercent(transfer.done, transfer.total)}%`;

  row.append(head, progress, detail);
  if (transfer.state === "hashing" || transfer.state === "queued" || transfer.state === "active") {
    const button = document.createElement("button");
    button.type = "button";
    button.className = "transfer-cancel";
    button.textContent = "Cancel";
    button.setAttribute("aria-label", `Cancel ${transfer.name}`);
    button.addEventListener("click", cancel);
    row.append(button);
  }
  return row;
}

export function createFileTransferUI({
  root,
  FileSha256,
  openDirectory = () => globalThis.showDirectoryPicker(),
}) {
  if (!root) throw new Error("file-transfer root is required");
  const document = root.ownerDocument;
  const drop = root.querySelector("#file-transfer-drop");
  const input = root.querySelector("#file-transfer-input");
  const choose = root.querySelector("#file-transfer-choose");
  const chooseDownload = root.querySelector("#file-transfer-download-folder");
  const status = root.querySelector("#file-transfer-status");
  const list = root.querySelector("#file-transfer-list");
  const transfers = new Map();
  const uploadQueue = [];
  const claimedSlots = new Set();
  const downloadWriters = new Map();
  const downloadDestinationTails = new Map();
  const directoryIds = new WeakMap();
  let controller = null;
  let directory = null;
  let stopped = false;
  let nextLocalId = 0;
  let nextDirectoryId = 0;
  let workersRunningGeneration = null;
  let controllerGeneration = 0;
  let pollWake = null;
  const downloadKey = (generation, id) => `download-${generation}-${id}`;
  const slotKey = (generation, slot) => `${generation}:${slot}`;
  const destinationKey = (targetDirectory, name) => {
    if ((typeof targetDirectory === "object" && targetDirectory) || typeof targetDirectory === "function") {
      if (!directoryIds.has(targetDirectory)) directoryIds.set(targetDirectory, ++nextDirectoryId);
      return `${directoryIds.get(targetDirectory)}:${name}`;
    }
    return `unknown:${name}`;
  };
  const wakePoll = () => {
    const wake = pollWake;
    pollWake = null;
    wake?.();
  };
  const hasActiveTransfers = () => uploadQueue.length > 0 ||
    [...transfers.values()].some((transfer) =>
      transfer.state === "queued" || transfer.state === "hashing" || transfer.state === "active");
  const pollIsArmed = () => Boolean(directory) || hasActiveTransfers();

  // FileSystemWritableFileStream commits its replacement on close. Two generations closing the
  // same destination out of order can therefore let an old download overwrite a newer one even if
  // every RPC/UI mutation is generation-guarded. Reserve a destination before createWritable and
  // hold it through the writer's terminal close/abort operation.
  async function acquireDownloadDestination(targetDirectory, name) {
    const key = destinationKey(targetDirectory, name);
    const previous = downloadDestinationTails.get(key) ?? Promise.resolve();
    let releasePromise;
    const released = new Promise((resolve) => { releasePromise = resolve; });
    const tail = previous.catch(() => {}).then(() => released);
    downloadDestinationTails.set(key, tail);
    await previous.catch(() => {});
    let didRelease = false;
    return () => {
      if (didRelease) return;
      didRelease = true;
      releasePromise();
      void tail.then(() => {
        if (downloadDestinationTails.get(key) === tail) downloadDestinationTails.delete(key);
      });
    };
  }

  async function runDownloadWriterOperation(writer, operation) {
    if (writer.terminalPromise) throw new Error("download writer is already settling");
    const active = Promise.resolve().then(operation);
    writer.operationPromise = active;
    try {
      return await active;
    } finally {
      if (writer.operationPromise === active) writer.operationPromise = null;
    }
  }

  function settleDownloadWriter(writer, method, reason) {
    if (writer.terminalPromise) return writer.terminalPromise;
    const prior = writer.operationPromise ?? Promise.resolve();
    writer.terminalPromise = prior.catch(() => {}).then(() => {
      const operation = writer.writable?.[method];
      if (typeof operation === "function") return operation.call(writer.writable, reason);
      return undefined;
    }).finally(() => {
      const release = writer.releaseDestination;
      writer.releaseDestination = null;
      release?.();
    });
    return writer.terminalPromise;
  }

  const render = () => {
    list.replaceChildren(
      ...[...transfers.values()].map((transfer) =>
        transferRow(document, transfer, () => cancelTransfer(transfer))),
    );
  };

  const setStatus = (message, state = "") => {
    status.textContent = message;
    status.dataset.state = state;
  };

  const fail = (transfer, error) => {
    transfer.state = error?.name === "AbortError" ? "partial" : "error";
    transfer.label = transfer.state === "partial"
      ? `partial — cancelled after ${formatBytes(transfer.done)}`
      : `error — ${error?.message || error}`;
    render();
  };

  const pruneHistory = (incoming) => {
    const target = Math.max(0, MAX_RETAINED_ROWS - incoming);
    for (const [key, transfer] of transfers) {
      if (transfers.size <= target) break;
      if (transfer.state === "complete" || transfer.state === "partial" || transfer.state === "error") {
        transfers.delete(key);
      }
    }
  };

  async function waitForSlot(signal) {
    while (!signal.aborted) {
      if (!controller) throw new Error("Boot Alpine before uploading files");
      const currentController = controller;
      const generation = controllerGeneration;
      for (let slot = 0; slot < UPLOAD_WORKERS; slot += 1) {
        const claim = slotKey(generation, slot);
        const ready = !claimedSlots.has(claim) && await currentController.fileTransferReady(slot);
        if (currentController !== controller || generation !== controllerGeneration) break;
        if (ready) {
          claimedSlots.add(claim);
          return { slot, claim, currentController, generation };
        }
      }
      await delay();
    }
    throw new DOMException("Upload cancelled", "AbortError");
  }

  async function waitForUploadState(currentController, generation, stream, signal) {
    while (!signal.aborted) {
      const snapshot = await currentController.fileTransferStatus();
      if (currentController !== controller || generation !== controllerGeneration) {
        throw new Error("file-transfer controller changed during upload");
      }
      const current = snapshot.uploads.find((item) => item.id === stream);
      if (current?.state === "complete") return current;
      if (current?.state === "partial") throw new DOMException("Upload cancelled", "AbortError");
      if (current?.state === "error") throw terminalUploadError(current);
      await delay();
    }
    throw new DOMException("Upload cancelled", "AbortError");
  }

  async function uploadFile(file, transfer) {
    let slot = null;
    let slotClaim = null;
    let currentController = null;
    let generation = 0;
    try {
      transfer.state = "hashing";
      transfer.label = "hashing locally";
      render();
      const sha256 = await hashFile(file, FileSha256, transfer.abort.signal);
      transfer.state = "queued";
      transfer.label = "waiting for guest agent";
      render();
      ({ slot, claim: slotClaim, currentController, generation } = await waitForSlot(transfer.abort.signal));
      transfer.ownerController = currentController;
      transfer.ownerGeneration = generation;
      transfer.state = "active";
      transfer.label = "uploading";
      transfer.stream = await currentController.beginFileUpload(slot, file.name, file.size, sha256);
      if (currentController !== controller || generation !== controllerGeneration) {
        throw new Error("file-transfer controller changed during upload");
      }
      render();

      const reader = file.stream().getReader();
      try {
        while (true) {
          if (transfer.abort.signal.aborted) {
            throw new DOMException("Upload cancelled", "AbortError");
          }
          const { done, value } = await reader.read();
          if (done) break;
          while (true) {
            const snapshot = await currentController.fileTransferStatus();
            if (currentController !== controller || generation !== controllerGeneration) {
              throw new Error("file-transfer controller changed during upload");
            }
            const current = snapshot.uploads.find((item) => item.id === transfer.stream);
            if (!current || current.buffered + value.byteLength <= snapshot.maxBuffered) break;
            if (current.state === "error") throw terminalUploadError(current);
            await delay();
          }
          await currentController.pushFileUpload(transfer.stream, value, false);
          if (transfer.abort.signal.aborted) throw new DOMException("Upload cancelled", "AbortError");
          if (currentController !== controller || generation !== controllerGeneration) {
            throw new Error("file-transfer controller changed during upload");
          }
          transfer.done += value.byteLength;
          render();
        }
      } finally {
        reader.releaseLock();
      }
      await currentController.pushFileUpload(transfer.stream, new Uint8Array(), true);
      await waitForUploadState(currentController, generation, transfer.stream, transfer.abort.signal);
      transfer.done = transfer.total;
      transfer.state = "complete";
      transfer.label = "complete — SHA-256 verified";
      render();
    } catch (caught) {
      let error = caught;
      if (transfer.stream != null && currentController) {
        try {
          const terminal = (await currentController.fileTransferStatus()).uploads
            .find((item) => item.id === transfer.stream);
          if (terminal?.diagnostic) {
            transfer.diagnostic = terminal.diagnostic;
            if (caught?.name !== "AbortError") error = terminalUploadError(terminal);
          }
        } catch {}
      }
      if (transfer.stream != null) {
        try { await currentController?.cancelFileUpload(transfer.stream); } catch {}
      }
      fail(transfer, error);
    } finally {
      if (transfer.stream != null) {
        try { await currentController?.dismissFileUpload(transfer.stream); } catch {}
      }
      if (slotClaim != null) claimedSlots.delete(slotClaim);
    }
  }

  async function runUploadWorkers() {
    const poolGeneration = controllerGeneration;
    if (workersRunningGeneration === poolGeneration) return;
    workersRunningGeneration = poolGeneration;
    const worker = async () => {
      while (uploadQueue.length) {
        const item = uploadQueue.shift();
        await uploadFile(item.file, item.transfer);
      }
    };
    await Promise.all(Array.from({ length: UPLOAD_WORKERS }, worker));
    if (workersRunningGeneration === poolGeneration) workersRunningGeneration = null;
    if (uploadQueue.length) void runUploadWorkers();
  }

  function enqueueFiles(files) {
    const selected = [...files];
    const outstanding = [...transfers.values()].filter(
      (transfer) =>
        transfer.direction === "upload" &&
        (transfer.state === "queued" || transfer.state === "hashing" || transfer.state === "active"),
    ).length;
    if (selected.length > MAX_SELECTED_FILES || outstanding + selected.length > MAX_SELECTED_FILES) {
      setStatus(
        `Selection rejected: ${outstanding + selected.length} outstanding files exceeds the ${MAX_SELECTED_FILES}-file bounded queue.`,
        "error",
      );
      return false;
    }
    pruneHistory(selected.length);
    for (const file of selected) {
      const transfer = {
        key: `upload-${++nextLocalId}`,
        direction: "upload",
        name: file.name,
        total: file.size,
        done: 0,
        state: "queued",
        label: "queued",
        abort: new AbortController(),
        stream: null,
        ownerController: null,
        ownerGeneration: 0,
      };
      transfers.set(transfer.key, transfer);
      uploadQueue.push({ file, transfer });
    }
    render();
    setStatus(`${selected.length} upload${selected.length === 1 ? "" : "s"} queued.`);
    wakePoll();
    void runUploadWorkers();
    return true;
  }

  async function openDownloadWriter(record, currentController, generation) {
    const key = downloadKey(generation, record.id);
    const targetDirectory = directory;
    if (downloadWriters.has(key) || !targetDirectory) return;
    const transfer = transfers.get(key);
    if (!transfer || transfer.state === "complete" || transfer.state === "partial" || transfer.state === "error") {
      return;
    }
    // Reserve the ID before either awaited picker call. The monitor can poll again while the
    // browser is opening the handle; without this reservation two writers can race, and the
    // empty loser may truncate a download that the winner just completed.
    const reservation = {
      writable: null,
      busy: true,
      operationPromise: null,
      terminalPromise: null,
      releaseDestination: null,
    };
    downloadWriters.set(key, reservation);
    try {
      const handle = await targetDirectory.getFileHandle(record.name, { create: true });
      if (
        currentController !== controller ||
        generation !== controllerGeneration ||
        downloadWriters.get(key) !== reservation
      ) return;
      reservation.releaseDestination = await acquireDownloadDestination(targetDirectory, record.name);
      if (
        currentController !== controller ||
        generation !== controllerGeneration ||
        downloadWriters.get(key) !== reservation
      ) {
        reservation.releaseDestination();
        reservation.releaseDestination = null;
        return;
      }
      const writable = await handle.createWritable();
      reservation.writable = writable;
      if (
        currentController !== controller ||
        generation !== controllerGeneration ||
        downloadWriters.get(key) !== reservation
      ) {
        await settleDownloadWriter(reservation, "abort", "file-transfer controller changed");
        return;
      }
      reservation.busy = false;
      transfer.label = "downloading";
      render();
    } catch (error) {
      if (reservation.writable) {
        try { await settleDownloadWriter(reservation, "abort", error); } catch {}
      } else if (reservation.releaseDestination) {
        reservation.releaseDestination();
        reservation.releaseDestination = null;
      }
      if (downloadWriters.get(key) === reservation) downloadWriters.delete(key);
      if (currentController !== controller || generation !== controllerGeneration) return;
      try { await currentController.cancelFileDownload(record.id); } catch {}
      fail(transfer, error);
    }
  }

  async function drainDownload(record, currentController, generation) {
    const key = downloadKey(generation, record.id);
    const writer = downloadWriters.get(key);
    const transfer = transfers.get(key);
    if (!writer?.writable || writer.busy || !transfer) return;
    const stale = () => currentController !== controller || generation !== controllerGeneration;
    writer.busy = true;
    try {
      while (true) {
        const chunk = await currentController.takeFileDownloadChunk(record.id);
        if (stale()) return;
        if (!chunk.byteLength) break;
        await runDownloadWriterOperation(writer, () => writer.writable.write(chunk));
        if (stale()) return;
        transfer.done += chunk.byteLength;
        render();
      }
      if (record.state === "awaiting-save" && record.buffered === 0) {
        await settleDownloadWriter(writer, "close");
        if (stale()) return;
        await currentController.finishFileDownload(record.id, true);
        if (stale()) return;
        await currentController.dismissFileDownload(record.id);
        if (stale()) return;
        transfer.done = transfer.total;
        transfer.state = "complete";
        transfer.label = "complete — SHA-256 verified";
        downloadWriters.delete(key);
        render();
      } else if (record.state === "partial") {
        await settleDownloadWriter(writer, "abort", "guest cancelled transfer");
        if (stale()) return;
        await currentController.dismissFileDownload(record.id);
        if (stale()) return;
        downloadWriters.delete(key);
        transfer.state = "partial";
        transfer.label = `partial — cancelled after ${formatBytes(transfer.done)}`;
        render();
      }
    } catch (error) {
      if (stale()) return;
      try { await settleDownloadWriter(writer, "abort", error); } catch {}
      if (stale()) return;
      downloadWriters.delete(key);
      try {
        if (record.state === "awaiting-save") await currentController.finishFileDownload(record.id, false);
        else await currentController.cancelFileDownload(record.id);
      } catch {}
      if (stale()) return;
      try { await currentController.dismissFileDownload(record.id); } catch {}
      if (stale()) return;
      fail(transfer, error);
    } finally {
      writer.busy = false;
    }
  }

  function syncDownloads(snapshot, currentController, generation) {
    for (const record of snapshot.downloads) {
      const key = downloadKey(generation, record.id);
      if (!transfers.has(key)) {
        transfers.set(key, {
          key,
          id: record.id,
          generation,
          direction: "download",
          name: record.name,
          total: record.total,
          done: 0,
          state: "active",
          label: directory ? "starting download" : "waiting for download folder",
        });
        render();
      }
      const transfer = transfers.get(key);
      if (
        directory &&
        transfer.state !== "complete" &&
        transfer.state !== "partial" &&
        transfer.state !== "error"
      ) {
        void openDownloadWriter(record, currentController, generation)
          .then(() => drainDownload(record, currentController, generation));
      }
    }
  }

  async function poll() {
    while (!stopped) {
      // An attached controller alone is idle: do not serialize status and enqueue a Worker RPC
      // forever when the user never enabled downloads or queued an upload. Choosing a destination
      // arms guest-initiated download discovery; an upload/active transfer also wakes the monitor.
      if (!pollIsArmed()) {
        await new Promise((resolve) => { pollWake = resolve; });
        continue;
      }
      try {
        if (controller) {
          const currentController = controller;
          const generation = controllerGeneration;
          const snapshot = await currentController.fileTransferStatus();
          if (currentController !== controller || generation !== controllerGeneration) continue;
          syncDownloads(snapshot, currentController, generation);
          await Promise.all(snapshot.downloads.map((record) =>
            drainDownload(record, currentController, generation)));
        }
      } catch (error) {
        setStatus(`File transfer monitor error: ${error?.message || error}`, "error");
      }
      const active = hasActiveTransfers();
      await delay(active ? POLL_MS : 500);
    }
  }

  function cancelTransfer(transfer) {
    if (transfer.direction === "upload") {
      transfer.abort.abort();
      if (transfer.stream != null) {
        const owner = transfer.ownerController;
        ignoreRejection(() => owner?.cancelFileUpload(transfer.stream));
      }
    } else {
      ignoreRejection(() => controller?.cancelFileDownload(transfer.id));
    }
    transfer.state = "partial";
    transfer.label = `partial — cancelled after ${formatBytes(transfer.done)}`;
    render();
  }

  function containsDirectory(dataTransfer) {
    return [...(dataTransfer?.items || [])].some((item) => item.webkitGetAsEntry?.()?.isDirectory);
  }

  choose.addEventListener("click", () => input.click());
  input.addEventListener("change", () => {
    enqueueFiles(input.files || []);
    input.value = "";
  });
  for (const type of ["dragenter", "dragover"]) {
    drop.addEventListener(type, (event) => {
      event.preventDefault();
      drop.classList.add("dragging");
    });
  }
  for (const type of ["dragleave", "drop"]) {
    drop.addEventListener(type, (event) => {
      event.preventDefault();
      drop.classList.remove("dragging");
    });
  }
  drop.addEventListener("drop", (event) => {
    if (containsDirectory(event.dataTransfer)) {
      setStatus("Directories are rejected; select files only.", "error");
      return;
    }
    enqueueFiles(event.dataTransfer?.files || []);
  });
  drop.addEventListener("keydown", (event) => {
    if (event.key === "Enter" || event.key === " ") {
      event.preventDefault();
      input.click();
    }
  });
  chooseDownload.addEventListener("click", async () => {
    try {
      directory = await openDirectory();
      await controller?.setFileDownloadReady(true);
      wakePoll();
      setStatus(`Downloads stream directly into “${directory.name || "selected folder"}”.`, "ready");
    } catch (error) {
      if (error?.name !== "AbortError") setStatus(`Cannot open download folder: ${error?.message || error}`, "error");
    }
  });

  void poll();
  return {
    attachController(next) {
      const previous = controller;
      if (previous !== next) {
        controllerGeneration += 1;
        if (previous) ignoreRejection(() => previous.setFileDownloadReady(false));
        for (const writer of downloadWriters.values()) {
          if (writer.writable) {
            ignoreRejection(() => settleDownloadWriter(
              writer,
              "abort",
              "file-transfer controller changed",
            ));
          }
        }
        downloadWriters.clear();
        let changed = false;
        for (const transfer of transfers.values()) {
          if (transfer.direction === "upload" &&
              (transfer.state === "queued" || transfer.state === "hashing" || transfer.state === "active")) {
            transfer.abort.abort();
            transfer.state = "partial";
            transfer.label = `partial — controller changed after ${formatBytes(transfer.done)}`;
            changed = true;
          }
          if (transfer.direction === "download" && transfer.state === "active") {
            transfer.state = "partial";
            transfer.label = `partial — controller changed after ${formatBytes(transfer.done)}`;
            changed = true;
          }
        }
        if (changed) render();
      }
      controller = next;
      // Old-generation workers may be stuck inside an uncooperative controller Promise even after
      // their AbortSignal fires. A generation-owned pool lets fresh uploads start immediately; late
      // old finally blocks release only their generation-qualified slot claims.
      if (uploadQueue.length) void runUploadWorkers();
      if (controller) ignoreRejection(() => controller.setFileDownloadReady(Boolean(directory)));
      setStatus(
        next
          ? "WVFT controller attached; uploads wait for two bounded guest-agent connections."
          : "Boot Alpine to enable WVFT.",
        next ? "ready" : "",
      );
    },
    enqueueFiles,
    setDownloadDirectory(next) {
      directory = next;
      ignoreRejection(() => controller?.setFileDownloadReady(Boolean(directory)));
      if (directory) wakePoll();
    },
    snapshot: () => [...transfers.values()].map(({ abort, ownerController, ...transfer }) => ({ ...transfer })),
    stop() {
      stopped = true;
      wakePoll();
    },
  };
}

// E5-T12c: keyboard capture policy for the browser-facing guest input surface.
// The policy is deliberately independent from the evdev bridge so it can be attacked with plain
// KeyboardEvent-shaped fixtures and so browser-default decisions remain auditable.

const MODIFIER_CODES = new Set([
  "ShiftLeft",
  "ShiftRight",
  "ControlLeft",
  "ControlRight",
  "AltLeft",
  "AltRight",
  "MetaLeft",
  "MetaRight",
]);

const MODIFIER_FLAGS = Object.freeze({
  Control: "ctrlKey",
  Meta: "metaKey",
  Alt: "altKey",
  Shift: "shiftKey",
});

const RESERVED_VIEW_TOGGLE = Object.freeze({
  code: "Backquote",
  modifiers: Object.freeze(["Control", "Alt"]),
});

/** Browser-owned shortcuts are intentionally not promised to the guest. */
export const DEFAULT_PASSTHROUGH = Object.freeze([
  Object.freeze({ code: "KeyW", modifiers: Object.freeze(["Control"]) }),
  Object.freeze({ code: "KeyT", modifiers: Object.freeze(["Control"]) }),
  Object.freeze({ code: "KeyN", modifiers: Object.freeze(["Control"]) }),
  Object.freeze({ code: "KeyQ", modifiers: Object.freeze(["Meta"]) }),
  Object.freeze({ code: "Tab", modifiers: Object.freeze(["Meta"]) }),
  Object.freeze({ code: "F11", modifiers: Object.freeze([]) }),
]);

const IME_KEY_CODE = 229;

function codeOf(event) {
  return typeof event?.code === "string" ? event.code : "";
}

function isModifierCode(code) {
  return MODIFIER_CODES.has(code);
}

function pendingHasModifier(pending, kind) {
  const prefix = kind === "Control" ? "Control"
    : kind === "Meta" ? "Meta"
      : kind === "Alt" ? "Alt" : "Shift";
  for (const code of pending.keys()) {
    if (code.startsWith(prefix)) return true;
  }
  return false;
}

function modifierIsDown(event, pending, kind) {
  return Boolean(event?.[MODIFIER_FLAGS[kind]]) || pendingHasModifier(pending, kind);
}

function isImeEvent(event) {
  return event?.isComposing === true
    || Number(event?.keyCode) === IME_KEY_CODE
    || Number(event?.which) === IME_KEY_CODE;
}

function normalizeRules(rules) {
  return [...(rules ?? [])].map((rule) => {
    if (typeof rule === "function") return rule;
    if (typeof rule === "string") return (event) => codeOf(event) === rule;
    if (!rule || typeof rule.code !== "string") {
      throw new TypeError("keyboard passthrough rules require a code or predicate");
    }
    const modifiers = [...(rule.modifiers ?? [])];
    for (const modifier of modifiers) {
      if (!(modifier in MODIFIER_FLAGS)) {
        throw new TypeError(`unknown keyboard passthrough modifier: ${modifier}`);
      }
    }
    return (event, pending) => codeOf(event) === rule.code &&
      modifiers.every((modifier) => modifierIsDown(event, pending, modifier));
  });
}

function callSafely(callback, value, onError, errorReason) {
  try {
    callback(value);
    return true;
  } catch (error) {
    onError(errorReason, value, error);
    return false;
  }
}

function makeResult(code, reason, extra = {}) {
  return {
    captured: extra.captured ?? true,
    prevented: extra.prevented ?? false,
    forwarded: extra.forwarded ?? false,
    reserved: extra.reserved ?? false,
    passthrough: extra.passthrough ?? false,
    code,
    reason,
    ...extra,
  };
}

/**
 * Create the deterministic browser-default policy around the T12b physical keyboard bridge.
 *
 * Modifiers are held as prefixes until a dependent key arrives. This is important for reserved
 * and browser-owned chords: ControlLeft + AltLeft must never leak to the guest before
 * Ctrl+Alt+Backquote is recognized as the T08 view-toggle hook.
 */
export function createKeyboardCapturePolicy({
  initialCaptured = true,
  onGuestEvent = () => {},
  onReserved = () => {},
  onDiagnostic = () => {},
  onStateChange = () => {},
  preserveDefault = () => false,
  passthrough = DEFAULT_PASSTHROUGH,
} = {}) {
  let captured = Boolean(initialCaptured);
  const pendingModifiers = new Map();
  const passthroughHeld = new Set();
  const reservedHeld = new Set();
  const rules = normalizeRules(passthrough);

  function diagnostic(reason, event, error = undefined) {
    callSafely(onDiagnostic, {
      reason,
      code: codeOf(event),
      eventType: event?.type ?? "",
      ...(error ? { error: error?.message || String(error) } : {}),
    }, () => {}, "diagnostic-callback-error");
  }

  function prevent(event) {
    try {
      if (preserveDefault(event)) return false;
    } catch (error) {
      diagnostic("preserve-default-error", event, error);
    }
    if (typeof event?.preventDefault !== "function") return false;
    try {
      event.preventDefault();
      return true;
    } catch (error) {
      diagnostic("prevent-default-error", event, error);
      return false;
    }
  }

  function stopPropagation(event) {
    if (typeof event?.stopImmediatePropagation !== "function") return;
    try { event.stopImmediatePropagation(); } catch (error) {
      diagnostic("stop-propagation-error", event, error);
    }
  }

  function guest(event) {
    return callSafely(onGuestEvent, event, (reason, value, error) => {
      diagnostic(reason, value, error);
    }, "guest-callback-error");
  }

  function pendingCodes() {
    return [...pendingModifiers.keys()];
  }

  function clearTransientState() {
    pendingModifiers.clear();
    passthroughHeld.clear();
    reservedHeld.clear();
  }

  function stateChanged() {
    callSafely(onStateChange, captured, () => {}, "state-callback-error");
  }

  function matchesPassthrough(event) {
    return rules.some((rule) => {
      try {
        return Boolean(rule(event, pendingModifiers));
      } catch (error) {
        diagnostic("passthrough-rule-error", event, error);
        return false;
      }
    });
  }

  function matchesReserved(event) {
    if (codeOf(event) !== RESERVED_VIEW_TOGGLE.code) return false;
    if (event?.shiftKey || event?.metaKey) return false;
    return modifierIsDown(event, pendingModifiers, "Control") &&
      modifierIsDown(event, pendingModifiers, "Alt");
  }

  function prefixCodesForChord() {
    const codes = pendingCodes();
    // A synthetic or browser-recovered event may expose modifier flags without a preceding DOM
    // keydown. There is no physical code to track in that case, so only real pending prefixes are
    // suppressed and the trigger itself remains the complete ownership record.
    return codes;
  }

  function flushModifiers() {
    let forwarded = false;
    for (const event of pendingModifiers.values()) forwarded = guest(event) || forwarded;
    pendingModifiers.clear();
    return forwarded;
  }

  function handleCaptured(event) {
    const code = codeOf(event);
    const eventType = event?.type;
    const modifier = isModifierCode(code);

    if (isImeEvent(event)) {
      diagnostic("ime-event", event);
      return makeResult(code, "ime-event", { captured, passthrough: true });
    }

    if (eventType === "keydown") {
      if (reservedHeld.has(code)) {
        return makeResult(code, "reserved-held", { captured, reserved: true });
      }
      if (passthroughHeld.has(code)) {
        return makeResult(code, "passthrough-held", { captured, passthrough: true });
      }
      if (matchesReserved(event)) {
        for (const prefix of prefixCodesForChord()) reservedHeld.add(prefix);
        pendingModifiers.clear();
        reservedHeld.add(code);
        stopPropagation(event);
        callSafely(onReserved, event, (reason, value, error) => {
          diagnostic(reason, value, error);
        }, "reserved-callback-error");
        return makeResult(code, "reserved-view-toggle", {
          captured,
          reserved: true,
        });
      }
      if (matchesPassthrough(event)) {
        for (const prefix of prefixCodesForChord()) passthroughHeld.add(prefix);
        pendingModifiers.clear();
        passthroughHeld.add(code);
        stopPropagation(event);
        return makeResult(code, "browser-passthrough", {
          captured,
          passthrough: true,
        });
      }
      if (modifier) {
        if (event?.repeat === true || pendingModifiers.has(code)) {
          diagnostic(event?.repeat === true ? "repeat-modifier" : "duplicate-modifier", event);
          return makeResult(code, event?.repeat === true ? "repeat-modifier" : "duplicate-modifier", {
            captured,
            prevented: false,
          });
        }
        pendingModifiers.set(code, event);
        // Do not cancel a modifier before we know whether it prefixes a browser-owned shortcut.
        // Modifiers have no useful standalone browser default; the dependent key receives the
        // ordinary captured decision once the chord is known.
        return makeResult(code, "modifier-prefix", { captured, prevented: false });
      }
      const prevented = prevent(event);
      const flushed = flushModifiers();
      const forwarded = guest(event) || flushed;
      return makeResult(code, "captured-keydown", { captured, prevented, forwarded });
    }

    if (eventType === "keyup") {
      if (reservedHeld.has(code)) {
        reservedHeld.delete(code);
        return makeResult(code, "reserved-keyup", { captured, reserved: true });
      }
      if (passthroughHeld.has(code)) {
        passthroughHeld.delete(code);
        return makeResult(code, "passthrough-keyup", { captured, passthrough: true });
      }
      if (modifier && pendingModifiers.has(code)) {
        pendingModifiers.delete(code);
        return makeResult(code, "modifier-prefix-keyup", { captured, prevented: false });
      }
      const prevented = prevent(event);
      const forwarded = guest(event);
      return makeResult(code, "captured-keyup", { captured, prevented, forwarded });
    }

    diagnostic("unsupported-event", event);
    return makeResult(code, "unsupported-event", { captured });
  }

  function handleKeyEvent(event) {
    const code = codeOf(event);
    if (event?.type !== "keydown" && event?.type !== "keyup") {
      diagnostic("unsupported-event", event);
      return makeResult(code, "unsupported-event", { captured });
    }
    if (!captured) return makeResult(code, "capture-off", { captured: false });
    return handleCaptured(event);
  }

  function setCaptured(value) {
    const next = Boolean(value);
    if (captured === next) return captured;
    captured = next;
    clearTransientState();
    stateChanged();
    return captured;
  }

  function toggle() {
    return setCaptured(!captured);
  }

  stateChanged();

  return {
    handleKeyEvent,
    isCaptured: () => captured,
    setCaptured,
    toggle,
    pendingModifierCodes: pendingCodes,
    passthroughCodes: () => [...passthroughHeld],
    reservedCodes: () => [...reservedHeld],
    clearTransientState,
  };
}

/** Attach policy listeners without hiding the policy's preventDefault decision. */
export function attachKeyboardCapture(target, policy, options = { capture: true }) {
  if (!target || typeof target.addEventListener !== "function") {
    throw new TypeError("keyboard capture target must support addEventListener");
  }
  if (typeof policy?.handleKeyEvent !== "function") {
    throw new TypeError("keyboard capture policy requires handleKeyEvent");
  }
  const listener = (event) => policy.handleKeyEvent(event);
  target.addEventListener("keydown", listener, options);
  target.addEventListener("keyup", listener, options);
  return () => {
    target.removeEventListener?.("keydown", listener, options);
    target.removeEventListener?.("keyup", listener, options);
  };
}

// E5-T13a: the host-side ledger for physical keys believed held by the guest.
// Keep this module independent from DOM and evdev details so lifecycle cleanup can be tested with
// synthetic targets and reused by the browser integration.

function report(onDiagnostic, reason, code = "") {
  try { onDiagnostic({ reason, code }); } catch { /* diagnostics never break input cleanup */ }
}

/**
 * Track physical key state with idempotent make/break operations.
 *
 * Values are deliberately opaque to the ledger. The keyboard bridge stores evdev/modifier
 * metadata there, while tests and future input devices can store their own release information.
 */
export function createHeldKeyLedger({ onDiagnostic = () => {}, onRelease = () => {} } = {}) {
  const held = new Map();

  function press(code, value = {}) {
    if (typeof code !== "string" || code.length === 0) {
      report(onDiagnostic, "invalid-key-code", typeof code === "string" ? code : "");
      return { accepted: false, code: typeof code === "string" ? code : "", reason: "invalid-key-code" };
    }
    const prior = held.get(code);
    if (prior !== undefined) {
      report(onDiagnostic, "duplicate-keydown", code);
      return { accepted: false, code, value: prior, reason: "duplicate-keydown" };
    }
    held.set(code, value);
    return { accepted: true, code, value };
  }

  function release(code) {
    if (!held.has(code)) {
      report(onDiagnostic, "orphan-keyup", typeof code === "string" ? code : "");
      return null;
    }
    const value = held.get(code);
    held.delete(code);
    return value;
  }

  function releaseAll(callback = onRelease) {
    if (typeof callback !== "function") throw new TypeError("releaseAll callback must be a function");

    const order = [...held.entries()];
    const records = [];
    // Release dependent keys before modifiers, and unwind each group in reverse make order.
    for (const modifier of [false, true]) {
      for (const [code, value] of [...order].reverse()) {
        if (Boolean(value?.modifier) !== modifier || !held.has(code)) continue;
        records.push({ code, value });
      }
    }
    // Clear before callbacks so a re-entrant lifecycle notification cannot emit a second break.
    for (const { code } of records) held.delete(code);
    for (const { code, value } of records) callback(code, value);
    return records;
  }

  function reset() {
    const records = [...held.entries()].map(([code, value]) => ({ code, value }));
    held.clear();
    return records;
  }

  return {
    press,
    release,
    releaseAll,
    reset,
    has: (code) => held.has(code),
    get: (code) => held.get(code),
    entries: () => [...held.entries()],
    codes: () => [...held.keys()],
    snapshot: () => [...held.entries()].map(([code, value]) => ({ code, value })),
    size: () => held.size,
  };
}

function addListener(registrations, target, type, listener) {
  if (!target || typeof target.addEventListener !== "function") return;
  target.addEventListener(type, listener);
  registrations.push({ target, type, listener });
}

/**
 * Attach every host lifecycle boundary that can strand a physical key.
 * The callback receives a reason string and should call the bridge's releaseAll method.
 */
export function attachHeldKeyLifecycle({
  windowTarget = globalThis.window,
  documentTarget = globalThis.document,
  viewTarget = windowTarget ?? documentTarget,
  releaseAll,
  isPointerLocked = () => Boolean(documentTarget?.pointerLockElement),
  viewToggleEvent = "wvm:reserved-view-toggle",
} = {}) {
  if (typeof releaseAll !== "function") throw new TypeError("lifecycle hooks require releaseAll");

  const registrations = [];
  const trigger = (reason) => releaseAll(reason);
  addListener(registrations, windowTarget, "blur", () => trigger("blur"));
  addListener(registrations, documentTarget, "visibilitychange", () => {
    if (documentTarget?.hidden === true || documentTarget?.visibilityState === "hidden") {
      trigger("visibility-hidden");
    }
  });
  addListener(registrations, documentTarget, "pointerlockchange", () => {
    let locked = false;
    try { locked = Boolean(isPointerLocked()); } catch { /* a lost target is unlocked */ }
    if (!locked) trigger("pointerlock-lost");
  });
  addListener(registrations, viewTarget, viewToggleEvent, () => trigger("view-toggle"));

  return () => {
    for (const { target, type, listener } of registrations.splice(0).reverse()) {
      target.removeEventListener?.(type, listener);
    }
  };
}

// E5-T13b: modifier and lock-key reconciliation layered on the T12b keyboard bridge.
// The module is synchronous by design: callers provide the latest host modifier observation and
// a cached T11 LED observation, so every repair is ordered before the triggering DOM event.

const MODIFIER_GROUPS = Object.freeze([
  Object.freeze({ kind: "Control", codes: Object.freeze(["ControlLeft", "ControlRight"]) }),
  Object.freeze({ kind: "Alt", codes: Object.freeze(["AltLeft", "AltRight"]) }),
  Object.freeze({ kind: "Shift", codes: Object.freeze(["ShiftLeft", "ShiftRight"]) }),
  Object.freeze({ kind: "Meta", codes: Object.freeze(["MetaLeft", "MetaRight"]) }),
]);

const LOCKS = Object.freeze([
  Object.freeze({ kind: "CapsLock", code: "CapsLock", state: "capsLock" }),
  Object.freeze({ kind: "NumLock", code: "NumLock", state: "numLock" }),
]);

function codeOf(event) {
  return typeof event?.code === "string" ? event.code : "";
}

function safeCallback(callback, value) {
  try { callback(value); } catch { /* reconciliation telemetry cannot break input */ }
}

function booleanValue(value) {
  return typeof value === "boolean" ? value : null;
}

function readModifier(event, kind, getModifierState) {
  try {
    const provided = getModifierState?.(event, kind);
    if (typeof provided === "boolean") return provided;
  } catch {
    // Fall through to the native KeyboardEvent method and report no observation if it also fails.
  }
  try {
    const native = event?.getModifierState?.(kind);
    return booleanValue(native);
  } catch {
    return null;
  }
}

function readLockState(value, getHostLockState, getModifierState) {
  if (value && typeof value === "object" &&
      ("capsLock" in value || "numLock" in value)) return value;
  try {
    const provided = getHostLockState?.(value);
    if (provided && typeof provided === "object") return provided;
  } catch {
    // Fall through to the KeyboardEvent modifier-state API.
  }
  const state = {};
  let observed = false;
  for (const lock of LOCKS) {
    const valueForLock = readModifier(value, lock.kind, getModifierState);
    if (valueForLock !== null) {
      state[lock.state] = valueForLock;
      observed = true;
    }
  }
  return observed ? state : null;
}

function guestLedValue(guest, state) {
  if (!guest || typeof guest !== "object") return null;
  return booleanValue(guest[state]);
}

/**
 * Wrap a T12b bridge with focus-recovery reconciliation.
 *
 * `getGuestLedState` should return the latest synchronous T11 LED snapshot. A pending repair is
 * suppressed until that snapshot reports the requested state, which prevents a slow statusq from
 * turning one divergence into an oscillating stream of CapsLock/NumLock pairs.
 */
export function createKeyboardReconciler(
  bridge,
  {
    getModifierState,
    getGuestLedState = () => null,
    getHostLockState,
    onDiagnostic = () => {},
    onStatsChange = () => {},
  } = {},
) {
  if (typeof bridge?.handleKeyEvent !== "function" || typeof bridge?.heldCodes !== "function") {
    throw new TypeError("keyboard reconciler requires a T12 keyboard bridge");
  }

  let modifierRepairs = 0;
  let lockRepairs = 0;
  const pendingLockRepairs = new Map();

  function diagnostic(reason, extra = {}) {
    safeCallback(onDiagnostic, { reason, ...extra });
  }

  function stats() {
    return {
      modifierRepairs,
      lockRepairs,
      pendingLockRepairs: [...pendingLockRepairs.entries()].map(([kind, value]) => ({ kind, value })),
    };
  }

  function notifyStats() {
    safeCallback(onStatsChange, stats());
  }

  function reconcileModifiers(event) {
    if (event?.type !== "keydown" && event?.type !== "keyup") return [];
    const corrections = [];
    for (const group of MODIFIER_GROUPS) {
      const desired = readModifier(event, group.kind, getModifierState);
      if (desired === null || group.codes.includes(codeOf(event))) continue;
      const held = bridge.heldCodes().filter((code) => group.codes.includes(code));
      if (desired && held.length === 0) {
        const synthetic = bridge.handleKeyEvent({
          type: "keydown",
          code: group.codes[0],
          repeat: false,
          reconciliation: true,
        });
        corrections.push(synthetic);
        if (synthetic.forwarded) {
          modifierRepairs += 1;
          diagnostic("modifier-reconciled-down", { kind: group.kind, code: group.codes[0] });
        }
      } else if (!desired && held.length > 0) {
        for (const code of [...held].reverse()) {
          const synthetic = bridge.handleKeyEvent({
            type: "keyup",
            code,
            reconciliation: true,
          });
          corrections.push(synthetic);
          if (synthetic.forwarded || synthetic.reason === "modifier-release-deferred") {
            modifierRepairs += 1;
            diagnostic("modifier-reconciled-up", { kind: group.kind, code });
          }
        }
      }
    }
    if (corrections.length > 0) notifyStats();
    return corrections;
  }

  function reconcileLocks(hostOrEvent = undefined, { skipCode = "" } = {}) {
    const host = readLockState(hostOrEvent, getHostLockState, getModifierState);
    if (!host) return [];
    let guest;
    try { guest = getGuestLedState?.(); } catch { guest = null; }
    const corrections = [];
    for (const lock of LOCKS) {
      if (skipCode === lock.code) continue;
      const desired = booleanValue(host[lock.state]);
      const observed = guestLedValue(guest, lock.state);
      if (desired === null || observed === null) continue;
      if (observed === desired) {
        pendingLockRepairs.delete(lock.kind);
        continue;
      }
      if (pendingLockRepairs.get(lock.kind) === desired) continue;

      const down = bridge.handleKeyEvent({ type: "keydown", code: lock.code, repeat: false, reconciliation: true });
      const up = bridge.handleKeyEvent({ type: "keyup", code: lock.code, reconciliation: true });
      corrections.push(down, up);
      pendingLockRepairs.set(lock.kind, desired);
      if (down.forwarded && up.forwarded) {
        lockRepairs += 1;
        diagnostic("lock-reconciled", { kind: lock.kind, desired });
        notifyStats();
      }
    }
    return corrections;
  }

  function handleKeyEvent(event) {
    const corrections = reconcileModifiers(event);
    const lockCorrections = reconcileLocks(event, { skipCode: codeOf(event) });
    const result = bridge.handleKeyEvent(event);
    return { ...result, corrections, lockCorrections };
  }

  return {
    handleKeyEvent,
    reconcileModifiers,
    reconcileLocks,
    stats,
    pendingLockKinds: () => [...pendingLockRepairs.keys()],
  };
}

// E5-T20d: browser autoplay unlock and the suspended-context discard policy.

import { CHANNELS } from "./ring.js";

export const AUTOPLAY_QUANTUM_FRAMES = 128;
export const AUTOPLAY_LOCKED = "locked";
export const AUTOPLAY_UNLOCKING = "unlocking";
export const AUTOPLAY_UNLOCKED = "unlocked";

const MAX_CLOCK_CREDIT_FRAMES = AUTOPLAY_QUANTUM_FRAMES * 4;

const BADGE_TEXT = Object.freeze({
  [AUTOPLAY_LOCKED]: "Audio muted until interaction — click or press a key to enable sound.",
  [AUTOPLAY_UNLOCKING]: "Enabling audio…",
  [AUTOPLAY_UNLOCKED]: "Audio enabled.",
});

function validSampleRate(sampleRateHz) {
  if (!Number.isInteger(sampleRateHz) || sampleRateHz < 1) {
    throw new RangeError("audio autoplay sample rate must be a positive integer");
  }
  return sampleRateHz;
}

function defaultNowMs() {
  const now = globalThis.performance?.now?.();
  return Number.isFinite(now) ? now : Date.now();
}

function defaultSchedule(callback, delayMs) {
  return setTimeout(callback, delayMs);
}

function defaultCancel(handle) {
  clearTimeout(handle);
}

function badgeText(state) {
  return BADGE_TEXT[state] ?? BADGE_TEXT[AUTOPLAY_LOCKED];
}

function renderBadge(badge, state) {
  if (!badge) return;
  badge.dataset.audioState = state;
  badge.setAttribute?.("role", "status");
  badge.setAttribute?.("aria-live", "polite");
  badge.textContent = badgeText(state);
  // A successful unlock clears the muted badge from the page. Locked, retryable, and in-flight
  // states remain visible so a suspended context is never mistaken for working audio.
  badge.hidden = state === AUTOPLAY_UNLOCKED;
}

/**
 * Own the one browser gesture → AudioContext.resume path.
 *
 * While the context is locked or a resume is in flight, `pump()` consumes at most one audio
 * quantum from the optional ring. The frame budget is derived from the negotiated sample rate;
 * a delayed timer contributes credit over later ticks instead of draining a whole backgrounding
 * gap in one call. A successful resume stops this reader before the AudioWorklet starts consuming.
 */
export class AudioAutoplayPolicy {
  constructor({
    context,
    ring = null,
    sampleRateHz = context?.sampleRate,
    badge = null,
    target = typeof document !== "undefined" ? document : null,
    nowMs = defaultNowMs,
    schedule = defaultSchedule,
    cancel = defaultCancel,
    quantumFrames = AUTOPLAY_QUANTUM_FRAMES,
    clockBuffer = null,
    onUnlocked = null,
  } = {}) {
    if (!context || typeof context.resume !== "function") {
      throw new TypeError("audio autoplay policy requires an AudioContext with resume()");
    }
    if (typeof nowMs !== "function") throw new TypeError("nowMs must be a function");
    if (typeof schedule !== "function") throw new TypeError("schedule must be a function");
    if (typeof cancel !== "function") throw new TypeError("cancel must be a function");
    if (!Number.isSafeInteger(quantumFrames) || quantumFrames < 1) {
      throw new RangeError("audio autoplay quantumFrames must be a positive integer");
    }
    if (ring !== null && typeof ring.consumer !== "function") {
      throw new TypeError("audio autoplay ring must expose consumer()");
    }
    if (onUnlocked !== null && typeof onUnlocked !== "function") {
      throw new TypeError("onUnlocked must be a function");
    }

    this.context = context;
    this.ring = ring;
    this.sampleRateHz = validSampleRate(Number(sampleRateHz));
    this.badge = badge;
    this._target = target;
    this._nowMs = nowMs;
    this._schedule = schedule;
    this._cancel = cancel;
    this._quantumFrames = quantumFrames;
    this._quantumMs = (quantumFrames * 1_000) / this.sampleRateHz;
    if (clockBuffer !== null && clockBuffer !== undefined) {
      if (typeof SharedArrayBuffer === "undefined"
        || !(clockBuffer instanceof SharedArrayBuffer)
        || clockBuffer.byteLength < Int32Array.BYTES_PER_ELEMENT) {
        throw new TypeError("audio autoplay clock must be a one-word SharedArrayBuffer");
      }
      this._clock = new Int32Array(clockBuffer, 0, 1);
    } else {
      this._clock = null;
    }
    this._consumer = ring?.consumer?.() ?? null;
    // Pre-unlock discard is deliberately allocation-free after construction. The same scratch
    // block is reused by every timer tick and is never handed to the AudioWorklet.
    this._discardScratch = new Float32Array(quantumFrames * CHANNELS);
    this._state = AUTOPLAY_LOCKED;
    this._started = false;
    this._disposed = false;
    this._attachedTarget = null;
    this._timer = null;
    this._timerActive = false;
    this._lastPumpMs = null;
    this._frameCredit = 0;
    this._discardedFrames = 0;
    this._resumeAttempts = 0;
    this._resumePromise = null;
    this._lastError = null;
    this._onUnlocked = onUnlocked;
    this._onGesture = () => { void this.unlock("gesture"); };
  }

  get state() {
    return this._state;
  }

  get isUnlocked() {
    return this._state === AUTOPLAY_UNLOCKED;
  }

  get resumeAttempts() {
    return this._resumeAttempts;
  }

  get discardedFrames() {
    return this._discardedFrames;
  }

  get lastError() {
    return this._lastError;
  }

  get hasGestureListeners() {
    return this._attachedTarget !== null;
  }

  /** Start the listeners and the bounded suspended-context clock pump. */
  start() {
    if (this._disposed) return this;
    if (this._started) return this;
    this._started = true;
    this.attach();
    this._lastPumpMs = this._nowMs();
    renderBadge(this.badge, this._state);
    this._schedulePump();
    return this;
  }

  /** Attach exactly one click and one keydown listener to the chosen DOM target. */
  attach(target = this._target) {
    if (this._disposed) return this;
    if (!target || typeof target.addEventListener !== "function") {
      throw new TypeError("audio autoplay policy requires an event target");
    }
    if (this._attachedTarget === target) return this;
    if (this._attachedTarget) this.detach();
    target.addEventListener("click", this._onGesture);
    target.addEventListener("keydown", this._onGesture);
    this._attachedTarget = target;
    return this;
  }

  detach() {
    if (!this._attachedTarget) return this;
    this._attachedTarget.removeEventListener?.("click", this._onGesture);
    this._attachedTarget.removeEventListener?.("keydown", this._onGesture);
    this._attachedTarget = null;
    return this;
  }

  /**
   * Consume the amount of PCM that the negotiated clock has made due since the last pump.
   * At most one quantum is read per call, including after a long timer/backgrounding gap.
   */
  pump(now = this._nowMs()) {
    if (this._disposed || this._state === AUTOPLAY_UNLOCKED) return 0;
    const currentMs = Number(now);
    if (!Number.isFinite(currentMs)) return 0;
    if (this._lastPumpMs === null) this._lastPumpMs = currentMs;
    const elapsedMs = Math.max(0, currentMs - this._lastPumpMs);
    this._lastPumpMs = currentMs;
    this._frameCredit = Math.min(
      MAX_CLOCK_CREDIT_FRAMES,
      this._frameCredit + (elapsedMs * this.sampleRateHz) / 1_000,
    );

    const dueFrames = Math.min(this._quantumFrames, Math.floor(this._frameCredit));
    if (dueFrames < 1) return 0;
    // Account for time, rather than for available payload. Silence is not carried forward as a
    // future read budget, and a resumed tab cannot turn an old timer gap into a burst drain.
    this._frameCredit -= dueFrames;
    // Keep the guest pacing clock at wall-clock pace while the AudioContext is suspended. The
    // worklet takes over this same cell after unlock, so no two consumers advance it concurrently.
    if (this._clock) Atomics.add(this._clock, 0, dueFrames);
    if (!this._consumer) return 0;
    const read = this._consumer.readInto(this._discardScratch, dueFrames);
    this._discardedFrames += read;
    return read;
  }

  /**
   * Resume once per in-flight gesture sequence. Rejections resolve to `{ ok: false }` so a DOM
   * listener never creates an unhandled rejection; the visible badge stays actionable and the
   * pre-unlock pump remains active for a later gesture.
   */
  unlock(reason = "gesture") {
    if (this._disposed) return Promise.resolve({ ok: false, state: "disposed", reason });
    if (this._state === AUTOPLAY_UNLOCKED) {
      return Promise.resolve({ ok: true, state: AUTOPLAY_UNLOCKED, reason });
    }
    if (this._resumePromise) return this._resumePromise;

    this._resumeAttempts += 1;
    this._state = AUTOPLAY_UNLOCKING;
    this._lastError = null;
    // Stop the suspended-context consumer as soon as the gesture owns the transition. Keeping its
    // timer alive while the async AudioWorklet attach runs could discard the first published PCM
    // block before the render consumer takes over.
    this._cancelPump();
    renderBadge(this.badge, this._state);
    let resumeResult;
    try {
      resumeResult = Promise.resolve(this.context.resume());
    } catch (error) {
      resumeResult = Promise.reject(error);
    }
    const unlocked = () => {
        this._resumePromise = null;
        this._state = AUTOPLAY_UNLOCKED;
        this._frameCredit = 0;
        this._cancelPump();
        renderBadge(this.badge, this._state);
        return { ok: true, state: AUTOPLAY_UNLOCKED, reason };
    };
    const failed = (error) => {
        this._resumePromise = null;
        this._state = AUTOPLAY_LOCKED;
        this._lastError = error;
        renderBadge(this.badge, this._state);
        this._schedulePump();
        return { ok: false, state: AUTOPLAY_LOCKED, reason, error };
    };
    this._resumePromise = resumeResult
      .then(() => this._onUnlocked?.())
      .then(unlocked, failed);
    return this._resumePromise;
  }

  dispose() {
    if (this._disposed) return;
    this._disposed = true;
    this._cancelPump();
    this.detach();
  }

  _schedulePump() {
    if (!this._started || !this._consumer || this._disposed || this._state === AUTOPLAY_UNLOCKED || this._timerActive) return;
    this._timerActive = true;
    this._timer = this._schedule(() => {
      this._timerActive = false;
      this._timer = null;
      if (this._state !== AUTOPLAY_UNLOCKED && !this._disposed) {
        this.pump();
        this._schedulePump();
      }
    }, this._quantumMs);
  }

  _cancelPump() {
    if (!this._timerActive) return;
    this._cancel(this._timer);
    this._timerActive = false;
    this._timer = null;
  }
}

export function createAutoplayPolicy(options) {
  return new AudioAutoplayPolicy(options);
}

export { BADGE_TEXT };

// E5-T20c: producer-side bridge from virtio-snd S16 frames to the T20a/T20b browser path.

import { AUDIO_WORKLET_PROCESSOR_NAME } from "./worklet.js";
import {
  AudioRingBuffer,
  CHANNELS,
  DEFAULT_CAPACITY_FRAMES,
} from "./ring.js";

export const REQUESTED_SAMPLE_RATE_HZ = 48_000;
export const S16_SCALE = 1 / 32_768;
export const CONVERSION_CHUNK_FRAMES = 128;
export const AUDIO_CLOCK_BYTES = Int32Array.BYTES_PER_ELEMENT;
export const AUDIO_CAPTURE_CONTROL_BYTES = Int32Array.BYTES_PER_ELEMENT;

function defaultAudioContextFactory(options) {
  if (typeof AudioContext !== "function") {
    throw new TypeError("AudioContext is not available in this realm");
  }
  return new AudioContext(options);
}

function defaultWorkletNodeFactory(context, processorName, options) {
  if (typeof AudioWorkletNode !== "function") {
    throw new TypeError("AudioWorkletNode is not available in this realm");
  }
  return new AudioWorkletNode(context, processorName, options);
}

function validSampleRate(sampleRateHz) {
  if (!Number.isInteger(sampleRateHz) || sampleRateHz < 1) {
    throw new RangeError("audio sample rate must be a positive integer");
  }
  return sampleRateHz;
}

function createClockBuffer(clockBuffer) {
  if (typeof SharedArrayBuffer === "undefined") {
    throw new TypeError("audio clock requires SharedArrayBuffer");
  }
  if (clockBuffer === null || clockBuffer === undefined) {
    return new SharedArrayBuffer(AUDIO_CLOCK_BYTES);
  }
  if (!(clockBuffer instanceof SharedArrayBuffer) || clockBuffer.byteLength < AUDIO_CLOCK_BYTES) {
    throw new TypeError("audio clock must be a SharedArrayBuffer with one Int32 cell");
  }
  return clockBuffer;
}

function optionalLatencySeconds(context, name) {
  const value = Number(context?.[name]);
  return Number.isFinite(value) && value >= 0 ? value : null;
}

function createContext({
  audioContextFactory,
  contextOptions,
  requestedSampleRateHz,
}) {
  const options = { ...contextOptions, sampleRate: requestedSampleRateHz };
  try {
    return {
      context: audioContextFactory(options),
      requested: true,
    };
  } catch (requestedError) {
    // Some implementations reject an explicit rate. Retrying without sampleRate lets the
    // context choose its native rate; push() will then require PCM at that actual rate.
    const fallbackOptions = { ...contextOptions };
    delete fallbackOptions.sampleRate;
    try {
      return {
        context: audioContextFactory(fallbackOptions),
        requested: false,
      };
    } catch (fallbackError) {
      fallbackError.cause = requestedError;
      throw fallbackError;
    }
  }
}

export class AudioSinkRateError extends Error {
  constructor(expectedRateHz, actualRateHz) {
    super(`audio PCM rate ${actualRateHz} Hz does not match context rate ${expectedRateHz} Hz`);
    this.name = "AudioSinkRateError";
    this.expectedRateHz = expectedRateHz;
    this.actualRateHz = actualRateHz;
  }
}

/**
 * Host-side implementation of the T19 interleaved stereo S16 AudioSink contract.
 *
 * `push()` is synchronous and never waits for the consumer. It returns the accepted frame count;
 * callers retry a partial result after the ring drains. Input must already use the context's
 * advertised sample rate: this bridge intentionally has no implicit resampler.
 */
export class AudioWorkletSink {
  constructor({
    vm = null,
    ring = null,
    capacityFrames = DEFAULT_CAPACITY_FRAMES,
    requestedSampleRateHz = REQUESTED_SAMPLE_RATE_HZ,
    audioContextFactory = defaultAudioContextFactory,
    contextOptions = {},
    workletUrl = new URL("./worklet.js", import.meta.url).href,
    workletNode = null,
    workletNodeFactory = defaultWorkletNodeFactory,
    clockBuffer = null,
    capture = false,
    onCapture = null,
  } = {}) {
    this._vm = vm;
    this._requestedSampleRateHz = validSampleRate(requestedSampleRateHz);
    if (typeof audioContextFactory !== "function") {
      throw new TypeError("audioContextFactory must be a function");
    }
    const created = createContext({
      audioContextFactory,
      contextOptions,
      requestedSampleRateHz: this._requestedSampleRateHz,
    });
    if (!created.context || !Number.isInteger(Number(created.context.sampleRate))) {
      throw new TypeError("AudioContext must expose an integer sampleRate");
    }

    this.context = created.context;
    this.sampleRateHz = validSampleRate(Number(this.context.sampleRate));
    this.rateRequested = created.requested;
    this.ring = ring ?? AudioRingBuffer.allocate({ capacityFrames });
    this.clockBuffer = createClockBuffer(clockBuffer);
    this._clock = new Int32Array(this.clockBuffer, 0, 1);
    this._originClockFrames = Atomics.load(this._clock, 0) >>> 0;
    this._producer = this.ring.producer();
    this._conversion = new Float32Array(
      Math.min(this.ring.capacityFrames, CONVERSION_CHUNK_FRAMES) * CHANNELS,
    );
    this._workletUrl = workletUrl;
    this._workletNode = workletNode;
    this._workletNodeFactory = workletNodeFactory;
    this._capture = capture === true;
    this._onCapture = typeof onCapture === "function" ? onCapture : null;
    this.captureReadyBuffer = this._capture
      ? new SharedArrayBuffer(AUDIO_CAPTURE_CONTROL_BYTES)
      : null;
    this._captureReady = this.captureReadyBuffer
      ? new Int32Array(this.captureReadyBuffer, 0, 1)
      : null;
    this._captureListener = null;
    this._originReadIndex = this.ring.readIndex;
    this._originContextTime = Number(this.context.currentTime);
    this._originContextTime = Number.isFinite(this._originContextTime) && this._originContextTime >= 0
      ? this._originContextTime
      : 0;
    this._lastClockNs = Math.round(this._originContextTime * 1e9);
    this._publishStats();
  }

  get workletNode() {
    return this._workletNode;
  }

  get requestedSampleRateHz() {
    return this._requestedSampleRateHz;
  }

  get advertisedSampleRateHz() {
    return this.sampleRateHz;
  }

  get consumedFrames() {
    return this.ring.readIndex;
  }

  get renderedFrames() {
    return Atomics.load(this._clock, 0) >>> 0;
  }

  /** Load the processor module, construct the node, and connect it to the context destination. */
  async connect() {
    if (this._workletNode) return this;
    if (!this.context.audioWorklet || typeof this.context.audioWorklet.addModule !== "function") {
      throw new TypeError("AudioContext.audioWorklet.addModule is not available");
    }
    await this.context.audioWorklet.addModule(this._workletUrl);
    this._workletNode = this._workletNodeFactory(
      this.context,
      AUDIO_WORKLET_PROCESSOR_NAME,
      {
        numberOfInputs: 0,
        numberOfOutputs: 1,
        outputChannelCount: [CHANNELS],
        processorOptions: {
          sharedBuffer: this.ring.sharedBuffer,
          clockBuffer: this.clockBuffer,
          ...(this.captureReadyBuffer ? { captureReadyBuffer: this.captureReadyBuffer } : {}),
          capture: this._capture,
        },
      },
    );
    if (this._capture && this._onCapture && this._workletNode.port) {
      this._captureListener = (event) => this._onCapture(event.data);
      this._workletNode.port.addEventListener?.("message", this._captureListener);
      if (!this._workletNode.port.addEventListener) this._workletNode.port.onmessage = this._captureListener;
      this._workletNode.port.start?.();
    }
    // The node constructor may run one process callback before this task reaches the listener
    // setup. Keep the consumer paused until capture can observe its first frame exactly once.
    if (this._captureReady) Atomics.store(this._captureReady, 0, 1);
    this._workletNode.connect?.(this.context.destination);
    return this;
  }

  /**
   * Push interleaved signed 16-bit stereo PCM without resampling or blocking.
   *
   * The result is `{ acceptedFrames, droppedFrames, complete, sampleRateHz }`. A partial result
   * means the ring was full; no input frame is silently converted at a different sample rate.
   */
  push(frames, sampleRateHz = this.sampleRateHz) {
    if (!(frames instanceof Int16Array)) {
      throw new TypeError("audio sink frames must be an Int16Array");
    }
    if (frames.length % CHANNELS !== 0) {
      throw new RangeError("audio sink frames must contain complete stereo samples");
    }
    const inputRateHz = validSampleRate(sampleRateHz);
    if (inputRateHz !== this.sampleRateHz) {
      throw new AudioSinkRateError(this.sampleRateHz, inputRateHz);
    }

    const totalFrames = frames.length / CHANNELS;
    let acceptedFrames = 0;
    while (acceptedFrames < totalFrames) {
      const chunkFrames = Math.min(
        totalFrames - acceptedFrames,
        this._conversion.length / CHANNELS,
      );
      for (let frame = 0; frame < chunkFrames; frame += 1) {
        const sourceIndex = (acceptedFrames + frame) * CHANNELS;
        const targetIndex = frame * CHANNELS;
        this._conversion[targetIndex] = frames[sourceIndex] * S16_SCALE;
        this._conversion[targetIndex + 1] = frames[sourceIndex + 1] * S16_SCALE;
      }
      const written = this._producer.write(this._conversion, chunkFrames);
      acceptedFrames += written;
      if (written < chunkFrames) break;
    }

    const result = {
      acceptedFrames,
      droppedFrames: totalFrames - acceptedFrames,
      complete: acceptedFrames === totalFrames,
      sampleRateHz: this.sampleRateHz,
    };
    this._publishStats();
    return result;
  }

  /**
   * Return the rendered audio clock in nanoseconds. The worklet (or the pre-unlock discard policy)
   * advances the shared frame cell at the negotiated sample rate; `currentTime` and the ring read
   * cursor remain monotonic fallbacks for older/fake contexts.
   */
  audioClockNowNs() {
    const currentTime = Number(this.context.currentTime);
    const contextClockNs = Number.isFinite(currentTime) && currentTime >= 0
      ? Math.round(currentTime * 1e9)
      : this._lastClockNs;
    const consumedDelta = (this.ring.readIndex - this._originReadIndex) >>> 0;
    const frameClockNs = Math.round(
      this._originContextTime * 1e9 + (consumedDelta * 1e9) / this.sampleRateHz,
    );
    const renderedDelta = (this.renderedFrames - this._originClockFrames) >>> 0;
    const renderedClockNs = Math.round(
      this._originContextTime * 1e9 + (renderedDelta * 1e9) / this.sampleRateHz,
    );
    this._lastClockNs = Math.max(this._lastClockNs, contextClockNs, frameClockNs, renderedClockNs);
    return this._lastClockNs;
  }

  stats() {
    return this._publishStats();
  }

  async close() {
    if (this._captureListener && this._workletNode?.port) {
      this._workletNode.port.removeEventListener?.("message", this._captureListener);
      if (this._workletNode.port.onmessage === this._captureListener) this._workletNode.port.onmessage = null;
      this._captureListener = null;
    }
    this._workletNode?.disconnect?.();
    await this.context.close?.();
  }

  _publishStats() {
    const baseLatency = optionalLatencySeconds(this.context, "baseLatency");
    const outputLatency = optionalLatencySeconds(this.context, "outputLatency");
    const fill = this.ring.fillFrames;
    const contextLatencySeconds = (baseLatency ?? 0) + (outputLatency ?? 0);
    const audio = {
      latency_ms: ((fill / this.sampleRateHz) + contextLatencySeconds) * 1_000,
      underruns: this.ring.underrunCount,
      fill,
      sampleRateHz: this.sampleRateHz,
    };
    if (baseLatency !== null) audio.baseLatency = baseLatency;
    if (outputLatency !== null) audio.outputLatency = outputLatency;
    if (this._vm) {
      if (!this._vm.stats || typeof this._vm.stats !== "object") this._vm.stats = {};
      this._vm.stats.audio = audio;
    }
    this._lastStats = audio;
    return audio;
  }
}

// The alias keeps the browser bridge name aligned with T19's host-side AudioSink trait.
export const AudioSink = AudioWorkletSink;

export async function createAudioSink(options) {
  const sink = new AudioWorkletSink(options);
  await sink.connect();
  return sink;
}

// E5-T21c: the reversed SPSC role for browser microphone capture.
//
// The capture AudioWorklet owns the producer endpoint and the VM-side host bridge owns the
// consumer endpoint.  The bytes are intentionally the T20a AudioRingBuffer layout: keeping one
// atomic contract means the only role change is which side calls producer() and consumer().

import {
  AudioRingBuffer,
  CHANNELS,
  HEADER,
} from "./ring.js";

const UINT32_MAX = 0xffff_ffff;

/** Add to the capture drop counter without allowing the uint32 cell to wrap. */
function addSaturated(header, index, amount) {
  if (!Number.isSafeInteger(amount) || amount < 0) {
    throw new RangeError("capture drop count must be a non-negative integer");
  }
  for (;;) {
    const current = Atomics.load(header, index) >>> 0;
    if (current === UINT32_MAX || amount === 0) return current;
    const next = Math.min(UINT32_MAX, current + amount);
    const observed = Atomics.compareExchange(header, index, current | 0, next | 0) >>> 0;
    if (observed === current) return next;
  }
}

/** A T20a ring viewed from the microphone side: worklet producer, VM consumer. */
export class AudioCaptureRingBuffer {
  static allocate(options = {}) {
    return new AudioCaptureRingBuffer(AudioRingBuffer.allocate(options));
  }

  static fromSharedBuffer(sharedBuffer) {
    return new AudioCaptureRingBuffer(AudioRingBuffer.fromSharedBuffer(sharedBuffer));
  }

  constructor(ring) {
    if (!(ring instanceof AudioRingBuffer)) {
      throw new TypeError("capture ring requires an AudioRingBuffer");
    }
    this._ring = ring;
    this._header = new Int32Array(ring.sharedBuffer, 0, HEADER.DROPPED_FRAMES + 1);
  }

  get sharedBuffer() {
    return this._ring.sharedBuffer;
  }

  get capacityFrames() {
    return this._ring.capacityFrames;
  }

  get channels() {
    return CHANNELS;
  }

  get fillFrames() {
    return this._ring.fillFrames;
  }

  get writeIndex() {
    return this._ring.writeIndex;
  }

  get readIndex() {
    return this._ring.readIndex;
  }

  /** Number of input frames refused because the ring had no free slot. */
  get droppedFrames() {
    return Atomics.load(this._header, HEADER.DROPPED_FRAMES) >>> 0;
  }

  /** Alias for callers that describe the same state as an overrun counter. */
  get overflowCount() {
    return this.droppedFrames;
  }

  recordDroppedFrames(frameCount) {
    return addSaturated(this._header, HEADER.DROPPED_FRAMES, frameCount);
  }

  producer() {
    return new AudioCaptureRingProducer(this);
  }

  consumer() {
    return this._ring.consumer();
  }
}

export class AudioCaptureRingProducer {
  constructor(captureRing) {
    this._captureRing = captureRing;
    this._producer = captureRing._ring.producer();
  }

  availableFrames() {
    return this._producer.availableFrames();
  }

  /** Publish what fits and account for the rest without waiting for the consumer. */
  write(frames, frameCount = frames.length / CHANNELS, frameOffset = 0) {
    const written = this._producer.write(frames, frameCount, frameOffset);
    if (written < frameCount) this._captureRing.recordDroppedFrames(frameCount - written);
    return written;
  }
}

export function createAudioCaptureRing(options) {
  return AudioCaptureRingBuffer.allocate(options);
}

// E5-T21d: lazy microphone permission and lifecycle policy.
//
// This module owns browser media objects only. The guest advertises capture at boot, but this
// adapter does not call getUserMedia until the loader reports a successful capture PCM_START. A
// denied, missing, muted, or ended track leaves the already-attached wasm capture source running;
// the shared-ring consumer then supplies paced zero-filled rxq periods and the guest receives the
// existing bounded PCM XRUN event through eventq.

import {
  AUDIO_CAPTURE_WORKLET_PROCESSOR_NAME,
} from "./capture-worklet.js";

export const MICROPHONE_OFF = "off";
export const MICROPHONE_LIVE = "live";
export const MICROPHONE_DENIED = "denied";
export const MICROPHONE_REVOKED = "revoked";

export const MICROPHONE_CONSTRAINTS = Object.freeze({
  audio: Object.freeze({
    channelCount: { ideal: 2 },
    sampleRate: { ideal: 48_000 },
    echoCancellation: false,
    noiseSuppression: false,
    autoGainControl: false,
  }),
  video: false,
