export class MicrophonePermissionController {
  constructor({
    enabled = false,
    ring = null,
    sampleRateHz = 48_000,
    getUserMedia = defaultGetUserMedia,
    audioContextFactory = defaultAudioContextFactory,
    workletUrl = new URL("./capture-worklet.js", import.meta.url).href,
    workletNodeFactory = defaultWorkletNodeFactory,
    mediaSourceFactory = defaultMediaSourceFactory,
    gainFactory = defaultGainFactory,
    notifyGuest = null,
    onStateChange = null,
  } = {}) {
    if (typeof getUserMedia !== "function") throw new TypeError("getUserMedia must be a function");
    if (typeof audioContextFactory !== "function") {
      throw new TypeError("audioContextFactory must be a function");
    }
    if (typeof workletNodeFactory !== "function") {
      throw new TypeError("workletNodeFactory must be a function");
    }
    if (typeof mediaSourceFactory !== "function") {
      throw new TypeError("mediaSourceFactory must be a function");
    }
    if (typeof gainFactory !== "function") throw new TypeError("gainFactory must be a function");
    if (notifyGuest !== null && typeof notifyGuest !== "function") {
      throw new TypeError("notifyGuest must be a function or null");
    }
    if (onStateChange !== null && typeof onStateChange !== "function") {
      throw new TypeError("onStateChange must be a function or null");
    }
    if (!Number.isInteger(Number(sampleRateHz)) || ![44_100, 48_000].includes(Number(sampleRateHz))) {
      throw new RangeError("microphone sample rate must be 44100 or 48000 Hz");
    }
    if (ring !== null && typeof ring !== "object") throw new TypeError("microphone ring is invalid");

    this.enabled = Boolean(enabled);
    this.ring = ring;
    this.sampleRateHz = Number(sampleRateHz);
    this._getUserMedia = getUserMedia;
    this._audioContextFactory = audioContextFactory;
    this._workletUrl = workletUrl;
    this._workletNodeFactory = workletNodeFactory;
    this._mediaSourceFactory = mediaSourceFactory;
    this._gainFactory = gainFactory;
    this._notifyGuest = notifyGuest;
    this._onStateChange = onStateChange;

    this._state = MICROPHONE_OFF;
    this._pending = false;
    this._startCount = 0;
    this._lastGuestStartCount = 0;
    this._getUserMediaCalls = 0;
    this._transitionCount = 0;
    this._lastError = null;
    this._requestPromise = null;
    this._sessionGeneration = 0;
    this._stream = null;
    this._track = null;
    this._trackListeners = [];
    this._context = null;
    this._source = null;
    this._node = null;
    this._gain = null;
    this._ringConsumer = ring?.consumer?.() ?? null;
    this._clearScratch = new Float32Array(256 * 2);
    this._notifyCount = 0;
    this._emit();
  }

  get state() {
    return this._state;
  }

  get pending() {
    return this._pending;
  }

  get stream() {
    return this._stream;
  }

  get track() {
    return this._track;
  }

  /** Snapshot used by the UI and deterministic browser harness. */
  snapshot() {
    return {
      enabled: this.enabled,
      state: this._state,
      pending: this._pending,
      startCount: this._startCount,
      getUserMediaCalls: this._getUserMediaCalls,
      listenerCount: this._trackListeners.length,
      streamActive: Boolean(this._stream),
      trackReadyState: this._track?.readyState ?? null,
      trackMuted: this._track?.muted === true,
      ringFillFrames: this.ring?.fillFrames ?? 0,
      ringDroppedFrames: this.ring?.droppedFrames ?? 0,
      notifyCount: this._notifyCount,
      transitionCount: this._transitionCount,
      lastError: this._lastError,
    };
  }

  /**
   * Observe one successful guest capture start. Duplicate observations of the same generation are
   * ignored, so a delayed worker message cannot create a second stream or listener set.
   */
  onPcmStart(info = {}) {
    if (!this.enabled || info?.enabled !== true) return Promise.resolve({ ok: false, state: this._state, reason: "disabled" });
    const startCount = Number(info.startCount);
    if (!Number.isSafeInteger(startCount) || startCount < 1) {
      return Promise.resolve({ ok: false, state: this._state, reason: "invalid-start" });
    }
    if (startCount <= this._lastGuestStartCount) {
      return this._requestPromise ?? Promise.resolve({ ok: this._state === MICROPHONE_LIVE, state: this._state, reason: "duplicate-start" });
    }
    this._lastGuestStartCount = startCount;
    this._startCount = startCount;
    if (this._requestPromise) return this._requestPromise;
    if (this._state === MICROPHONE_LIVE && this._stream && this._track?.readyState !== "ended") {
      return Promise.resolve({ ok: true, state: MICROPHONE_LIVE, reason: "already-live" });
    }
    if (!this.ring) {
      this._pending = false;
      this._lastError = "capture-ring-unavailable";
      this._setState(MICROPHONE_DENIED);
      this._notify("denied");
      return Promise.resolve({ ok: false, state: MICROPHONE_DENIED, reason: this._lastError });
    }

    this._pending = true;
    this._lastError = null;
    this._emit();
    const request = this._requestMedia(startCount, this._sessionGeneration);
    this._requestPromise = request;
    request.finally(() => {
      if (this._requestPromise === request) this._requestPromise = null;
    }).catch(() => { /* _requestMedia classifies all expected failures */ });
    return request;
  }

  /** Retry is intentionally a marker, not a permission entry point; the next guest PCM_START owns it. */
  retry() {
    return {
      ok: false,
      state: this._state,
      reason: "awaiting-guest-pcm-start",
      startCount: this._lastGuestStartCount,
    };
  }

  reset() {
    this._sessionGeneration += 1;
    this._teardown({ stopStream: true });
    this._drainRing();
    this._state = MICROPHONE_OFF;
    this._pending = false;
    this._startCount = 0;
    this._lastGuestStartCount = 0;
    this._lastError = null;
    this._requestPromise = null;
    this._emit();
  }

  close() {
    this.reset();
  }

  async _requestMedia(startCount, sessionGeneration) {
    let stream;
    try {
      this._getUserMediaCalls += 1;
      stream = await this._getUserMedia(MICROPHONE_CONSTRAINTS);
    } catch (error) {
      this._pending = false;
      this._lastError = errorCode(error);
      this._setState(MICROPHONE_DENIED);
      this._notify("denied");
      return { ok: false, state: MICROPHONE_DENIED, reason: this._lastError, startCount };
    }

    // A boot/reset can retire a pending browser permission prompt, but browsers do not expose a
    // portable abort for getUserMedia. Ignore a late grant and stop its tracks instead of letting a
    // stale response recreate listeners or a hidden AudioContext on the next guest session.
    if (sessionGeneration !== this._sessionGeneration) {
      stopTracks(stream);
      return { ok: false, state: MICROPHONE_OFF, reason: "cancelled", startCount };
    }

    const track = stream?.getAudioTracks?.().find((candidate) => candidate) ?? null;
    if (!track) {
      stopTracks(stream);
      this._pending = false;
      this._lastError = "no-device";
      this._setState(MICROPHONE_DENIED);
      this._notify("denied");
      return { ok: false, state: MICROPHONE_DENIED, reason: this._lastError, startCount };
    }

    try {
      await this._installGraph(stream, track, sessionGeneration);
    } catch (error) {
      stopTracks(stream);
      this._teardown({ stopStream: false });
      if (sessionGeneration !== this._sessionGeneration) {
        return { ok: false, state: MICROPHONE_OFF, reason: "cancelled", startCount };
      }
      this._pending = false;
      this._lastError = errorCode(error);
      this._setState(MICROPHONE_DENIED);
      this._notify("denied");
      return { ok: false, state: MICROPHONE_DENIED, reason: this._lastError, startCount };
    }
    if (sessionGeneration !== this._sessionGeneration) {
      stopTracks(stream);
      this._teardown({ stopStream: false });
      return { ok: false, state: MICROPHONE_OFF, reason: "cancelled", startCount };
    }
    this._pending = false;
    this._lastError = null;
    if (track.muted === true) {
      this._setState(MICROPHONE_REVOKED);
      this._notify("muted");
      return { ok: true, state: MICROPHONE_REVOKED, reason: "muted", startCount };
    }
    this._setState(MICROPHONE_LIVE);
    return { ok: true, state: MICROPHONE_LIVE, reason: "granted", startCount };
  }

  async _installGraph(stream, track, sessionGeneration) {
    this._teardown({ stopStream: true });
    const context = this._audioContextFactory({ sampleRate: this.sampleRateHz });
    this._context = context;
    let node = null;
    let source = null;
    let gain = null;
    try {
      if (!context?.audioWorklet?.addModule) throw new TypeError("capture AudioWorklet is unavailable");
      if (Number(context.sampleRate) !== this.sampleRateHz) {
        throw new RangeError("capture AudioContext sample rate does not match the guest");
      }
      await context.audioWorklet.addModule(this._workletUrl);
      if (sessionGeneration !== this._sessionGeneration) {
        throw new Error("capture session was reset");
      }
      node = this._workletNodeFactory(
        context,
        AUDIO_CAPTURE_WORKLET_PROCESSOR_NAME,
        {
          numberOfInputs: 1,
          numberOfOutputs: 1,
          outputChannelCount: [2],
          processorOptions: {
            captureBuffer: this.ring.sharedBuffer,
            sampleRateHz: this.sampleRateHz,
          },
        },
      );
      source = this._mediaSourceFactory(context, stream);
      gain = this._gainFactory(context);
      if (gain?.gain) gain.gain.value = 0;
      source.connect?.(node);
      node.connect?.(gain);
      gain.connect?.(context.destination);

      this._source = source;
      this._node = node;
      this._gain = gain;
      this._stream = stream;
      this._track = track;
      this._attachTrackListeners(track);
      // Capturing remains usable when autoplay policy keeps this private, zero-gain context
      // suspended. A rejected resume is expected and leaves the stream in live/silence fallback.
      try { await Promise.resolve(context.resume?.()); } catch { /* user gesture may be required */ }
    } catch (error) {
      try { source?.disconnect?.(); } catch {}
      try { node?.disconnect?.(); } catch {}
      try { gain?.disconnect?.(); } catch {}
      this._source = null;
      this._node = null;
      this._gain = null;
      this._stream = null;
      this._track = null;
      if (this._context === context) this._context = null;
      try { await Promise.resolve(context.close?.()); } catch {}
      throw error;
    }
  }

  _attachTrackListeners(track) {
    const listeners = [
      ["mute", () => this._trackMuted()],
      ["unmute", () => this._trackUnmuted()],
      ["ended", () => this._trackEnded()],
    ];
    for (const [type, listener] of listeners) {
      if (typeof track.addEventListener === "function") {
        track.addEventListener(type, listener);
        this._trackListeners.push([track, type, listener]);
      }
    }
  }

  _trackMuted() {
    this._drainRing();
    if (this._state !== MICROPHONE_REVOKED) {
      this._setState(MICROPHONE_REVOKED);
      this._notify("muted");
    }
  }

  _trackUnmuted() {
    if (this._stream && this._track?.readyState !== "ended") {
      this._lastError = null;
      this._setState(MICROPHONE_LIVE);
    }
  }

  _trackEnded() {
    this._drainRing();
    this._teardown({ stopStream: false });
    this._pending = false;
    this._lastError = "track-ended";
    this._setState(MICROPHONE_REVOKED);
    this._notify("revoked");
  }

  _teardown({ stopStream }) {
    for (const [track, type, listener] of this._trackListeners) {
      try { track.removeEventListener?.(type, listener); } catch { /* teardown is best effort */ }
    }
    this._trackListeners = [];
    try { this._source?.disconnect?.(); } catch {}
    try { this._node?.disconnect?.(); } catch {}
    try { this._gain?.disconnect?.(); } catch {}
    const stream = this._stream;
    this._source = null;
    this._node = null;
    this._gain = null;
    this._stream = null;
    this._track = null;
    const context = this._context;
    this._context = null;
    if (stopStream) stopTracks(stream);
    if (context?.close) void Promise.resolve(context.close()).catch(() => {});
  }

  _drainRing() {
    if (!this._ringConsumer) return;
    try {
      while (this._ringConsumer.readInto(this._clearScratch) > 0) {}
    } catch { /* a reset/teardown race should still leave the guest on silence */ }
  }

  _notify(event) {
    this._notifyCount += 1;
    try {
      const result = this._notifyGuest?.(event);
      if (result && typeof result.then === "function") result.catch(() => {});
    } catch { /* host lifecycle notification must never become an uncaught page exception */ }
  }

  _setState(state) {
    if (this._state === state) return;
    this._state = state;
    this._transitionCount += 1;
    this._emit();
  }

  _emit() {
    try { this._onStateChange?.(this.snapshot()); } catch { /* diagnostics/UI cannot break capture */ }
  }
}

export function createMicrophonePermissionController(options) {
  return new MicrophonePermissionController(options);
}

// E5-T14b: browser pointer routing for the T14a virtio tablet/mouse pair.
//
// This module is intentionally JavaScript-compatible TypeScript. The demo has no bundler, so
// pointer.js is a byte-identical projection consumed by the page and by the Node fixtures. All
// coordinate math stays in CSS pixels; the guest's 0..32767 tablet range never sees a canvas
// backing-pixel dimension or a devicePixelRatio multiplier.

export const EV_SYN = 0;
export const SYN_REPORT = 0;
export const EV_KEY = 1;
export const EV_REL = 2;
export const EV_ABS = 3;

export const ABS_X = 0;
export const ABS_Y = 1;
export const REL_X = 0;
export const REL_Y = 1;
export const REL_HWHEEL = 6;
export const REL_WHEEL = 8;

export const WHEEL_DELTA_MODES = Object.freeze({
  PIXEL: 0,
  LINE: 1,
  PAGE: 2,
});
// Keep one normalized accumulator unit equal to one CSS pixel. A line is treated as 40 pixels and
// a page as one detent (120 pixels), matching the browser-independent contract in docs/input.md.
export const WHEEL_DETENT_UNITS = 120;
export const WHEEL_MAX_INPUT = 1_000_000;

export const BTN_LEFT = 0x110;
export const BTN_RIGHT = 0x111;
export const BTN_MIDDLE = 0x112;
export const BTN_SIDE = 0x113;
export const BTN_EXTRA = 0x114;

export const ABS_MIN = 0;
export const ABS_MAX = 32767;

export const POINTER_MODES = Object.freeze({
  ABSOLUTE: "absolute",
  RELATIVE: "relative",
});

/** Browser PointerEvent.button → the T14a evdev button code. */
export const POINTER_BUTTON_CODES = Object.freeze({
  0: BTN_LEFT, // primary
  1: BTN_MIDDLE, // auxiliary/middle
  2: BTN_RIGHT, // secondary
  3: BTN_SIDE, // back
  4: BTN_EXTRA, // forward
});

function finiteNumber(value) {
  const number = Number(value);
  return Number.isFinite(number) ? number : null;
}

function clamp(value, min, max) {
  return Math.min(max, Math.max(min, value));
}

function safeCallback(callback, value) {
  try { callback(value); } catch { /* diagnostics and telemetry never break input */ }
}

function eventCoordinate(event, axis, rect) {
  const client = finiteNumber(event?.[axis]);
  if (client !== null) return client;
  const offsetName = axis === "clientX" ? "offsetX" : "offsetY";
  const offset = finiteNumber(event?.[offsetName]);
  if (offset !== null) return finiteNumber(rect?.[axis === "clientX" ? "left" : "top"]) + offset;
  return null;
}

/** Convert a PointerEvent-shaped value to the guest's absolute tablet range. */
export function absoluteCoordinatesFromEvent(event, rect) {
  const left = finiteNumber(rect?.left);
  const top = finiteNumber(rect?.top);
  const width = finiteNumber(rect?.width);
  const height = finiteNumber(rect?.height);
  if (left === null || top === null || width === null || height === null || width <= 0 || height <= 0) {
    return null;
  }
  const clientX = eventCoordinate(event, "clientX", rect);
  const clientY = eventCoordinate(event, "clientY", rect);
  if (clientX === null || clientY === null) return null;
  return {
    x: clamp(Math.round(((clientX - left) / width) * ABS_MAX), ABS_MIN, ABS_MAX),
    y: clamp(Math.round(((clientY - top) / height) * ABS_MAX), ABS_MIN, ABS_MAX),
  };
}

export function evdevForPointerButton(button) {
  const number = finiteNumber(button);
  if (number === null || !Number.isInteger(number)) return null;
  return Object.hasOwn(POINTER_BUTTON_CODES, number) ? POINTER_BUTTON_CODES[number] : null;
}

/** Adapt a direct WasmLinux controller or the whole-machine-worker proxy. */
export function createWasmPointerAdapter(controller) {
  const methods = ["sendTabletEvent", "syncTablet", "sendMouseEvent", "syncMouse"];
  for (const method of methods) {
    if (typeof controller?.[method] !== "function") {
      throw new TypeError(`pointer adapter requires ${method}`);
    }
  }
  return {
    sendTabletEvent: (...args) => controller.sendTabletEvent(...args),
    syncTablet: () => controller.syncTablet(),
    sendMouseEvent: (...args) => controller.sendMouseEvent(...args),
    syncMouse: () => controller.syncMouse(),
  };
}

function pointerEventKey(event, button) {
  const pointerId = finiteNumber(event?.pointerId);
  return pointerId === null ? `button:${button}` : `pointer:${pointerId}:${button}`;
}

function eventRecord(eventType, code, value) {
  return { eventType, code, value };
}

/**
 * Build the absolute-tablet/relative-mouse state machine.
 *
 * `setMode("relative")` makes the mode change explicit immediately, then requests Pointer Lock.
 * A rejected request or a later lock-loss event returns to absolute mode and releases every held
 * button on the device that originally received its make. This makes a lock denial safe even when
 * the browser delivers a late pointerup for the old mode.
 */
export function createPointerBridge(
  adapter,
  {
    target = null,
    documentTarget = globalThis.document,
    getRect = () => target?.getBoundingClientRect?.() ?? null,
    isReady = () => true,
    onDiagnostic = () => {},
    onFrame = () => {},
    onStateChange = () => {},
    absoluteButtonDevice = "tablet",
    serializeTransport = false,
  } = {},
) {
  if (typeof adapter?.sendTabletEvent !== "function" || typeof adapter?.syncTablet !== "function") {
    throw new TypeError("pointer bridge requires tablet event and sync methods");
  }
  if (typeof adapter?.sendMouseEvent !== "function" || typeof adapter?.syncMouse !== "function") {
    throw new TypeError("pointer bridge requires mouse event and sync methods");
  }
  if (absoluteButtonDevice !== "tablet" && absoluteButtonDevice !== "mouse") {
    throw new TypeError(`unknown absolute button device: ${String(absoluteButtonDevice)}`);
  }
  if (typeof serializeTransport !== "boolean") {
    throw new TypeError("serializeTransport must be boolean");
  }

  let pointerTarget = target;
  let pointerDocument = documentTarget;
  let mode = POINTER_MODES.ABSOLUTE;
  let pointerLockRequested = false;
  let sequence = 0;
  let modeChanges = 0;
  let pointerLockChanges = 0;
  const heldButtons = new Map();
  let wheelRemainders = { horizontal: 0, vertical: 0 };
  let transportTail = Promise.resolve();

  function diagnostic(reason, extra = {}) {
    safeCallback(onDiagnostic, { reason, mode, ...extra });
  }

  function pointerLocked() {
    return Boolean(pointerTarget && pointerDocument?.pointerLockElement === pointerTarget);
  }

  function snapshot(reason = "state") {
    return {
      mode,
      pointerLocked: pointerLocked(),
      pointerLockRequested,
      heldButtons: [...heldButtons.values()].map((entry) => ({ ...entry })),
      wheelRemainders: { ...wheelRemainders },
      modeChanges,
      pointerLockChanges,
      reason,
    };
  }

  function notify(reason) {
    safeCallback(onStateChange, snapshot(reason));
  }

  function ready() {
    try { return Boolean(isReady()); } catch (error) {
      diagnostic("ready-check-error", { error: error?.message || String(error) });
      return false;
    }
  }

  function publish(device, events, metadata = {}) {
    if (!events || events.length === 0) return null;
    if (!ready()) {
      diagnostic("controller-unavailable", { device, eventCount: events.length });
      return null;
    }
    const send = device === "tablet"
      ? adapter.sendTabletEvent
      : adapter.sendMouseEvent;
    const sync = device === "tablet" ? adapter.syncTablet : adapter.syncMouse;
    const frame = {
      sequence: ++sequence,
      device,
      mode,
      events: events.map((event) => ({ ...event })),
      sync: SYN_REPORT,
      ...metadata,
    };
    const transmit = () => {
      try {
        for (const event of events) send(event.eventType, event.code, event.value);
        sync();
      } catch (error) {
        diagnostic("pointer-send-error", { device, error: error?.message || String(error) });
        return false;
      }
      safeCallback(onFrame, frame);
      return true;
    };
    const transmitSerialized = async () => {
      try {
        for (const event of events) await send(event.eventType, event.code, event.value);
        await sync();
      } catch (error) {
        diagnostic("pointer-send-error", { device, error: error?.message || String(error) });
        return false;
      }
      safeCallback(onFrame, frame);
      return true;
    };
    if (serializeTransport) {
      transportTail = transportTail.then(transmitSerialized, transmitSerialized);
    } else {
      transmit();
    }
    return frame;
  }

  function releaseAll(reason = "release-all", { emit = true } = {}) {
    if (heldButtons.size === 0) return [];
    const byDevice = new Map();
    for (const entry of [...heldButtons.values()].reverse()) {
      if (!byDevice.has(entry.device)) byDevice.set(entry.device, []);
      byDevice.get(entry.device).push(eventRecord(EV_KEY, entry.evdev, 0));
    }
    const frames = [];
    if (emit) {
      for (const [device, events] of byDevice) {
        const frame = publish(device, events, { reason });
        if (frame) frames.push(frame);
      }
    }
    heldButtons.clear();
    return frames;
  }

  function exitPointerLock() {
    try { pointerDocument?.exitPointerLock?.(); } catch (error) {
      diagnostic("pointerlock-exit-error", { error: error?.message || String(error) });
    }
  }

  function makeAbsolute(reason, { exitLock = true } = {}) {
    pointerLockRequested = false;
    releaseAll(reason);
    const changed = mode !== POINTER_MODES.ABSOLUTE;
    mode = POINTER_MODES.ABSOLUTE;
    if (changed) modeChanges += 1;
    notify(reason);
    if (exitLock && pointerLocked()) exitPointerLock();
    return mode;
  }

  function lockFailure(reason, error = undefined) {
    pointerLockRequested = false;
    diagnostic(reason, error ? { error: error?.message || String(error) } : {});
    makeAbsolute(reason, { exitLock: false });
    return false;
  }

  function requestPointerLock() {
    if (!pointerTarget || typeof pointerTarget.requestPointerLock !== "function") {
      return lockFailure("pointerlock-unavailable");
    }
    try {
      let result;
      try {
        result = pointerTarget.requestPointerLock({ unadjustedMovement: true });
      } catch (error) {
        // Older browsers expose the legacy no-argument form. Retry only for an options-shape
        // TypeError; permission and policy errors must fail closed into absolute mode.
        if (error?.name !== "TypeError") throw error;
        result = pointerTarget.requestPointerLock();
      }
      if (result === false) return lockFailure("pointerlock-denied");
      if (result && typeof result.then === "function") {
        Promise.resolve(result).catch((error) => lockFailure("pointerlock-denied", error));
      }
      return true;
    } catch (error) {
      return lockFailure("pointerlock-denied", error);
    }
  }

  function setMode(nextMode, { requestLock = true, reason = "mode-change" } = {}) {
    if (nextMode !== POINTER_MODES.ABSOLUTE && nextMode !== POINTER_MODES.RELATIVE) {
      throw new TypeError(`unknown pointer mode: ${String(nextMode)}`);
    }
    if (nextMode === POINTER_MODES.ABSOLUTE) {
      return makeAbsolute(reason);
    }
    pointerLockRequested = requestLock;
    releaseAll(reason);
    if (mode !== POINTER_MODES.RELATIVE) {
      mode = POINTER_MODES.RELATIVE;
      modeChanges += 1;
      notify(reason);
    } else if (!requestLock) {
      notify(reason);
    }
    if (requestLock) requestPointerLock();
    return mode;
  }

  function toggleMode(options = {}) {
    return setMode(
      mode === POINTER_MODES.ABSOLUTE ? POINTER_MODES.RELATIVE : POINTER_MODES.ABSOLUTE,
      options,
    );
  }

  function handlePointerLockChange() {
    pointerLockChanges += 1;
    if (pointerLocked()) {
      if (mode === POINTER_MODES.RELATIVE || pointerLockRequested) {
        pointerLockRequested = false;
        if (mode !== POINTER_MODES.RELATIVE) {
          releaseAll("pointerlock-acquired");
          mode = POINTER_MODES.RELATIVE;
          modeChanges += 1;
        }
        notify("pointerlock-acquired");
      }
      return snapshot("pointerlock-acquired");
    }
    if (mode === POINTER_MODES.RELATIVE || pointerLockRequested) {
      makeAbsolute("pointerlock-lost", { exitLock: false });
    }
    return snapshot("pointerlock-change");
  }

  function handlePointerLockError(event) {
    return lockFailure("pointerlock-error", event);
  }

  function currentDevice() {
    return mode === POINTER_MODES.ABSOLUTE ? absoluteButtonDevice : "mouse";
  }

  function wheelScale(deltaMode) {
    switch (deltaMode) {
      case WHEEL_DELTA_MODES.PIXEL: return 1;
      case WHEEL_DELTA_MODES.LINE: return 40;
      case WHEEL_DELTA_MODES.PAGE: return WHEEL_DETENT_UNITS;
      default: return null;
    }
  }

  function wholeWheelDetents(units) {
    const ratio = units / WHEEL_DETENT_UNITS;
    // A tiny tolerance makes repeated fractional WheelEvent values deterministic at an exact
    // detent boundary without ever changing the sign of an emitted event.
    if (ratio > 0) return Math.floor(ratio + 1e-9);
    if (ratio < 0) return Math.ceil(ratio - 1e-9);
    return 0;
  }

  function handleWheel(event) {
    const rawMode = event?.deltaMode ?? WHEEL_DELTA_MODES.PIXEL;
    const deltaMode = finiteNumber(rawMode);
    const scale = deltaMode !== null && Number.isInteger(deltaMode) ? wheelScale(deltaMode) : null;
    if (scale === null) {
      diagnostic("unsupported-wheel-mode", { deltaMode: rawMode });
      return { forwarded: false, consumed: false, reason: "unsupported-wheel-mode" };
    }

    const axes = [
      // Browser deltaX grows to the right; REL_HWHEEL keeps that natural horizontal sign.
      { name: "horizontal", value: finiteNumber(event?.deltaX ?? 0), code: REL_HWHEEL, direction: 1 },
      // Browser deltaY grows down; evdev REL_WHEEL +1 means up/away, so invert it.
      { name: "vertical", value: finiteNumber(event?.deltaY ?? 0), code: REL_WHEEL, direction: -1 },
    ];
    if (axes.some((axis) => axis.value === null)) {
      diagnostic("invalid-wheel-delta", { deltaMode });
      return { forwarded: false, consumed: false, reason: "invalid-wheel-delta" };
    }

    const nextRemainders = { ...wheelRemainders };
    const detents = { horizontal: 0, vertical: 0 };
    const events = [];
    let consumed = false;
    for (const axis of axes) {
      if (axis.value === 0) continue;
      consumed = true;
      const bounded = clamp(axis.value, -WHEEL_MAX_INPUT, WHEEL_MAX_INPUT);
      if (bounded !== axis.value) diagnostic("wheel-delta-clamped", { axis: axis.name, delta: axis.value });
      const combined = nextRemainders[axis.name] + bounded * scale * axis.direction;
      const whole = wholeWheelDetents(combined);
      nextRemainders[axis.name] = combined - whole * WHEEL_DETENT_UNITS;
      detents[axis.name] = whole;
      if (whole !== 0) events.push(eventRecord(EV_REL, axis.code, whole));
    }
    if (!consumed) return { forwarded: false, consumed: false, reason: "zero-wheel" };

    // Commit the bounded remainder even when the guest is not ready. There is no guest frame to
    // replay in that state, and retaining only the fractional detent avoids an unbounded pre-boot
    // accumulator while keeping the next live wheel event deterministic.
    wheelRemainders = nextRemainders;
    if (events.length === 0) {
      notify("wheel-accumulating");
      return { forwarded: false, consumed: true, reason: "wheel-accumulating", detents, remainders: { ...wheelRemainders } };
    }
    const frame = publish("mouse", events, { source: "wheel", deltaMode, detents });
    if (!frame) {
      notify("wheel-dropped");
      return { forwarded: false, consumed: true, reason: "not-forwarded", detents, remainders: { ...wheelRemainders } };
    }
    return { forwarded: true, consumed: true, frame, detents, remainders: { ...wheelRemainders } };
  }

  function handleFocusLoss(reason = "focus-loss") {
    const released = heldButtons.size;
    makeAbsolute(reason);
    return { mode, released, pointerLocked: pointerLocked(), heldButtons: snapshot(reason).heldButtons };
  }

  function handlePointerMove(event) {
    if (mode === POINTER_MODES.RELATIVE) {
      const movementX = finiteNumber(event?.movementX);
      const movementY = finiteNumber(event?.movementY);
      if (movementX === null || movementY === null) {
        diagnostic("invalid-relative-move", { eventType: event?.type ?? "" });
        return { forwarded: false, reason: "invalid-relative-move" };
      }
      const events = [];
      if (movementX !== 0) events.push(eventRecord(EV_REL, REL_X, Math.round(movementX)));
      if (movementY !== 0) events.push(eventRecord(EV_REL, REL_Y, Math.round(movementY)));
      const frame = publish("mouse", events, { source: "pointermove" });
      return frame ? { forwarded: true, frame } : { forwarded: false, reason: "not-forwarded" };
    }
    const coordinates = absoluteCoordinatesFromEvent(event, getRect());
    if (!coordinates) {
      diagnostic("invalid-absolute-rect", { eventType: event?.type ?? "" });
      return { forwarded: false, reason: "invalid-absolute-rect" };
    }
    const frame = publish("tablet", [
      eventRecord(EV_ABS, ABS_X, coordinates.x),
      eventRecord(EV_ABS, ABS_Y, coordinates.y),
    ], { source: "pointermove", coordinates });
    return frame ? { forwarded: true, frame, coordinates } : { forwarded: false, reason: "not-forwarded" };
  }

  function handlePointerDown(event) {
    const button = finiteNumber(event?.button);
    const evdev = evdevForPointerButton(button);
    if (evdev === null) {
      diagnostic("unsupported-pointer-button", { button });
      return { forwarded: false, reason: "unsupported-pointer-button" };
    }
    const key = pointerEventKey(event, button);
    if (heldButtons.has(key)) {
      diagnostic("duplicate-pointer-down", { button, pointerId: event?.pointerId });
      return { forwarded: false, reason: "duplicate-pointer-down", evdev };
    }
    const device = currentDevice();
    const frame = publish(device, [eventRecord(EV_KEY, evdev, 1)], {
      source: "pointerdown",
      button,
      evdev,
    });
    if (!frame) return { forwarded: false, reason: "not-forwarded", evdev };
    heldButtons.set(key, { key, button, evdev, device, pointerId: event?.pointerId ?? null });
    return { forwarded: true, frame, evdev };
  }

  function findHeldButton(event) {
    const button = finiteNumber(event?.button);
    const exact = pointerEventKey(event, button);
    if (heldButtons.has(exact)) return [exact, heldButtons.get(exact)];
    for (const [key, entry] of heldButtons) {
      if (entry.button === button) return [key, entry];
    }
    return [null, null];
  }

  function handlePointerUp(event) {
    const [key, entry] = findHeldButton(event);
    if (!entry) {
      diagnostic("orphan-pointer-up", { button: event?.button, pointerId: event?.pointerId });
      return { forwarded: false, reason: "orphan-pointer-up" };
    }
    const frame = publish(entry.device, [eventRecord(EV_KEY, entry.evdev, 0)], {
      source: "pointerup",
      button: entry.button,
      evdev: entry.evdev,
    });
    if (!frame) return { forwarded: false, reason: "not-forwarded", evdev: entry.evdev };
    heldButtons.delete(key);
    return { forwarded: true, frame, evdev: entry.evdev };
  }

  function handlePointerCancel(event) {
    const frames = releaseAll("pointercancel");
    if (mode === POINTER_MODES.RELATIVE || pointerLockRequested) {
      makeAbsolute("pointercancel");
    } else {
      notify("pointercancel");
    }
    return { forwarded: frames.length > 0, frames, mode };
  }

  function handleContextMenu(event) {
    try { event?.preventDefault?.(); } catch (error) {
      diagnostic("contextmenu-prevent-error", { error: error?.message || String(error) });
    }
    return true;
  }

  function reset({ emit = false, exitLock = true } = {}) {
    if (emit) releaseAll("reset");
    else heldButtons.clear();
    pointerLockRequested = false;
    mode = POINTER_MODES.ABSOLUTE;
    wheelRemainders = { horizontal: 0, vertical: 0 };
    if (exitLock && pointerLocked()) exitPointerLock();
    notify("reset");
  }

  return {
    setTarget(value) { pointerTarget = value; },
    setDocumentTarget(value) { pointerDocument = value; },
    mode: () => mode,
    state: () => snapshot(),
    isPointerLocked: pointerLocked,
    setMode,
    toggleMode,
    requestRelative: () => setMode(POINTER_MODES.RELATIVE),
    exitRelative: () => setMode(POINTER_MODES.ABSOLUTE, { reason: "relative-cancelled" }),
    handlePointerLockChange,
    handlePointerLockError,
    handlePointerMove,
    handleWheel,
    handlePointerDown,
    handlePointerUp,
    handlePointerCancel,
    handleFocusLoss,
    handleContextMenu,
    wheelRemainders: () => ({ ...wheelRemainders }),
    releaseAll,
    reset,
    heldButtons: () => [...heldButtons.values()].map((entry) => ({ ...entry })),
  };
}

/** Attach the bridge to a DOM pointer surface and its Pointer Lock lifecycle. */
export function attachPointerBridge(
  target,
  bridge,
  {
    documentTarget = globalThis.document,
    windowTarget = globalThis.window,
    capture = true,
    preventDefault = true,
  } = {},
) {
  if (!target || typeof target.addEventListener !== "function") {
    throw new TypeError("pointer bridge target must support addEventListener");
  }
  if (typeof bridge?.handlePointerMove !== "function") {
    throw new TypeError("pointer bridge requires handlePointerMove");
  }
  bridge.setTarget?.(target);
  bridge.setDocumentTarget?.(documentTarget);
  const options = { capture, passive: false };
  const onMove = (event) => {
    const result = bridge.handlePointerMove(event);
    if (preventDefault && result?.forwarded) event.preventDefault?.();
  };
  const onWheel = (event) => {
    const result = bridge.handleWheel?.(event);
    if (preventDefault && result?.consumed) event.preventDefault?.();
  };
  const onDown = (event) => {
    const result = bridge.handlePointerDown(event);
    if (!result?.forwarded) return;
    if (preventDefault) event.preventDefault?.();
    try { target.setPointerCapture?.(event.pointerId); } catch { /* capture is an enhancement */ }
  };
  const onUp = (event) => {
    const result = bridge.handlePointerUp(event);
    if (preventDefault && result?.forwarded) event.preventDefault?.();
    try { target.releasePointerCapture?.(event.pointerId); } catch { /* capture is an enhancement */ }
  };
  const onCancel = (event) => {
    const result = bridge.handlePointerCancel(event);
    if (preventDefault && result?.forwarded) event.preventDefault?.();
    try { target.releasePointerCapture?.(event.pointerId); } catch { /* capture is an enhancement */ }
  };
  const onContextMenu = (event) => bridge.handleContextMenu(event);
  const onLockChange = () => bridge.handlePointerLockChange();
  const onLockError = (event) => bridge.handlePointerLockError(event);
  const onBlur = () => bridge.handleFocusLoss?.("blur");
  const onVisibilityChange = () => {
    if (documentTarget?.hidden === true || documentTarget?.visibilityState === "hidden") {
      bridge.handleFocusLoss?.("visibility-hidden");
    }
  };
  const viewTarget = windowTarget ?? documentTarget;
  const onViewToggle = () => bridge.handleFocusLoss?.("view-toggle");
  target.addEventListener("pointermove", onMove, options);
  target.addEventListener("wheel", onWheel, options);
  target.addEventListener("pointerdown", onDown, options);
  target.addEventListener("pointerup", onUp, options);
  target.addEventListener("pointercancel", onCancel, options);
  target.addEventListener("contextmenu", onContextMenu, options);
  documentTarget?.addEventListener?.("pointerlockchange", onLockChange, options);
  documentTarget?.addEventListener?.("pointerlockerror", onLockError, options);
  windowTarget?.addEventListener?.("blur", onBlur, options);
  documentTarget?.addEventListener?.("visibilitychange", onVisibilityChange, options);
  viewTarget?.addEventListener?.("wvm:reserved-view-toggle", onViewToggle, options);
  return () => {
    target.removeEventListener?.("pointermove", onMove, options);
    target.removeEventListener?.("wheel", onWheel, options);
    target.removeEventListener?.("pointerdown", onDown, options);
    target.removeEventListener?.("pointerup", onUp, options);
    target.removeEventListener?.("pointercancel", onCancel, options);
    target.removeEventListener?.("contextmenu", onContextMenu, options);
    documentTarget?.removeEventListener?.("pointerlockchange", onLockChange, options);
    documentTarget?.removeEventListener?.("pointerlockerror", onLockError, options);
    windowTarget?.removeEventListener?.("blur", onBlur, options);
    documentTarget?.removeEventListener?.("visibilitychange", onVisibilityChange, options);
    viewTarget?.removeEventListener?.("wvm:reserved-view-toggle", onViewToggle, options);
    bridge.reset?.({ emit: false, exitLock: true });
  };
}

// E5-T06d: runtime presentation selection and context-loss recovery.

import { Canvas2DBackend } from "./canvas2d.js";
import { WebGL2Backend } from "./webgl.js";
import { FrameScheduler } from "./frame-scheduler.js";
import { VisibilityFrameScheduler } from "./visibility-scheduler.js";
import { checkedDisplaySize, fitFrameToViewport } from "./viewport.js";

const DEFAULT_WIDTH = 1280;
const DEFAULT_HEIGHT = 800;
const BACKEND_NAMES = Object.freeze(["canvas2d", "webgl2"]);
const FORMAT_B8G8R8X8_UNORM = 2;

function checkedDimension(value, name) {
  if (!Number.isSafeInteger(value) || value < 1) {
    throw new RangeError(`${name} must be a positive safe integer`);
  }
  return value;
}

function checkedFrame(frame) {
  if (frame === null || typeof frame !== "object") {
    throw new TypeError("presentation frame must be an object");
  }
  const width = checkedDimension(Number(frame.resourceWidth), "resource width");
  const height = checkedDimension(Number(frame.resourceHeight), "resource height");
  const format = Number(frame.format ?? 1);
  if (!Number.isSafeInteger(format) || format < 1) {
    throw new RangeError("presentation frame format must be a positive safe integer");
  }
  const rect = frame.rect;
  if (rect === null || typeof rect !== "object") {
    throw new TypeError("presentation frame rect is missing");
  }
  const checkedRect = Object.freeze({
    x: Number(rect.x),
    y: Number(rect.y),
    width: Number(rect.width),
    height: Number(rect.height),
  });
  for (const [name, value] of Object.entries(checkedRect)) {
    if (!Number.isSafeInteger(value) || value < 0 || (name === "width" || name === "height") && value < 1) {
      throw new RangeError(`presentation rect ${name} is invalid`);
    }
  }
  if (checkedRect.x + checkedRect.width > width || checkedRect.y + checkedRect.height > height) {
    throw new RangeError("presentation rect is outside the resource");
  }
  const expected = width * height;
  if (!Number.isSafeInteger(expected)) throw new RangeError("presentation frame is too large");
  if (frame.pixels === null || frame.pixels === undefined || frame.pixels.length !== expected) {
    throw new RangeError(`presentation pixel count does not match ${width}x${height}`);
  }
  // Rust's callback supplies a temporary wasm-memory view. Copy it before any backend call so the
  // latest frame remains valid across a WebGL context loss and later guest memory growth.
  const pixels = frame.pixels instanceof Uint32Array
    ? new Uint32Array(frame.pixels)
    : Uint32Array.from(frame.pixels);
  // Linux's B8G8R8X8_UNORM fbcon surface uses the high byte as padding. The guest is allowed to
  // leave that X byte zero, but browser ImageData treats it as alpha, so normalize it to opaque at
  // the presentation boundary before Canvas2D or WebGL2 consumes the copied frame.
  if (format === FORMAT_B8G8R8X8_UNORM) {
    for (let index = 0; index < pixels.length; index += 1) pixels[index] |= 0xff000000;
  }
  return Object.freeze({
    scanout: frame.scanout == null ? null : Number(frame.scanout),
    format,
    rect: checkedRect,
    resourceWidth: width,
    resourceHeight: height,
    pixels,
  });
}

function disposeQuietly(backend, errors) {
  if (!backend || typeof backend.dispose !== "function") return;
  try {
    backend.dispose();
  } catch (error) {
    errors.push(String(error?.message || error));
  }
}

/**
 * Own the selected browser presentation backend and the one-frame recovery policy.
 *
 * Canvas2D is the measured default from E5-T06c. WebGL2 is attempted when explicitly requested or
 * when Canvas2D is unavailable. A real WebGL canvas cannot change context type after creation, so
 * context-loss recovery replaces that element with a same-attribute canvas before activating the
 * Canvas2D backend. The controller owns that replacement and its event listeners.
 */
export class PresentationController {
  constructor(canvas, options = {}) {
    if (canvas === null || typeof canvas !== "object" || typeof canvas.getContext !== "function") {
      throw new TypeError("PresentationController requires a canvas-like object");
    }
    const defaultBackend = options.defaultBackend ?? "canvas2d";
    if (!BACKEND_NAMES.includes(defaultBackend)) {
      throw new RangeError(`unknown presentation backend: ${defaultBackend}`);
    }
    this.canvas = canvas;
    this.defaultBackend = defaultBackend;
    this._factories = {
      canvas2d: options.backendFactories?.canvas2d
        ?? ((target) => new Canvas2DBackend(target, options.canvas2dOptions)),
      webgl2: options.backendFactories?.webgl2
        ?? ((target) => new WebGL2Backend(target, options.webgl2Options)),
    };
    this._width = checkedDimension(
      Number(options.width ?? (canvas.width > 0 ? canvas.width : DEFAULT_WIDTH)),
      "canvas width",
    );
    this._height = checkedDimension(
      Number(options.height ?? (canvas.height > 0 ? canvas.height : DEFAULT_HEIGHT)),
      "canvas height",
    );
    this._backend = null;
    this._backendName = null;
    this._latest = null;
    this._paintedResource = null;
    this._fixedViewport = false;
    this._disposed = false;
    this._contextLost = false;
    this._lossDropCounted = false;
    this._listenerCanvas = null;
    this._errors = [];
    this._framesReceived = 0;
    this._successfulPresents = 0;
    this._replayedFrames = 0;
    this._droppedFrames = 0;
    this._fallbacks = 0;
    this._contextLosses = 0;
    this._contextRestores = 0;
    this._uploadedBytes = 0;
    this._drawnPresents = 0;
    this._drawnBytes = 0;
    this._presentationSequence = 0;
    this._onPresent = typeof options.onPresent === "function" ? options.onPresent : null;
    this._now = typeof options.now === "function" ? options.now : null;
    this._guestInstructions = typeof options.guestInstructions === "function" ? options.guestInstructions : null;
    this._lastGuestInstructions = null;
    this._statsOwner = options.vm ?? null;
    if (this._statsOwner !== null && (typeof this._statsOwner !== "object" || Array.isArray(this._statsOwner))) {
      throw new TypeError("PresentationController vm must be an object");
    }
    const schedulerOptions = {
      present: (frame) => this._deliver(frame),
      requestFrame: options.requestFrame,
      cancelFrame: options.cancelFrame,
      onError: options.onSchedulerError
        ?? ((error) => this._errors.push(`scheduled present: ${String(error?.message || error)}`)),
    };
    this._scheduler = options.scheduleFrames
      ? options.visibilityTarget
        ? new VisibilityFrameScheduler({
          present: schedulerOptions.present,
          visibilityTarget: options.visibilityTarget,
          isHidden: options.isHidden,
          requestAnimationFrame: options.requestAnimationFrame ?? options.requestFrame,
          cancelAnimationFrame: options.cancelAnimationFrame ?? options.cancelFrame,
          setTimeout: options.setTimeout,
          clearTimeout: options.clearTimeout,
          now: options.now,
          timerMs: options.timerMs,
          onError: schedulerOptions.onError,
        })
        : new FrameScheduler(schedulerOptions)
      : null;
    this._installStatsSurface();
    this._attachCanvasListeners();
    this._ensureCanvasSize();
    this._activateWithFallback(defaultBackend);
  }

  _ensureCanvasSize() {
    if (this.canvas.width !== this._width) this.canvas.width = this._width;
    if (this.canvas.height !== this._height) this.canvas.height = this._height;
  }

  _attachCanvasListeners() {
    this._detachCanvasListeners();
    if (typeof this.canvas.addEventListener !== "function") return;
    this._onContextLost = (event) => this._handleContextLost(event);
    this._onContextRestored = (event) => this._handleContextRestored(event);
    this.canvas.addEventListener("webglcontextlost", this._onContextLost, false);
    this.canvas.addEventListener("webglcontextrestored", this._onContextRestored, false);
    this._listenerCanvas = this.canvas;
  }

  _detachCanvasListeners() {
    if (!this._listenerCanvas || typeof this._listenerCanvas.removeEventListener !== "function") return;
    this._listenerCanvas.removeEventListener("webglcontextlost", this._onContextLost, false);
    this._listenerCanvas.removeEventListener("webglcontextrestored", this._onContextRestored, false);
    this._listenerCanvas = null;
  }

  _activate(name) {
    const factory = this._factories[name];
    if (typeof factory !== "function") throw new TypeError(`presentation factory ${name} is unavailable`);
    const candidate = factory(this.canvas);
    if (candidate === null || typeof candidate !== "object" ||
        typeof candidate.present !== "function" || typeof candidate.resize !== "function") {
      throw new TypeError(`presentation factory ${name} returned an invalid backend`);
    }
    if (candidate.width !== this._width || candidate.height !== this._height) {
      candidate.resize(this._width, this._height);
    }
    const prior = this._backend;
    this._backend = candidate;
    this._backendName = name;
    this._paintedResource = null;
    disposeQuietly(prior, this._errors);
  }

  _activateWithFallback(preferred) {
    const order = [preferred, ...BACKEND_NAMES.filter((name) => name !== preferred)];
    let failure = null;
    for (const name of order) {
      try {
        this._activate(name);
        if (name !== preferred) this._fallbacks += 1;
        return name;
      } catch (error) {
        failure = error;
        this._errors.push(`${name}: ${String(error?.message || error)}`);
      }
    }
    throw new Error(`no presentation backend is available: ${String(failure?.message || failure)}`);
  }

  _replaceCanvasForFallback() {
    const oldCanvas = this.canvas;
    const parent = oldCanvas.parentNode;
    if (!parent || typeof oldCanvas.cloneNode !== "function" || typeof parent.replaceChild !== "function") {
      // Dependency-injected test canvases may support both context types on one object. Real DOM
      // canvases take the replacement path above; retaining this path keeps the controller testable.
      return false;
    }
    const replacement = oldCanvas.cloneNode(false);
    replacement.width = this._width;
    replacement.height = this._height;
    parent.replaceChild(replacement, oldCanvas);
    this._detachCanvasListeners();
    this.canvas = replacement;
    this._attachCanvasListeners();
    return true;
  }

  _fallbackToCanvas() {
    this._disposeBackend();
    const replaced = this._replaceCanvasForFallback();
    this._activate("canvas2d");
    this._fallbacks += 1;
    this._contextLost = false;
    this._lossDropCounted = false;
    if (this._latest) {
      // A replacement canvas starts transparent. If the lost WebGL frame was a partial update,
      // replay the retained full-resource source across the whole new surface so unchanged pixels
      // are not lost during the backend transition.
      const replay = replaced
        ? { ...this._latest, rect: { x: 0, y: 0,
          width: this._latest.resourceWidth, height: this._latest.resourceHeight } }
        : this._latest;
      this._deliver(replay, true);
    }
  }

  _guestInstructionAttribution() {
    if (!this._guestInstructions) return { total: null, delta: null };
    let value;
    try {
      const raw = this._guestInstructions();
      value = raw !== null && typeof raw === "object"
        ? raw.retiredInstructions ?? raw.guestInstructions
        : raw;
    } catch (error) {
      let detail = "unavailable";
      try {
        detail = String(error?.message || error);
      } catch {
        try { detail = String(error); } catch { /* retain the safe fallback */ }
      }
      this._errors.push(`guest instruction telemetry: ${detail}`);
      return { total: null, delta: null };
    }
    if (typeof value !== "number" || !Number.isSafeInteger(value) || value < 0) {
      return { total: null, delta: null };
    }
    const total = value;
    const delta = this._lastGuestInstructions === null
      ? total
      : total >= this._lastGuestInstructions ? total - this._lastGuestInstructions : null;
    this._lastGuestInstructions = total;
    return { total, delta };
  }

  _disposeBackend() {
    const backend = this._backend;
    this._backend = null;
    this._backendName = null;
    disposeQuietly(backend, this._errors);
  }

  _handleContextLost(event) {
    if (this._disposed || this._backendName !== "webgl2") return;
    event?.preventDefault?.();
    this._contextLosses += 1;
    this._contextLost = true;
    this._lossDropCounted = false;
    try {
      this._fallbackToCanvas();
    } catch (error) {
      this._errors.push(`context-loss recovery: ${String(error?.message || error)}`);
    }
  }

  _handleContextRestored(_event) {
    if (this._disposed) return;
    this._contextRestores += 1;
    // A recovered WebGL context is deliberately not reselected: the new Canvas2D element is the
    // stable fallback surface, and replaying the latest frame there avoids a second transition.
    if (this._backendName === "canvas2d") this._contextLost = false;
  }

  _deliver(frame, replay = false) {
    if (!this._backend || this._contextLost) {
      if (!this._lossDropCounted) {
        this._droppedFrames += 1;
        this._lossDropCounted = true;
      }
      return false;
    }
    try {
      // Decide at paint time, not receipt time: the scheduler can replace any pending
      // full repaint with a newer partial frame before its animation callback runs.
      // Until a resource size has actually reached this backend, replay its full copy.
      const repaint = (!this._paintedResource ||
        this._paintedResource.width !== frame.resourceWidth ||
        this._paintedResource.height !== frame.resourceHeight)
        ? { ...frame, rect: { x: 0, y: 0, width: frame.resourceWidth, height: frame.resourceHeight } }
        : frame;
      const fitted = this._fixedViewport ? fitFrameToViewport(repaint, this._width, this._height) : repaint;
      this._backend.present(fitted.rect, fitted.pixels);
      this._paintedResource = { width: frame.resourceWidth, height: frame.resourceHeight };
      this._successfulPresents += 1;
      const bytes = fitted.rect.width * fitted.rect.height * 4;
      this._uploadedBytes += bytes;
      const drawn = typeof this._backend.drawsPixels === "function"
        ? Boolean(this._backend.drawsPixels())
        : true;
      if (drawn) {
        this._drawnPresents += 1;
        this._drawnBytes += bytes;
      }
      const guest = this._guestInstructionAttribution();
      if (replay) this._replayedFrames += 1;
      this._lossDropCounted = false;
      if (this._onPresent) {
        const timestamp = this._now
          ? Number(this._now())
          : (typeof globalThis.performance?.now === "function" ? globalThis.performance.now() : Date.now());
        const record = Object.freeze({
          sequence: ++this._presentationSequence,
          timestamp,
          backend: this._backendName,
          drawn,
          replay,
          rect: Object.freeze({ ...fitted.rect }),
          resourceWidth: frame.resourceWidth,
          resourceHeight: frame.resourceHeight,
          bytes,
          guestInstructions: guest.delta,
          guestInstructionsTotal: guest.total,
        });
        try {
          this._onPresent(record);
        } catch (error) {
          this._errors.push(`present telemetry: ${String(error?.message || error)}`);
        }
      }
      return true;
    } catch (error) {
      this._errors.push(`present via ${this._backendName}: ${String(error?.message || error)}`);
      if (this._backendName === "webgl2") {
        try {
          this._fallbackToCanvas();
          return true;
        } catch (fallbackError) {
          this._errors.push(`present fallback: ${String(fallbackError?.message || fallbackError)}`);
        }
      }
      this._droppedFrames += 1;
      return false;
    }
  }

  _installStatsSurface() {
    if (!this._statsOwner) return;
    if (!this._statsOwner.stats || typeof this._statsOwner.stats !== "object") this._statsOwner.stats = {};
    const stats = this._statsOwner.stats;
    try {
      Object.defineProperty(stats, "gpu", {
        configurable: true,
        enumerable: true,
        get: () => this._gpuStats(),
      });
    } catch {
      // A host may provide a non-configurable stats object. Keep the public value useful without
      // retaining a backend/canvas reference in the serialized snapshot.
      stats.gpu = this._gpuStats();
    }
  }

  _gpuStats() {
    const scheduler = this._scheduler?.snapshot();
    return {
      framesReceived: this._framesReceived,
      enqueued: scheduler?.enqueued ?? this._framesReceived,
      coalesced: scheduler?.coalesced ?? 0,
      presented: scheduler?.presented ?? this._successfulPresents,
      successfulPresents: this._successfulPresents,
      skipped: scheduler?.skipped ?? this._droppedFrames,
      droppedFrames: this._droppedFrames,
      overruns: scheduler?.overruns ?? 0,
      pending: scheduler?.pending ?? 0,
      maxPending: scheduler?.maxPending ?? 0,
      uploadedBytes: this._uploadedBytes,
      drawnPresents: this._drawnPresents,
      drawnBytes: this._drawnBytes,
      width: this._width,
      height: this._height,
    };
  }

  /** Publish one full-resource frame and return whether it reached a backend. */
  present(frame) {
    if (this._disposed) throw new Error("PresentationController is disposed");
    if (frame !== null && typeof frame === "object" && frame.type === "clear") {
      return this.clear();
    }
    if (frame !== null && typeof frame === "object" && frame.type === "invalidate") {
      return this.invalidate();
    }
    const checked = checkedFrame(frame);
    this._framesReceived += 1;
    if (!this._fixedViewport && (checked.resourceWidth !== this._width || checked.resourceHeight !== this._height)) {
      this.resize(checked.resourceWidth, checked.resourceHeight);
    }
    this._latest = checked;
    return this._scheduler ? this._scheduler.enqueue(checked) : this._deliver(checked);
  }

  /** A retained renderer frame is already paced by its host owner. Deliver on that owner's rAF. */
  presentNow(frame) {
    if (this._disposed) throw new Error("PresentationController is disposed");
    const checked = checkedFrame(frame);
    this._framesReceived += 1;
    this._scheduler?.discardPending();
    if (!this._fixedViewport && (checked.resourceWidth !== this._width || checked.resourceHeight !== this._height)) {
      this.resize(checked.resourceWidth, checked.resourceHeight);
    }
    this._latest = checked;
    return this._deliver(checked);
  }

  /** Revoke queued/recovery pixels while the displayed front buffer stays visible. */
  invalidate() {
    if (this._disposed) throw new Error("PresentationController is disposed");
    this._scheduler?.discardPending();
    this._latest = null;
    this._paintedResource = null;
    return true;
  }

  /** Explicit disable/reset also erases the visible front buffer. */
  clear() {
    this.invalidate();
    if (this._backend) this._backend.resize(this._width, this._height);
    else this._ensureCanvasSize();
    return true;
  }

  /** Resize the visible target and backend resource. */
  setViewport(width, height) {
    if (this._disposed) throw new Error("PresentationController is disposed");
    checkedDisplaySize(width, height);
    this._fixedViewport = true;
    if (width !== this._width || height !== this._height) {
      this.resize(width, height);
      if (this._latest) {
        this._deliver({ ...this._latest, rect: { x: 0, y: 0,
          width: this._latest.resourceWidth, height: this._latest.resourceHeight } }, true);
      }
    }
    return { width, height };
  }

  /** Legacy resource-following resize; viewport users call setViewport instead. */
  resize(width, height) {
    if (this._disposed) throw new Error("PresentationController is disposed");
    const nextWidth = checkedDimension(Number(width), "canvas width");
    const nextHeight = checkedDimension(Number(height), "canvas height");
    if (this._scheduler && (nextWidth !== this._width || nextHeight !== this._height)) {
      // A queued frame contains a full-resource pixel view. It cannot be presented after the
      // backend has changed dimensions, so retire it before resizing the target.
      this._scheduler.discardPending();
    }
    this._width = nextWidth;
    this._height = nextHeight;
    this._paintedResource = null;
    if (this._backend) {
      this._backend.resize(this._width, this._height);
    } else {
      this._ensureCanvasSize();
    }
    return { width: this._width, height: this._height };
  }

  /** Return a compact, JSON-safe diagnostic snapshot for browser evidence. */
  snapshot() {
    return {
      backend: this._backendName,
      defaultBackend: this.defaultBackend,
      width: this._width,
      height: this._height,
      fixedViewport: this._fixedViewport,
      sizeMismatch: Boolean(this._latest &&
        (!this._paintedResource || this._paintedResource.width !== this._width ||
          this._paintedResource.height !== this._height)),
      framesReceived: this._framesReceived,
      successfulPresents: this._successfulPresents,
      drawnPresents: this._drawnPresents,
      drawnBytes: this._drawnBytes,
      replayedFrames: this._replayedFrames,
      droppedFrames: this._droppedFrames,
      contextLosses: this._contextLosses,
      contextRestores: this._contextRestores,
      fallbacks: this._fallbacks,
      listenerCount: this._listenerCanvas ? 2 : 0,
      scheduler: this._scheduler?.snapshot() ?? null,
      gpu: this._gpuStats(),
      latest: this._latest
        ? { rect: this._latest.rect, resourceWidth: this._latest.resourceWidth, resourceHeight: this._latest.resourceHeight }
        : null,
      errors: [...this._errors],
    };
  }

  /** Read the visible RGBA surface when the active backend exposes a readback API. */
  readPixels() {
    if (this._disposed) throw new Error("PresentationController is disposed");
    if (this._backendName === "canvas2d") {
      const context = this.canvas.getContext("2d");
      if (!context || typeof context.getImageData !== "function") throw new Error("2D readback unavailable");
      return new Uint8ClampedArray(context.getImageData(0, 0, this._width, this._height).data);
    }
    if (this._backendName === "webgl2" && this._backend?.gl) {
      const output = new Uint8Array(this._width * this._height * 4);
      this._backend.gl.readPixels(0, 0, this._width, this._height, this._backend.gl.RGBA, this._backend.gl.UNSIGNED_BYTE, output);
      return output;
    }
    throw new Error("presentation readback unavailable");
  }

  dispose() {
    if (this._disposed) return;
    this._disposed = true;
    this._scheduler?.dispose();
    this._detachCanvasListeners();
    this._disposeBackend();
    this._latest = null;
    this._paintedResource = null;
  }

  /** Pause/resume the optional page-owned display drain without affecting guest frame receipt. */
  pause() {
    return this._scheduler?.pause() ?? false;
  }

  resume() {
    return this._scheduler?.resume() ?? false;
  }

  /** Drop a queued test or resize frame without disturbing the retained latest resource. */
  discardPending() {
    return this._scheduler?.discardPending() ?? false;
  }

  visibilityChanged() {
    return this._scheduler?.visibilityChanged?.() ?? false;
  }

  get backendName() {
    return this._backendName;
  }

  get backend() {
    return this._backend;
  }
}

// E5-T22b: viewport policy is independent of whether a guest compositor adopted a mode.
export const DISPLAY_MIN_WIDTH = 320;
export const DISPLAY_MIN_HEIGHT = 240;
export const DISPLAY_MAX_DIMENSION = 4095;
export const DISPLAY_DEBOUNCE_MS = 250;

export function checkedDisplaySize(width, height) {
  for (const value of [width, height]) {
    if (!Number.isInteger(value) || value < 1 || value > DISPLAY_MAX_DIMENSION) {
      throw new RangeError("display dimensions must be integers in 1..4095");
    }
  }
  return { width, height };
}

export function viewportPixelMode(cssWidth, cssHeight, dpr) {
  if (![cssWidth, cssHeight, dpr].every(Number.isFinite) || cssWidth < 0 || cssHeight < 0 || dpr <= 0) {
    throw new RangeError("viewport dimensions and DPR must be finite and non-negative (DPR > 0)");
  }
  // Hidden/collapsed panes have no current viewport and must not hotplug a minimum mode.
  if (cssWidth === 0 || cssHeight === 0) return null;
  const width = Math.min(DISPLAY_MAX_DIMENSION, Math.max(DISPLAY_MIN_WIDTH, Math.round(cssWidth * dpr)));
  const height = Math.min(DISPLAY_MAX_DIMENSION, Math.max(DISPLAY_MIN_HEIGHT, Math.round(cssHeight * dpr)));
  if (!Number.isFinite(width / dpr) || !Number.isFinite(height / dpr)) throw new RangeError("DPR is too small");
  return { width, height, dpr, cssWidth: width / dpr, cssHeight: height / dpr };
}

/**
 * Pick a bounded desktop scanout for a responsive browser surface.
 *
 * A desktop canvas is often shown in a narrow or high-DPR browser pane. Mirroring that pane
 * directly into the guest can request pathological modes such as 2200x2162, which makes a cold
 * graphical boot spend its whole budget copying an oversized framebuffer. Keep the guest's
 * 16:10 desktop mode bounded, then scale it to the available CSS box. Input remains normalized
 * against the canvas rectangle, so the CSS scaling is transparent to the guest.
 */
export function desktopViewportPixelMode(cssWidth, cssHeight, dpr, {
  maxWidth = 1280,
  maxHeight = 800,
} = {}) {
  if (![cssWidth, cssHeight, dpr, maxWidth, maxHeight].every(Number.isFinite) ||
      cssWidth < 0 || cssHeight < 0 || dpr <= 0 ||
      !Number.isInteger(maxWidth) || !Number.isInteger(maxHeight) ||
      maxWidth < DISPLAY_MIN_WIDTH || maxHeight < DISPLAY_MIN_HEIGHT ||
      maxWidth > DISPLAY_MAX_DIMENSION || maxHeight > DISPLAY_MAX_DIMENSION) {
    throw new RangeError("desktop viewport dimensions and limits must be finite and positive");
  }
  if (cssWidth === 0 || cssHeight === 0) return null;
  const aspectRatio = maxWidth / maxHeight;
  const fitWidth = Math.min(cssWidth, cssHeight * aspectRatio);
  const fitHeight = fitWidth / aspectRatio;
  return { width: maxWidth, height: maxHeight, dpr: 1, cssWidth: fitWidth, cssHeight: fitHeight };
}

/** Native-pixel top-left fit. Input has already passed the full-resource frame validator. */
export function fitFrameToViewport(frame, width, height) {
  checkedDisplaySize(width, height);
  if (frame.resourceWidth === width && frame.resourceHeight === height) return frame;
  const pixels = new Uint32Array(width * height);
  pixels.fill(0xff000000);
  const columns = Math.min(width, frame.resourceWidth);
  const rows = Math.min(height, frame.resourceHeight);
  for (let row = 0; row < rows; row++) {
    const start = row * frame.resourceWidth;
    pixels.set(frame.pixels.subarray(start, start + columns), row * width);
  }
  return { ...frame, resourceWidth: width, resourceHeight: height,
    rect: { x: 0, y: 0, width, height }, pixels };
}

/** Map pointer coordinates to the old guest resource during a clipped/letterboxed transition. */
export function nativeContentRect(containerRect, resourceWidth, resourceHeight, dpr) {
  if (![resourceWidth, resourceHeight, dpr].every(Number.isFinite) ||
      resourceWidth <= 0 || resourceHeight <= 0 || dpr <= 0) return null;
  return { left: containerRect.left, top: containerRect.top,
    width: resourceWidth / dpr, height: resourceHeight / dpr };
}

export class DisplayViewportController {
  constructor({ container, presentation, controller = null, onState = () => {},
    ResizeObserverClass = globalThis.ResizeObserver,
    matchMedia = globalThis.matchMedia?.bind(globalThis),
    getDpr = () => globalThis.devicePixelRatio || 1,
    modeForRect = viewportPixelMode,
    setTimer = globalThis.setTimeout.bind(globalThis), clearTimer = globalThis.clearTimeout.bind(globalThis),
    testDebounceMs = undefined,
  } = {}) {
    if (!container?.getBoundingClientRect || !presentation?.setViewport ||
        typeof ResizeObserverClass !== "function" || typeof matchMedia !== "function") {
      throw new TypeError("viewport requires a container, presentation, ResizeObserver and matchMedia");
    }
    if (testDebounceMs !== undefined && testDebounceMs !== 0) throw new RangeError("only the explicit zero-delay test hook is supported");
    if (typeof modeForRect !== "function") throw new TypeError("viewport modeForRect must be a function");
    this.container = container;
    this.presentation = presentation;
    this._controller = controller;
    this._onState = onState;
    this._getDpr = getDpr;
    this._modeForRect = modeForRect;
    this._matchMedia = matchMedia;
    this._setTimer = setTimer;
    this._clearTimer = clearTimer;
    this._delay = testDebounceMs ?? DISPLAY_DEBOUNCE_MS;
    this._timer = null;
    this._dprTimer = null;
    this._media = null;
    this._disposed = false;
    this._sequence = 0;
    this._desired = null;
    this._due = false;
    this._inFlight = null;
    this._requested = null;
    this._accepted = null;
    this._requests = 0;
    this._error = null;
    this._onDpr = () => { if (!this._disposed) { this._watchDpr(); this.measure(); } };
    this._observer = new ResizeObserverClass(() => this.measure());
    try {
      this._watchDpr();
      this._observer.observe(container);
      this.measure();
      this._pollDpr();
    } catch (error) {
      this._observer.disconnect();
      this._media?.removeEventListener("change", this._onDpr);
      throw error;
    }
  }

  _watchDpr() {
    this._media?.removeEventListener("change", this._onDpr);
    this._watchedDpr = this._getDpr();
    this._media = this._matchMedia("(resolution: " + this._watchedDpr + "dppx)");
    this._media.addEventListener("change", this._onDpr);
  }

  _pollDpr() {
    if (this._disposed) return;
    // A scale-factor change can update devicePixelRatio without a resolution change event
    // (observed with Chrome device emulation). One low-frequency scalar check covers that path.
    this._dprTimer = this._setTimer(() => {
      this._dprTimer = null;
      if (this._disposed) return;
      if (this._getDpr() !== this._watchedDpr) this._onDpr();
      this._pollDpr();
    }, 250);
  }

  _notify() {
    try { this._onState(this.snapshot()); } catch { /* diagnostics do not control device state */ }
  }

  measure() {
    if (this._disposed) return null;
    const rect = this.container.getBoundingClientRect();
    const next = this._modeForRect(rect.width, rect.height, this._getDpr());
    if (!next) {
      this._clearPending();
      this._desired = null;
      this._notify();
      return null;
    }
    if (this._desired && ["width", "height", "dpr"].every((key) => this._desired[key] === next[key])) {
      // A capped desktop backing stays 1280×800 while the browser window can still grow/shrink.
      // Resize its CSS projection without clearing the guest pixels or emitting another hotplug.
      this._desired = { ...this._desired, cssWidth: next.cssWidth, cssHeight: next.cssHeight };
      this.applyCanvasStyle();
      return next;
    }
    this._desired = { ...next, sequence: ++this._sequence };
    this._error = null;
    this.presentation.setViewport(next.width, next.height);
    this.applyCanvasStyle();
    this._clearPending();
    this._timer = this._setTimer(() => {
      this._timer = null;
      this._due = true;
      void this._drain();
    }, this._delay);
    this._notify();
    return next;
  }

  // A WebGL context replacement copies styles, but callers may also reapply them after a frame.
  applyCanvasStyle() {
    if (!this._desired || this._disposed) return;
    const style = this.presentation.canvas.style;
    if (style) {
      style.width = this._desired.cssWidth + "px";
      style.height = this._desired.cssHeight + "px";
      style.maxWidth = "none";
      style.maxHeight = "none";
    }
  }

  _clearPending() {
    if (this._timer !== null) this._clearTimer(this._timer);
    this._timer = null;
    this._due = false;
  }

  setController(controller) {
    if (this._disposed) return;
    this._clearPending();
    this._controller = controller;
    this._inFlight = null;
    this._requested = null;
    this._accepted = null;
    this._error = null;
    // Initial mode is sent before the caller resumes a paused/new guest. Later resizes debounce.
    this._due = this._desired !== null;
    return this._drain();
  }

  async _drain() {
    if (this._disposed || !this._due || this._inFlight || !this._controller || !this._desired) return;
    const mode = this._desired;
    const controller = this._controller;
    const token = {}; // Identity fences completions from replaced/disposed controllers.
    this._due = false;
    this._inFlight = token;
    this._requested = mode;
    this._requests++;
    this._notify();
    try {
      const accepted = await controller.setDisplay(mode.width, mode.height);
      if (this._inFlight === token && this._desired?.sequence === mode.sequence) {
        this._accepted = accepted ? mode : null;
        this._error = accepted ? null : "GPU unavailable";
      }
    } catch (error) {
      if (this._inFlight === token && this._desired?.sequence === mode.sequence) this._error = String(error);
    } finally {
      if (this._inFlight === token) {
        this._inFlight = null;
        this._notify();
        void this._drain();
      }
    }
  }

  pointerRect() {
    const latest = this.presentation.snapshot().latest;
    const mode = this._desired;
    return mode && nativeContentRect(this.container.getBoundingClientRect(),
      latest?.resourceWidth ?? mode.width, latest?.resourceHeight ?? mode.height, mode.dpr);
  }

  snapshot() {
    return { disposed: this._disposed, desired: this._desired && { ...this._desired },
      requested: this._requested && { ...this._requested }, accepted: this._accepted && { ...this._accepted },
      requests: this._requests, inFlight: this._inFlight !== null, timerPending: this._timer !== null,
      dprWatcherPending: this._dprTimer !== null,
      debounceMs: this._delay, error: this._error };
  }

  dispose() {
    if (this._disposed) return;
    this._disposed = true;
    this._clearPending();
    if (this._dprTimer !== null) this._clearTimer(this._dprTimer);
    this._dprTimer = null;
    this._observer.disconnect();
    this._media.removeEventListener("change", this._onDpr);
    this._controller = null;
    this._inFlight = null;
  }
}

// E5-T15c: cursor presentation mode and DOM lifecycle.
//
// CursorSink owns resource conversion. This controller owns the page's one optional overlay,
// absolute/relative mode policy, and transform-only MOVE_CURSOR handling. The move path never
// calls a layout API or touches the PNG/data URL; it only updates the current position and, when
// needed, the overlay's transform.

import { CursorSink } from "./cursor.js";

export const CURSOR_MODES = Object.freeze({
  ABSOLUTE: "absolute",
  RELATIVE: "relative",
});

export const CURSOR_EVENTS = Object.freeze({
  UPDATE: "cursor-update",
  MOVE: "cursor-move",
});

const MAX_U32 = 0xffff_ffff;

function checkedU32(value, name) {
  const number = Number(value);
  if (!Number.isSafeInteger(number) || number < 0 || number > MAX_U32) {
    throw new RangeError(`${name} must be an unsigned 32-bit integer`);
  }
  return number;
}

function checkedScale(value, name) {
  const number = Number(value);
  if (!Number.isFinite(number) || number <= 0) {
    throw new RangeError(`${name} must be a positive finite number`);
  }
  return number;
}

/** Normalize the Rust/worker cursor state without retaining any borrowed guest object. */
export function normalizeCursorState(state) {
  if (state === null || typeof state !== "object") throw new TypeError("cursor state is missing");
  const pos = state.pos && typeof state.pos === "object"
    ? state.pos
    : state.position && typeof state.position === "object"
      ? state.position
      : state;
  return Object.freeze({
    resourceId: checkedU32(state.resourceId ?? state.resource_id, "cursor resource id"),
    hotX: checkedU32(state.hotX ?? state.hot_x, "cursor hot_x"),
    hotY: checkedU32(state.hotY ?? state.hot_y, "cursor hot_y"),
    scanout: checkedU32(pos.scanout ?? pos.scanoutId ?? pos.scanout_id, "cursor scanout"),
    x: checkedU32(pos.x, "cursor x"),
    y: checkedU32(pos.y, "cursor y"),
  });
}

function safeCallback(callback, value) {
  try { callback(value); } catch { /* diagnostics never break guest execution */ }
}

function eventType(event) {
  return event?.type ?? event?.event ?? event?.kind ?? CURSOR_EVENTS.UPDATE;
}

function stateForSink(state) {
  return {
    resourceId: state.resourceId,
    hotX: state.hotX,
    hotY: state.hotY,
    pos: {
      scanoutId: state.scanout,
      x: state.x,
      y: state.y,
    },
  };
}

/**
 * Own the current cursor asset and its optional DOM overlay.
 *
 * The target is the same surface used by the pointer bridge. The controller does not create an
 * element or write target styles until a cursor resource is actually published, so software-fbcon
 * boots with no cursorq traffic leave the browser's default cursor untouched.
 */
export class CursorController {
  constructor({
    target = null,
    documentTarget = globalThis.document,
    overlayParent = target,
    cssMaxDimension,
    positionScaleX = 1,
    positionScaleY = 1,
    onDiagnostic = () => {},
    onStateChange = () => {},
  } = {}) {
    if (target !== null && (typeof target !== "object" || !target.style)) {
      throw new TypeError("cursor target must expose a style object");
    }
    if (overlayParent !== null && (typeof overlayParent !== "object" || typeof overlayParent.appendChild !== "function")) {
      throw new TypeError("cursor overlay parent must support appendChild");
    }
    if (typeof onDiagnostic !== "function") throw new TypeError("cursor onDiagnostic must be a function");
    if (typeof onStateChange !== "function") throw new TypeError("cursor onStateChange must be a function");
    this.target = target;
    this.documentTarget = documentTarget;
    this.overlayParent = overlayParent;
    this._positionScaleX = checkedScale(positionScaleX, "cursor x scale");
    this._positionScaleY = checkedScale(positionScaleY, "cursor y scale");
    this._onDiagnostic = onDiagnostic;
    this._onStateChange = onStateChange;
    this._sink = new CursorSink({ cssMaxDimension });
    this._descriptor = null;
    this._state = null;
    this._mode = CURSOR_MODES.ABSOLUTE;
    this._pointerLocked = false;
    this._overlay = null;
    this._savedHostCursor = null;
    this._hostCursorOwned = false;
    this._hostCursorHidden = false;
    this._targetPositionOwned = false;
    this._savedTargetPosition = null;
    this._updates = 0;
    this._moves = 0;
    this._modeChanges = 0;
    this._transformWrites = 0;
    this._styleWrites = 0;
    this._diagnostics = 0;
    this._disposed = false;
  }

  _diagnostic(reason, error = undefined) {
    this._diagnostics += 1;
    safeCallback(this._onDiagnostic, {
      reason,
      mode: this._mode,
      resourceId: this._state?.resourceId ?? 0,
      error: error ? String(error?.message || error) : undefined,
    });
  }

  _notify(reason) {
    safeCallback(this._onStateChange, this.snapshot(reason));
  }

  _captureHostCursor() {
    if (this._hostCursorOwned || !this.target?.style) return;
    this._savedHostCursor = this.target.style.cursor ?? "";
    this._hostCursorOwned = true;
  }

  _setHostCursor(value, { hidden = false } = {}) {
    if (!this.target?.style) return;
    this._captureHostCursor();
    if (this.target.style.cursor !== value) {
      this.target.style.cursor = value;
      this._styleWrites += 1;
    }
    this._hostCursorHidden = hidden;
  }

  _restoreHostCursor() {
    if (!this._hostCursorOwned || !this.target?.style) return;
    if (this.target.style.cursor !== this._savedHostCursor) {
      this.target.style.cursor = this._savedHostCursor;
      this._styleWrites += 1;
    }
    this._hostCursorOwned = false;
    this._hostCursorHidden = false;
    this._savedHostCursor = null;
  }

  _captureTargetPosition() {
    if (this._targetPositionOwned || this.overlayParent !== this.target || !this.target?.style) return;
    this._savedTargetPosition = this.target.style.position ?? "";
    if (!this._savedTargetPosition) {
      this.target.style.position = "relative";
      this._styleWrites += 1;
      this._targetPositionOwned = true;
    }
  }

  _restoreTargetPosition() {
    if (!this._targetPositionOwned || !this.target?.style) return;
    if (this.target.style.position !== this._savedTargetPosition) {
      this.target.style.position = this._savedTargetPosition;
      this._styleWrites += 1;
    }
    this._targetPositionOwned = false;
    this._savedTargetPosition = null;
  }

  _ensureOverlay() {
    if (this._overlay) return this._overlay;
    if (!this.overlayParent || typeof this.documentTarget?.createElement !== "function") {
      throw new Error("cursor overlay DOM is unavailable");
    }
    const overlay = this.documentTarget.createElement("img");
    if (!overlay || !overlay.style) throw new TypeError("cursor overlay element is invalid");
    overlay.className = "wvm-cursor-overlay";
    overlay.alt = "";
    overlay.draggable = false;
    overlay.setAttribute?.("aria-hidden", "true");
    overlay.style.position = "absolute";
    overlay.style.left = "0px";
    overlay.style.top = "0px";
    overlay.style.pointerEvents = "none";
    overlay.style.userSelect = "none";
    overlay.style.willChange = "transform";
    overlay.style.transformOrigin = "0 0";
    overlay.style.zIndex = "2147483647";
    overlay.style.display = "block";
    this._captureTargetPosition();
    try {
      this.overlayParent.appendChild(overlay);
    } catch (error) {
      this._restoreTargetPosition();
      throw error;
    }
    this._overlay = overlay;
    return overlay;
  }

  _removeOverlay() {
    if (!this._overlay) {
      this._restoreTargetPosition();
      return;
    }
    const overlay = this._overlay;
    let removed = false;
    try {
      if (typeof this.overlayParent?.removeChild === "function") {
        this.overlayParent.removeChild(overlay);
        removed = true;
      }
    } catch (error) {
      this._diagnostic("overlay-remove-error", error);
    }
    if (!removed) {
      try {
        overlay.remove?.();
        removed = true;
      } catch (error) {
        this._diagnostic("overlay-remove-error", error);
      }
    }
    this._overlay = null;
    this._restoreTargetPosition();
  }

  /** Write only the transform for a cursor position; this method performs no layout reads. */
  _applyPositionOnly() {
    if (!this._overlay || !this._state || !this._descriptor) return;
    const x = this._state.x * this._positionScaleX - this._descriptor.hotX;
    const y = this._state.y * this._positionScaleY - this._descriptor.hotY;
    this._overlay.style.transform = `translate3d(${x}px, ${y}px, 0)`;
    this._transformWrites += 1;
