  _showOverlay() {
    const descriptor = this._descriptor;
    if (!descriptor || descriptor.kind === "hidden") return;
    const overlay = this._ensureOverlay();
    const source = descriptor.src ?? descriptor.dataUrl;
    overlay.src = source;
    overlay.style.width = `${descriptor.width}px`;
    overlay.style.height = `${descriptor.height}px`;
    overlay.style.display = "block";
    this._applyPositionOnly();
  }

  _applyAsset() {
    const descriptor = this._descriptor;
    if (!descriptor || descriptor.kind === "hidden" || this._state?.resourceId === 0) {
      this._removeOverlay();
      this._restoreHostCursor();
      return;
    }

    if (this._mode === CURSOR_MODES.ABSOLUTE && descriptor.kind === "css") {
      this._removeOverlay();
      this._setHostCursor(descriptor.css);
      return;
    }

    // Relative mode always uses the overlay. A large absolute-mode cursor also uses the overlay
    // because browsers reject CSS cursor images above the bounded CSS dimension.
    this._showOverlay();
    if (this._mode === CURSOR_MODES.RELATIVE) {
      if (this._pointerLocked) this._setHostCursor("none", { hidden: true });
      else this._restoreHostCursor();
    } else {
      this._setHostCursor("none", { hidden: true });
    }
  }

  _applySafely(reason) {
    try {
      this._applyAsset();
    } catch (error) {
      this._diagnostic(reason, error);
    }
  }

  /** Apply one cursor resource callback, copying all guest-backed bytes through CursorSink. */
  handleUpdate(event) {
    if (this._disposed) return false;
    let state;
    try {
      state = normalizeCursorState(event?.state ?? event?.cursorState ?? event);
      const descriptor = this._sink.update(
        stateForSink(state),
        event?.format,
        event?.resourceWidth,
        event?.resourceHeight,
        event?.pixels ?? [],
      );
      this._state = state;
      this._descriptor = descriptor;
      this._updates += 1;
      this._applySafely("cursor-update-dom-error");
      this._notify("cursor-update");
      return this.snapshot("cursor-update");
    } catch (error) {
      this._diagnostic("cursor-update-rejected", error);
      return false;
    }
  }

  /**
   * Apply MOVE_CURSOR without touching the copied resource or invoking any layout API.
   * A move before a matching update is rejected rather than accidentally displaying stale data.
   */
  handleMove(event) {
    if (this._disposed) return false;
    try {
      const state = normalizeCursorState(event?.state ?? event?.cursorState ?? event);
      if (state.resourceId === 0) {
        this._state = state;
        this._descriptor = null;
        this._removeOverlay();
        this._restoreHostCursor();
        this._moves += 1;
        this._notify("cursor-move-hidden");
        return this.snapshot("cursor-move-hidden");
      }
      if (!this._descriptor || this._descriptor.kind === "hidden" ||
          this._state?.resourceId !== state.resourceId) {
        throw new RangeError("cursor move has no matching copied resource");
      }
      if (state.hotX !== this._descriptor.hotX || state.hotY !== this._descriptor.hotY) {
        throw new RangeError("cursor move cannot change the active hotspot");
      }
      if (state.hotX >= this._descriptor.width || state.hotY >= this._descriptor.height) {
        throw new RangeError("cursor move hotspot is outside the active resource");
      }
      this._state = state;
      this._moves += 1;
      // This is the only DOM operation on the high-frequency move path.
      this._applyPositionOnly();
      return this.snapshot("cursor-move");
    } catch (error) {
      this._diagnostic("cursor-move-rejected", error);
      return false;
    }
  }

  /** Dispatch a typed callback from the direct wasm path or the whole-machine worker. */
  handle(event) {
    switch (eventType(event)) {
      case CURSOR_EVENTS.UPDATE: return this.handleUpdate(event);
      case CURSOR_EVENTS.MOVE: return this.handleMove(event);
      default:
        this._diagnostic("unknown-cursor-event");
        return false;
    }
  }

  /** Follow the pointer bridge's mode/Pointer Lock state without coupling to its event routing. */
  setPointerState(state = {}) {
    const mode = state.mode ?? CURSOR_MODES.ABSOLUTE;
    if (mode !== CURSOR_MODES.ABSOLUTE && mode !== CURSOR_MODES.RELATIVE) {
      throw new TypeError(`unknown cursor mode: ${String(mode)}`);
    }
    const locked = state.pointerLocked === true;
    const changed = mode !== this._mode || locked !== this._pointerLocked;
    this._mode = mode;
    this._pointerLocked = locked;
    if (changed) {
      this._modeChanges += 1;
      this._applySafely("cursor-mode-dom-error");
      this._notify("pointer-state");
    }
    return this.snapshot("pointer-state");
  }

  /** Set guest-to-surface scale without measuring during MOVE_CURSOR delivery. */
  setPositionScale(scaleX, scaleY = scaleX) {
    this._positionScaleX = checkedScale(scaleX, "cursor x scale");
    this._positionScaleY = checkedScale(scaleY, "cursor y scale");
    if (this._overlay) this._applyPositionOnly();
    this._notify("position-scale");
    return this.snapshot("position-scale");
  }

  /** Return a private snapshot of the current converted asset for diagnostics and integration tests. */
  descriptor() {
    return Object.freeze(this._descriptor ? { ...this._descriptor } : { kind: "hidden" });
  }

  /** Hide the resource and remove all DOM owned by this controller. */
  reset() {
    if (this._disposed) return this.snapshot("reset");
    try {
      this._sink.hide({ resourceId: 0, hotX: 0, hotY: 0, scanout: 0, x: 0, y: 0 });
    } catch (error) {
      this._diagnostic("cursor-reset-sink-error", error);
    }
    this._descriptor = null;
    this._state = null;
    this._mode = CURSOR_MODES.ABSOLUTE;
    this._pointerLocked = false;
    this._removeOverlay();
    this._restoreHostCursor();
    this._notify("reset");
    return this.snapshot("reset");
  }

  dispose() {
    if (!this._disposed) this.reset();
    this._disposed = true;
    return this.snapshot("dispose");
  }

  snapshot(reason = "state") {
    return Object.freeze({
      mode: this._mode,
      pointerLocked: this._pointerLocked,
      resourceId: this._state?.resourceId ?? 0,
      kind: this._descriptor?.kind ?? "hidden",
      width: this._descriptor?.width ?? 0,
      height: this._descriptor?.height ?? 0,
      hotX: this._descriptor?.hotX ?? 0,
      hotY: this._descriptor?.hotY ?? 0,
      overlayAttached: this._overlay !== null,
      hostCursorOwned: this._hostCursorOwned,
      hostCursorHidden: this._hostCursorHidden,
      updates: this._updates,
      moves: this._moves,
      modeChanges: this._modeChanges,
      transformWrites: this._transformWrites,
      styleWrites: this._styleWrites,
      diagnostics: this._diagnostics,
      reason,
    });
  }
}

// One boot-owned, lazy adapter over the unchanged desktop agent transport.
import { createDesktopAgentBridge } from "./desktop-agent-bridge.js";
import { DisconnectedError } from "./agent-channel.js";

export function createDesktopAgentSession({ request, isCurrent, onError = null,
  createBridge = createDesktopAgentBridge } = {}) {
  if (!request || typeof request.key !== "string" || !Number.isSafeInteger(request.generation)
      || request.generation < 1 || typeof isCurrent !== "function") {
    throw new TypeError("desktop agent session requires an owned boot request");
  }
  const automatic = request.key !== "omarchy";
  let controller = null;
  let bridge = null;
  let closed = false;
  const pending = []; // CLI-only, before the controller exists; never retained for lazy Omarchy.
  let resolveReady, rejectReady;
  const ready = new Promise((resolve, reject) => { resolveReady = resolve; rejectReady = reject; });
  ready.catch(() => {});

  function close(reason = "desktop agent session retired") {
    if (closed) return false;
    closed = true;
    pending.length = 0;
    rejectReady(new DisconnectedError(String(reason)));
    bridge?.close(reason);
    return true;
  }
  function current() {
    if (closed) return false;
    if (isCurrent()) return true;
    close("desktop agent session no longer owns this boot");
    return false;
  }
  function activate() {
    if (!current()) throw new DisconnectedError("desktop agent session is retired");
    if (!controller) throw new DisconnectedError("desktop agent controller is not attached");
    if (!bridge) {
      try {
        // Fence even reconnects and writes already scheduled by Channel. Never resolve the
        // controller dynamically through a global that can belong to a different generation.
        bridge = createBridge({
          sendAgentInput(bytes) {
            if (!current()) return Promise.reject(new DisconnectedError("desktop agent session is retired"));
            return controller.sendAgentInput(bytes);
          },
        }, { onError });
        bridge.channel.ready.then(resolveReady, rejectReady);
        bridge.start();
        for (const bytes of pending.splice(0)) bridge.receive(bytes);
      } catch (error) {
        close("desktop agent startup failed");
        throw error;
      }
    }
    return bridge.channel;
  }

  // Property/availability reads are passive, including .ready. Consumers explicitly start,
  // waitUntilReady, rehandshake, send/ping, or subscribe (ClipboardService.start does this).
  // The facade stays bound to this session even if a caller retains it after a later boot.
  const channel = {
    get state() { return current() ? bridge?.channel.state ?? "idle" : "closed"; },
    get ready() { return ready; },
    get negotiated() { return current() ? bridge?.channel.negotiated ?? null : null; },
    get negotiatedVersion() { return channel.negotiated?.version ?? null; },
    get negotiatedCapabilities() { return channel.negotiated?.capabilities ?? 0n; },
    get transportGeneration() { return current() ? bridge?.channel.transportGeneration ?? 0 : 0; },
    get pendingCount() { return current() ? bridge?.channel.pendingCount ?? 0 : 0; },
    get maxPending() { return bridge?.channel.maxPending ?? 1024; },
    get lastError() { return bridge?.channel.lastError ?? null; },
    get transportListenerCount() { return current() ? bridge?.channel.transportListenerCount ?? 0 : 0; },
    supports(capability) { return current() && (bridge?.channel.supports(capability) ?? BigInt(capability) === 0n); },
    listenerCount(type) { return current() ? bridge?.channel.listenerCount(type) ?? 0 : 0; },
    start() { activate(); return channel; },
    async waitUntilReady() { return activate().waitUntilReady(); },
    async rehandshake() { return activate().rehandshake(); },
    async send(...args) { return activate().send(...args); },
    async ping(...args) { return activate().ping(...args); },
    subscribe(type, listener) { return activate().subscribe(type, listener); },
    subscribeState(listener) { return activate().subscribeState(listener); },
    close,
    destroy: close,
  };
  return {
    channel,
    isCurrent: current,
    attach(nextController) {
      if (!current()) return false;
      if (!nextController || typeof nextController.sendAgentInput !== "function") {
        throw new TypeError("desktop agent session requires sendAgentInput");
      }
      if (controller && controller !== nextController) throw new Error("desktop agent session cannot change controller");
      controller = nextController;
      if (automatic) activate();
      return true;
    },
    receive(value) {
      if (!current()) return 0;
      if (bridge) return bridge.receive(value);
      if (!automatic) return 0; // No copy, bridge construction, timers, or hidden pending queue.
      const bytes = value instanceof Uint8Array ? value.slice() : Uint8Array.from(value || []);
      if (!bytes.byteLength) return 0;
      pending.push(bytes);
      if (pending.length > 128) pending.shift();
      return bytes.byteLength;
    },
    close,
  };
}

// E5-T26e — browser composition of the T23d agent Channel, core desktop restore, and T22.
//
// The core owns the atomic guest transaction. This small page-side boundary owns the two host
// prerequisites that cannot live in no-std Rust: a fresh Channel HELLO and the actual
// PresentationController that paints the restored viewport.

function checkedViewport(value) {
  if (!value || !Number.isInteger(value.width) || !Number.isInteger(value.height)
      || value.width < 1 || value.height < 1) {
    throw new RangeError("desktop restore host viewport must contain positive integer dimensions");
  }
  return { width: value.width, height: value.height };
}
function ownedBytes(value) {
  if (value instanceof Uint8Array) return value.slice();
  if (ArrayBuffer.isView(value)) return new Uint8Array(value.buffer, value.byteOffset, value.byteLength).slice();
  if (value instanceof ArrayBuffer) return new Uint8Array(value.slice(0));
  throw new TypeError("desktop restore snapshot must be bytes");
}

/**
 * Restore one desktop envelope through the live host boundaries.
 *
 * `agentChannel.rehandshake()` is the T23d proof point: it resolves only after the new transport's
 * peer HELLO has been decoded and intersected. `controller.confirmAgentHello()` transfers that
 * application-level fact to the core. T22's real PresentationController is cleared and resized
 * before the core commit, so a refusal cannot leave the previous frame visible.
 */
export async function restoreDesktopThroughHost({
  controller,
  agentChannel,
  presentation,
  viewportController = null,
  beforeRestore = null,
}, snapshot, hostViewport) {
  if (!controller || typeof controller.confirmAgentHello !== "function"
      || typeof controller.restoreDesktopSnapshot !== "function") {
    throw new Error("desktop restore controller is unavailable");
  }
  if (!agentChannel || typeof agentChannel.rehandshake !== "function") {
    throw new Error("desktop restore requires the live T23d agent Channel");
  }
  if (!presentation || typeof presentation.setViewport !== "function"
      || typeof presentation.clear !== "function") {
    throw new Error("desktop restore requires the live T22 presentation owner");
  }
  const viewport = checkedViewport(hostViewport);
  const bytes = ownedBytes(snapshot);
  try {
    // Clear before any host resize so a rejected transaction cannot retain a pre-restore frame.
    presentation.clear();
    const appliedViewport = presentation.setViewport(viewport.width, viewport.height);
    const handshake = await agentChannel.rehandshake();
    if (!handshake || agentChannel.state !== "ready") {
      throw new Error("agent Channel did not reach READY after fresh HELLO");
    }
    if (!await controller.confirmAgentHello()) {
      throw new Error("virtio-console rejected the fresh application HELLO");
    }
    // The guest must be running while the fresh HELLO is transported and handled. The page
    // owner can then pause at this exact boundary so the composite restore call is atomic with
    // respect to the executor, without deadlocking the handshake behind a paused guest.
    await beforeRestore?.();
    const report = await controller.restoreDesktopSnapshot(bytes, viewport.width, viewport.height);
    if (!report?.hostViewport
        || report.hostViewport.width !== viewport.width
        || report.hostViewport.height !== viewport.height) {
      throw new Error("desktop restore returned a different host viewport");
    }
    viewportController?.applyCanvasStyle?.();
    return Object.freeze({ report, handshake, appliedViewport });
  } catch (error) {
    // The core performs the device/agent fallback. This covers host-side failures before the core
    // call and keeps the visible T22 surface honest for the next cold boot.
    try { presentation.clear(); } catch { /* preserve the original restore error */ }
    throw error;
  }
}

// Local experiment only: arm after restore, before the first execution slice.
// Never enables JIT, changes any other admission policy, or exposes a controller mutation RPC.

const LOOPBACK_HOSTS = new Set(["localhost", "127.0.0.1", "[::1]", "::1"]);

/** Return whether a browser location is an HTTP(S) loopback origin. */
export function isLoopbackOrigin(locationLike = globalThis.location) {
  const origin = typeof locationLike === "string"
    ? locationLike
    : locationLike?.origin ?? locationLike?.href;
  if (typeof origin !== "string") return false;
  let url;
  try {
    url = new URL(origin);
  } catch {
    return false;
  }
  return (url.protocol === "http:" || url.protocol === "https:") &&
    LOOPBACK_HOSTS.has(url.hostname.toLowerCase());
}

/** Arm the actual WASM machine and verify the actual report. */
export function applyColdCounterRecycling(machine, requested = false) {
  if (typeof requested !== "boolean") {
    throw new TypeError("jitColdCounterRecycling must be boolean");
  }
  if (!requested) return;
  for (const method of ["setColdCounterRecycling", "jitStats"]) {
    if (typeof machine?.[method] !== "function") {
      throw new Error(`jitColdCounterRecycling requires WASM ${method}`);
    }
  }
  if (machine.jitStats()?.hasExecutor !== true) {
    throw new Error("jitColdCounterRecycling requires an actual JIT executor");
  }
  machine.setColdCounterRecycling(true);
  const report = machine.jitStats()?.coldCounterRecycling;
  if (report?.enabled !== true) {
    throw new Error("jitColdCounterRecycling did not reach the actual machine");
  }
  return report;
}

// Shell login and a framebuffer allocation both precede the desktop. Require the package shell's
// mapped bar and background plus actual non-uniform pixels before uncovering the canvas.
function mappedLayerNamespaces(layers) {
  const found = new Set();
  const visit = (value) => {
    if (!value || typeof value !== "object") return;
    if (Number.isFinite(value.w) && value.w > 0 && Number.isFinite(value.h) && value.h > 0
      && Number.isInteger(value.pid) && value.pid > 0) found.add(value.namespace);
    for (const child of Object.values(value)) if (child && typeof child === "object") visit(child);
  };
  visit(layers);
  return found;
}

export function hasOmarchyDesktopLayers(layers) {
  const found = mappedLayerNamespaces(layers);
  return found.has("omarchy-bar") && found.has("omarchy-background");
}

// The browser demo's readiness gate. The responsive demo profile
// (tools/image/omarchy-responsive-profile.sh) disables the shell's background layer: it re-committed
// every frame and forced a full-screen software recomposite, while its undecodable .webp wallpaper
// never drew anything. The mapped package bar is therefore the shell evidence for both profiles.
export function hasOmarchyShellBar(layers) {
  return mappedLayerNamespaces(layers).has("omarchy-bar");
}

export function hasDesktopPixels(rgba) {
  if (!rgba || rgba.length < 4096 || rgba.length % 4 !== 0) return false;
  const colors = new Set();
  let visible = 0, samples = 0;
  const stride = Math.max(1, Math.floor(rgba.length / 4 / 8192)) * 4;
  for (let i = 0; i < rgba.length; i += stride) {
    samples++;
    if (rgba[i + 3] > 0 && Math.max(rgba[i], rgba[i + 1], rgba[i + 2]) > 12) {
      visible++;
      colors.add((rgba[i] << 16) | (rgba[i + 1] << 8) | rgba[i + 2]);
    }
  }
  return visible > samples / 4 && colors.size >= 8;
}

export function throwJitMemFault() {
    throw null;
}

export function invokeJitBlock(run, stateBase, directChain) {
    try {
        // Direct-chain functions carry a third virtual-entry-PC argument. The host root uses the
        // handoff-backed path (root=1), so pass an explicit zero for the ignored fast-call value.
        return directChain ? run(stateBase, 1, 0n) : run(stateBase);
    } catch {
        return NaN;
    }
}

