    }

    if (cachedResponse) {
      // This announces the source before any body bytes are consumed. A failed
      // verification below transitions to the network source.
      emitCacheStatus(onCacheStatus, { role: descriptor.role, source: "cache" });
      try {
        return await verifyResponse(cachedResponse, descriptor, onProgress);
      } catch (error) {
        cacheWasCorrupt = true;
        // Delete exactly this content-addressed key.  A bad entry must never cause a
        // broad cache clear that could evict unrelated boot assets.
        try {
          await cache.delete(cacheKey);
        } catch (deleteError) {
          emitCacheStatus(onCacheStatus, { role: descriptor.role, source: "unavailable", reason: "cache-delete-failed" });
        }
      }
    }
  }

  // Source status describes where the bytes will be read from, not whether the
  // eventual response passes verification.
  emitCacheStatus(onCacheStatus, { role: descriptor.role, source: "network" });
  const response = await fetchImpl(
    descriptor.resolvedUrl,
    { cache: cacheWasCorrupt ? "reload" : "default" },
  );
  if (!response || response.status !== 200 || response.type === "opaque") {
    throw new Error(`boot asset request was not an HTTP 200 response: ${descriptor.resolvedUrl}`);
  }

  // This verifies before any storage write, so corrupt network responses can never
  // poison the content-addressed entry.
  const bytes = await verifyResponse(response, descriptor, onProgress);

  if (cache) {
    try {
      // Put a fresh Response containing the already verified bytes.  Awaiting this
      // operation makes a successful return deterministic across a reload.
      await cache.put(cacheKey, new Response(bytes));
    } catch (error) {
      emitCacheStatus(onCacheStatus, { role: descriptor.role, source: "unavailable", reason: "cache-store-failed" });
    }
  }

  return bytes;
}

async function verifyResponse(response, descriptor, emitProgress) {
  if (!response || response.status !== 200 || response.type === "opaque") {
    throw new Error("cached boot asset response is not a usable HTTP 200 response");
  }

  const bytes = await readBounded(response, descriptor.size, emitProgressFor(emitProgress));
  const subtle = globalThis.crypto?.subtle;
  if (!subtle || typeof subtle.digest !== "function") {
    throw new Error("WebCrypto SHA-256 is unavailable");
  }
  const digest = await subtle.digest("SHA-256", bytes);
  const actualSha256 = toHex(new Uint8Array(digest));
  if (actualSha256 !== descriptor.sha256) {
    throw new Error(`boot asset SHA-256 mismatch: expected ${descriptor.sha256}, got ${actualSha256}`);
  }
  return bytes;
}

async function readBounded(response, expectedSize, emitProgress) {
  emitProgress(0, expectedSize);

  if (!response.body || typeof response.body.getReader !== "function") {
    throw new Error("boot asset response has no readable body");
  }

  const bytes = new Uint8Array(expectedSize);
  const reader = response.body.getReader();
  let loaded = 0;
  try {
    for (;;) {
      const { done, value } = await reader.read();
      if (done) break;
      const chunk = asUint8Array(value);
      if (loaded + chunk.byteLength > expectedSize) {
        throw new Error(`boot asset exceeds declared size ${expectedSize}`);
      }
      bytes.set(chunk, loaded);
      loaded += chunk.byteLength;
      emitProgress(loaded, expectedSize);
    }
  } catch (error) {
    // Attach a rejection handler without waiting for cancellation: a stream
    // implementation may keep cancel() pending after an overflow/read failure.
    try { void Promise.resolve(reader.cancel()).catch(() => {}); } catch (cancelError) { /* best effort */ }
    throw error;
  } finally {
    reader.releaseLock();
  }
  if (loaded !== expectedSize) {
    throw new Error(`boot asset is truncated: expected ${expectedSize} bytes, got ${loaded}`);
  }
  return bytes;
}

function normalizeDescriptor(descriptor, baseUrlOption) {
  if (!descriptor || typeof descriptor !== "object") {
    throw new TypeError("boot asset descriptor must be an object");
  }
  if (typeof descriptor.sha256 !== "string" || !/^[0-9a-f]{64}$/.test(descriptor.sha256)) {
    throw new TypeError("boot asset sha256 must be exactly 64 lowercase hexadecimal characters");
  }
  if (!Number.isSafeInteger(descriptor.size) || descriptor.size <= 0 || descriptor.size > MAX_ASSET_SIZE) {
    throw new RangeError(`boot asset size must be a positive safe integer <= ${MAX_ASSET_SIZE}`);
  }
  if (typeof descriptor.role !== "string" || descriptor.role.length === 0) {
    throw new TypeError("boot asset role must be a non-empty string");
  }
  if (typeof descriptor.url !== "string" || descriptor.url.length === 0) {
    throw new TypeError("boot asset url must be a non-empty string");
  }

  const baseUrl = baseUrlOption === undefined ? globalThis.location?.href : baseUrlOption;
  let resolved;
  try {
    resolved = new URL(descriptor.url, baseUrl);
  } catch (error) {
    throw new TypeError("boot asset url must be an absolute http(s) URL or resolve against baseUrl");
  }
  if (resolved.protocol !== "http:" && resolved.protocol !== "https:") {
    throw new TypeError("boot asset url must use http or https");
  }

  return {
    url: descriptor.url,
    resolvedUrl: resolved.href,
    sha256: descriptor.sha256,
    size: descriptor.size,
    role: descriptor.role,
  };
}

function makeCacheKey(sha256, resolvedUrl, baseUrlOption) {
  let origin = FALLBACK_CACHE_ORIGIN;
  try {
    const base = baseUrlOption === undefined ? globalThis.location?.href : baseUrlOption;
    const candidate = new URL(base ?? resolvedUrl);
    if (candidate.protocol === "http:" || candidate.protocol === "https:") origin = candidate.origin;
  } catch (error) {
    // The descriptor URL was already resolved and validated; the fallback merely
    // keeps the synthetic key same-origin when no browser location exists.
  }
  return `${origin}/__wasm-vm-boot-assets-v1/${sha256}`;
}

function emitProgressFor(onProgress) {
  return (loaded, total) => {
    try { onProgress?.(loaded, total); } catch (error) { /* callbacks cannot corrupt boot */ }
  };
}

function emitCacheStatus(onCacheStatus, status) {
  try { onCacheStatus?.(status); } catch (error) { /* callbacks cannot corrupt boot */ }
}

function asUint8Array(value) {
  if (value instanceof Uint8Array) return value;
  if (value instanceof ArrayBuffer) return new Uint8Array(value);
  if (ArrayBuffer.isView(value)) return new Uint8Array(value.buffer, value.byteOffset, value.byteLength);
  throw new TypeError("boot asset stream yielded a non-byte chunk");
}

function toHex(bytes) {
  return Array.from(bytes, (byte) => byte.toString(16).padStart(2, "0")).join("");
}

// E3-T24a: a typed, honest, monotonic boot-progress model.
//
// The one rule this module exists to enforce: the displayed bar only ever moves in response to a
// REAL event — bytes actually fetched, or a stage actually reaching a milestone — never a timer and
// never an inferred "creep toward 99%". Measurable phases (kernel, chunk) are byte-weighted; the
// unmeasurable phases (wasm instantiate, manifest fetch, and the kernel's own boot-to-login) are
// EXPLICITLY indeterminate — the bar holds at its last determinate value and the surface says
// "working", rather than faking a percentage. 100% is reached only when the guest is actually usable
// (the `ready` event, i.e. the login prompt), so completion cannot precede the prompt.
//
// It is a pure reducer: `applyEvent` takes the current immutable state + one typed event and returns
// the next state. No DOM, no clock, no globals — so it is exhaustively testable headlessly (reorder,
// duplicate, omit, delay, and fail every event) and reused verbatim by the browser surface.

/** The ordered boot stages. `measurable` phases advance by observed bytes; the rest are indeterminate
 * (shown as an explicit "working" state, never a fabricated percentage). `weight` is the stage's
 * share of the overall 0..1 bar; the weights sum to 1. */
export const STAGES = [
  { id: "wasm", label: "Loading engine", measurable: false, weight: 0.05 },
  { id: "manifest", label: "Reading manifest", measurable: false, weight: 0.05 },
  { id: "kernel", label: "Fetching kernel", measurable: true, weight: 0.15 },
  { id: "chunk", label: "Fetching disk image", measurable: true, weight: 0.55 },
  { id: "login", label: "Booting to login", measurable: false, weight: 0.20 },
];

const STAGE_INDEX = new Map(STAGES.map((s, i) => [s.id, i]));

/** The typed event contract. Every producer emits exactly these shapes:
 *  - { kind: "enter", stage }                 a stage became active (indeterminate phases show "working")
 *  - { kind: "bytes", stage, loaded, total }  observed bytes for a measurable stage (total null ⇒ indeterminate)
 *  - { kind: "complete", stage }              a stage finished (its full weight lands)
 *  - { kind: "ready" }                        the guest is usable (login prompt) ⇒ overall reaches 100%
 *  - { kind: "error", stage, message }        a stage failed ⇒ a stage-named error, never an endless spinner
 * Unknown kinds / unknown stage ids are ignored (a producer from a newer build cannot corrupt the bar). */
export function isValidEvent(evt) {
  if (!evt || typeof evt.kind !== "string") return false;
  if (evt.kind === "ready") return true;
  if (typeof evt.stage !== "string" || !STAGE_INDEX.has(evt.stage)) return false;
  if (evt.kind === "bytes") {
    return (
      Number.isFinite(evt.loaded) &&
      evt.loaded >= 0 &&
      (evt.total == null || (Number.isFinite(evt.total) && evt.total >= 0))
    );
  }
  return evt.kind === "enter" || evt.kind === "complete" || evt.kind === "error";
}

/** The initial state. `overall` is the monotonic 0..1 bar; `indeterminate` is true while the active
 * stage cannot report bytes (the surface must show "working", not a number that appears stalled). */
export function initialProgress() {
  const stages = {};
  for (const s of STAGES) {
    stages[s.id] = { state: "pending", loaded: 0, total: null, fraction: 0 };
  }
  return {
    overall: 0,
    activeStage: null,
    label: "Starting",
    indeterminate: true,
    ready: false,
    error: null,
    stages,
  };
}

// The overall bar = sum over stages of weight × fraction, where a measurable stage's fraction is
// bytes-based and an indeterminate stage contributes only 0 (active/pending) or 1 (complete). This is
// what keeps it honest: an active indeterminate phase adds NOTHING to the number — the bar simply
// holds — so there is no fabricated intra-phase creep.
function computeOverall(stages, ready) {
  if (ready) return 1;
  let sum = 0;
  for (const s of STAGES) {
    sum += s.weight * stages[s.id].fraction;
  }
  // Clamp strictly below 1 until `ready`: fetching everything must not read as "done" while the
  // guest is still booting to a prompt. (Weights already leave the login stage's share unfilled, but
  // this makes the invariant explicit and mutation-testable.)
  return Math.min(sum, 0.99);
}

/** Apply one typed event, returning the next state. Pure and monotonic: `overall` never decreases and
 * a completed stage never reopens, so out-of-order / duplicated / delayed events cannot rewind the bar. */
export function applyProgress(prev, evt) {
  if (!isValidEvent(evt)) return prev;
  const stages = { ...prev.stages };
  const clone = (id) => (stages[id] = { ...stages[id] });
  let ready = prev.ready;
  let error = prev.error;
  let activeStage = prev.activeStage;

  switch (evt.kind) {
    case "ready": {
      ready = true;
      // Every stage is implicitly complete once the guest is usable.
      for (const s of STAGES) {
        clone(s.id);
        if (stages[s.id].state !== "error") {
          stages[s.id].state = "complete";
          stages[s.id].fraction = 1;
        }
      }
      activeStage = "login";
      break;
    }
    case "enter": {
      clone(evt.stage);
      // A stage never leaves a terminal state (complete/error) on a late/duplicate "enter".
      if (stages[evt.stage].state === "pending") stages[evt.stage].state = "active";
      // Entering a later stage implies the earlier measurable ones delivered their bytes; fill any
      // still-open earlier stage so a dropped "complete" can't strand the bar behind reality.
      const here = STAGE_INDEX.get(evt.stage);
      for (const s of STAGES) {
        if (STAGE_INDEX.get(s.id) < here && stages[s.id].state !== "error") {
          clone(s.id);
          stages[s.id].state = "complete";
          stages[s.id].fraction = 1;
        }
      }
      if (activeStage == null || STAGE_INDEX.get(evt.stage) >= STAGE_INDEX.get(activeStage)) {
        activeStage = evt.stage;
      }
      break;
    }
    case "bytes": {
      clone(evt.stage);
      const st = stages[evt.stage];
      if (st.state !== "complete" && st.state !== "error") st.state = "active";
      st.loaded = Math.max(st.loaded, evt.loaded); // observed bytes only grow within a stage
      if (evt.total != null) st.total = evt.total;
      // Fraction is monotonic per stage: a smaller/duplicate reading can't shrink it.
      const frac = st.total ? Math.min(1, st.loaded / st.total) : st.fraction;
      st.fraction = Math.max(st.fraction, frac);
      if (activeStage == null || STAGE_INDEX.get(evt.stage) >= STAGE_INDEX.get(activeStage)) {
        activeStage = evt.stage;
      }
      break;
    }
    case "complete": {
      clone(evt.stage);
      if (stages[evt.stage].state !== "error") {
        stages[evt.stage].state = "complete";
        stages[evt.stage].fraction = 1;
      }
      break;
    }
    case "error": {
      clone(evt.stage);
      stages[evt.stage].state = "error";
      error = { stage: evt.stage, label: stageLabel(evt.stage), message: String(evt.message ?? "failed") };
      activeStage = evt.stage;
      break;
    }
    default:
      return prev;
  }

  const overall = error ? prev.overall : Math.max(prev.overall, computeOverall(stages, ready));
  const active = activeStage ? STAGES[STAGE_INDEX.get(activeStage)] : null;
  const indeterminate = Boolean(
    !ready && !error && active && (!active.measurable || stages[activeStage].total == null),
  );
  const label = error
    ? `${error.label} failed: ${error.message}`
    : ready
      ? "Ready"
      : active
        ? active.label
        : "Starting";

  return { overall, activeStage, label, indeterminate, ready, error, stages };
}

/** Fold a whole event sequence (test/replay helper). */
export function reduceProgress(events, start = initialProgress()) {
  return events.reduce(applyProgress, start);
}

export function stageLabel(id) {
  const i = STAGE_INDEX.get(id);
  return i == null ? id : STAGES[i].label;
}

/** Integer percent for display/assertions. */
export function percent(state) {
  return Math.round(state.overall * 100);
}

// A tiny, environment-neutral single-flight task barrier used by the Linux scheduler.
// `stop()` first closes admission, then joins the currently active task. Callers may therefore
// release storage only after it resolves: a fetch/persist await cannot still be using that storage.
export function createTaskQuiescence(onIdle = () => {}) {
  let active = null;
  let stopping = false;

  const run = (task) => {
    if (stopping) return Promise.resolve(false);
    if (active) return active;
    let current;
    current = Promise.resolve()
      .then(task)
      .finally(() => {
        if (active === current) active = null;
        onIdle();
      });
    active = current;
    return current;
  };

  const stop = async () => {
    stopping = true;
    const current = active;
    if (current) await current;
    onIdle();
  };

  return {
    run,
    stop,
    waitForIdle: async () => { const current=active; if(current) await current; },
    isActive: () => active != null,
    isStopping: () => stopping,
  };
}

// E5-T26k: one explicit capacity experiment; omission preserves the machine's default/state.
export function validateDecodedCacheEntries(value) {
  if (value === undefined) return undefined;
  if (value === 4096 || value === 16384) return value;
  if (value === "4096" || value === "16384") return Number(value);
  throw new RangeError("decodedCacheEntries must be 4096 or 16384 (number or exact decimal string)");
}

// Called after initial snapshot restoration, before any guest pump. Do not put this
// fail-closed configuration inside the optional JIT-enable fallback catch.
export function applyDecodedCacheEntries(machine, value) {
  const entries = validateDecodedCacheEntries(value);
  if (entries === undefined) return;
  for (const method of ["setDecodedCacheEntries", "jitStats"]) {
    if (typeof machine?.[method] !== "function") {
      throw new Error(`decodedCacheEntries requires WASM ${method}`);
    }
  }
  const actual = machine.jitStats()?.decodedCacheEntries;
  if (actual !== 4096 && actual !== 16384) {
    throw new Error("decodedCacheEntries requires actual supported cache capacity");
  }
  if (actual === entries) return; // No resize/invalidation for an explicit same-size selection.
  machine.setDecodedCacheEntries(entries);
  if (machine.jitStats()?.decodedCacheEntries !== entries) {
    throw new Error("decodedCacheEntries selection did not reach the actual machine");
  }
}

// E3-T22a: OSC 52 clipboard-copy handler for the in-page terminal. Pure, dependency-free logic so
// it is node-unit-testable apart from the browser Clipboard API; `createOsc52Handler` adapts it to
// xterm.js's `registerOscHandler(52, …)`.
//
// A guest emits `ESC ] 52 ; <selection> ; <payload> (BEL|ST)`. xterm strips the `ESC]52;` framing and
// hands the callback the DATA string — i.e. `<selection>;<payload>` (e.g. `c;aGk=` or `c;?`). We:
//   - COPY when payload is base64 → decode and write the host clipboard,
//   - QUERY when payload is `?` → answer ONLY when clipboard-read is explicitly enabled (default off:
//     a guest read of the host clipboard is an exfiltration channel),
//   - classify anything malformed/oversize as INVALID and drop it (handled, never a throw/hang).

// Hostile-guest cap on the base64 payload length, enforced BEFORE any decode so a multi-megabyte
// sequence can never force a giant allocation. 100 KB of base64 ≈ 75 KB of clipboard text.
export const DEFAULT_MAX_ENCODED_BYTES = 100 * 1024;

const BASE64_RE = /^[A-Za-z0-9+/]*={0,2}$/;

/**
 * Classify an OSC 52 data string (everything after `ESC]52;`).
 * Returns one of:
 *   { kind: "copy",  selection, text }   — a valid, in-cap base64 payload, decoded to `text`
 *   { kind: "query", selection }         — the `?` read-request form
 *   { kind: "invalid", reason }          — malformed selection/base64, or over the cap
 * Never throws.
 */
export function parseOsc52(data, { maxEncodedBytes = DEFAULT_MAX_ENCODED_BYTES } = {}) {
  if (typeof data !== "string") return { kind: "invalid", reason: "non-string" };
  // Split into the selection field and the payload (the payload itself may be empty = clear).
  const semi = data.indexOf(";");
  if (semi < 0) return { kind: "invalid", reason: "no-selection-separator" };
  const selection = data.slice(0, semi);
  const payload = data.slice(semi + 1);
  // Selection is a set of clipboard names (c, p, s, 0-7, q, …). An empty field means the default
  // ("c" + "s") per the spec; anything with a separator or control char is malformed.
  if (/[;\s]/.test(selection)) return { kind: "invalid", reason: "bad-selection" };

  if (payload === "?") return { kind: "query", selection };

  // Enforce the cap on the ENCODED length first — before validating or decoding.
  if (payload.length > maxEncodedBytes) return { kind: "invalid", reason: "too-large" };
  if (!BASE64_RE.test(payload)) return { kind: "invalid", reason: "bad-base64" };
  const text = decodeBase64Utf8(payload);
  if (text === null) return { kind: "invalid", reason: "undecodable" };
  return { kind: "copy", selection, text };
}

/**
 * Build the `registerOscHandler(52, …)` callback. `writeClipboard(text) -> Promise` performs the host
 * write (e.g. `navigator.clipboard.writeText`); on rejection `onCopyBlocked(text)` surfaces the
 * "copied — click to confirm" affordance so a permission failure NEVER drops silently. The read-query
 * form is answered only when `allowRead` is true (default off).
 *
 * The returned handler is synchronous and always returns `true` (the sequence is "handled" — even an
 * invalid payload is consumed rather than echoed as raw bytes); async clipboard work runs in the
 * background so a slow/denied write can never block the terminal's OSC parser.
 *
 * `allowRead` may be a boolean OR a thunk `() => boolean`, evaluated PER INVOCATION so a live toggle
 * is honored (the guest read-query gate must reflect the current setting, not the construction-time one).
 */
export function createOsc52Handler({
  writeClipboard,
  readClipboard = null,
  allowRead = false,
  maxEncodedBytes = DEFAULT_MAX_ENCODED_BYTES,
  onCopyBlocked = null,
  onCopied = null,
  respond = null, // (payloadString) => void — how a query answer is written back to the guest
} = {}) {
  if (typeof writeClipboard !== "function") {
    throw new TypeError("createOsc52Handler requires writeClipboard(text) -> Promise");
  }
  const readAllowed = () => (typeof allowRead === "function" ? !!allowRead() : !!allowRead);
  return function handleOsc52(data) {
    const parsed = parseOsc52(data, { maxEncodedBytes });
    switch (parsed.kind) {
      case "copy": {
        Promise.resolve()
          .then(() => writeClipboard(parsed.text))
          .then(
            () => {
              if (onCopied) onCopied(parsed.text);
            },
            () => {
              // Denied / no transient activation / insecure context → hand off to the affordance.
              if (onCopyBlocked) onCopyBlocked(parsed.text);
            },
          );
        return true;
      }
      case "query": {
        // Default-off: a guest read of the host clipboard is refused silently (no answer written).
        if (!readAllowed() || typeof readClipboard !== "function" || typeof respond !== "function") {
          return true;
        }
        Promise.resolve()
          .then(() => readClipboard())
          .then(
            (text) => respond(`${parsed.selection};${encodeBase64Utf8(String(text ?? ""))}`),
            () => {
              /* read denied → answer nothing */
            },
          );
        return true;
      }
      default:
        // Invalid: consume the sequence (return true) so a hostile payload isn't re-emitted as text.
        return true;
    }
  };
}

// --- base64 <-> UTF-8, environment-agnostic (browser atob/btoa or Node Buffer) ---

function decodeBase64Utf8(b64) {
  try {
    if (typeof atob === "function") {
      const bin = atob(b64);
      const bytes = new Uint8Array(bin.length);
      for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
      return new TextDecoder("utf-8", { fatal: false }).decode(bytes);
    }
    // Node fallback (unit tests).
    return globalThis.Buffer.from(b64, "base64").toString("utf-8");
  } catch {
    return null;
  }
}

function encodeBase64Utf8(text) {
  const bytes = new TextEncoder().encode(text);
  if (typeof btoa === "function") {
    let bin = "";
    for (let i = 0; i < bytes.length; i++) bin += String.fromCharCode(bytes[i]);
    return btoa(bin);
  }
  return globalThis.Buffer.from(bytes).toString("base64");
}

// E5-T20b: the allocation-free AudioWorklet consumer for the T20a stereo PCM ring.

import { AudioRingBuffer, CHANNELS } from "./ring.js";

export const AUDIO_WORKLET_PROCESSOR_NAME = "wasm-vm-audio-consumer";
export const AUDIO_QUANTUM_FRAMES = 128;

// Node imports this module for the deterministic test hook, where AudioWorkletProcessor is not
// defined. The browser path extends the real host base and registers the stable processor name.
const WorkletProcessorBase = typeof AudioWorkletProcessor === "function"
  ? AudioWorkletProcessor
  : class AudioWorkletProcessorFallback {};

export class AudioRingWorkletProcessor extends WorkletProcessorBase {
  constructor(options = {}) {
    super();
    const sharedBuffer = options?.processorOptions?.sharedBuffer;
    if (typeof SharedArrayBuffer === "undefined" || !(sharedBuffer instanceof SharedArrayBuffer)) {
      throw new TypeError("audio worklet requires processorOptions.sharedBuffer");
    }
    const ring = AudioRingBuffer.fromSharedBuffer(sharedBuffer);
    this._ring = ring;
    this._consumer = ring.consumer();
    const clockBuffer = options?.processorOptions?.clockBuffer;
    if (clockBuffer !== undefined && clockBuffer !== null) {
      if (typeof SharedArrayBuffer === "undefined"
        || !(clockBuffer instanceof SharedArrayBuffer)
        || clockBuffer.byteLength < Int32Array.BYTES_PER_ELEMENT) {
        throw new TypeError("audio worklet clock requires a one-word SharedArrayBuffer");
      }
      this._clock = new Int32Array(clockBuffer, 0, 1);
    } else {
      this._clock = null;
    }
    this._capture = options?.processorOptions?.capture === true
      && typeof this.port?.postMessage === "function";
    const captureReadyBuffer = options?.processorOptions?.captureReadyBuffer;
    if (this._capture) {
      if (typeof SharedArrayBuffer === "undefined"
        || !(captureReadyBuffer instanceof SharedArrayBuffer)
        || captureReadyBuffer.byteLength < Int32Array.BYTES_PER_ELEMENT) {
        throw new TypeError("captured audio worklet requires a one-word ready buffer");
      }
      this._captureReady = new Int32Array(captureReadyBuffer, 0, 1);
    } else {
      this._captureReady = null;
    }
    this._captureScratch = this._capture
      ? new Float32Array(AUDIO_QUANTUM_FRAMES * CHANNELS)
      : null;
    // The rendering thread reuses this one interleaved scratch block on every process call.
    this._scratch = new Float32Array(AUDIO_QUANTUM_FRAMES * CHANNELS);
  }

  process(_inputs, outputs) {
    const output = outputs[0];
    const left = output?.[0];
    const right = output?.[1];
    if (!left || !right) return true;

    const frameCount = Math.min(AUDIO_QUANTUM_FRAMES, left.length, right.length);
    if (this._captureReady && Atomics.load(this._captureReady, 0) === 0) {
      left.fill(0, 0, frameCount);
      right.fill(0, 0, frameCount);
      return true;
    }
    const read = this._consumer.readInto(this._scratch, frameCount);
    for (let frame = 0; frame < frameCount; frame += 1) {
      const sampleIndex = frame * CHANNELS;
      const sample = frame < read ? this._scratch[sampleIndex] : 0;
      const otherSample = frame < read ? this._scratch[sampleIndex + 1] : 0;
      left[frame] = sample;
      right[frame] = otherSample;
    }
    if (read < frameCount) this._ring.recordUnderrun();
    if (this._clock) Atomics.add(this._clock, 0, frameCount);
    if (this._capture) {
      for (let frame = 0; frame < frameCount; frame += 1) {
        const sampleIndex = frame * CHANNELS;
        this._captureScratch[sampleIndex] = left[frame];
        this._captureScratch[sampleIndex + 1] = right[frame];
      }
      this.port.postMessage({ frames: frameCount, samples: this._captureScratch });
    }
    return true;
  }
}

/** Test-only adapter: drive the real processor with caller-owned synthetic output channels. */
export function processSyntheticQuantum(processor, left, right) {
  return processor.process([], [[left, right]], []);
}

