const VERTEX_SHADER_SOURCE = `#version 300 es
in vec2 a_position;
out vec2 v_uv;
void main() {
  gl_Position = vec4(a_position, 0.0, 1.0);
  v_uv = vec2(a_position.x * 0.5 + 0.5, 0.5 - a_position.y * 0.5);
}`;

const FRAGMENT_SHADER_SOURCE = `#version 300 es
precision highp float;
uniform sampler2D u_texture;
in vec2 v_uv;
out vec4 out_color;
void main() {
  out_color = texture(u_texture, v_uv).bgra;
}`;

function compileShader(gl, type, source) {
  const shader = gl.createShader(type);
  if (shader === null) throw new Error("WebGL2 could not create a shader");
  gl.shaderSource(shader, source);
  gl.compileShader(shader);
  if (!gl.getShaderParameter(shader, gl.COMPILE_STATUS)) {
    const info = gl.getShaderInfoLog(shader) || "unknown shader compile error";
    gl.deleteShader(shader);
    throw new Error(`WebGL2 shader compilation failed: ${info}`);
  }
  return shader;
}

function createProgram(gl) {
  const vertex = compileShader(gl, gl.VERTEX_SHADER, VERTEX_SHADER_SOURCE);
  const fragment = compileShader(gl, gl.FRAGMENT_SHADER, FRAGMENT_SHADER_SOURCE);
  const program = gl.createProgram();
  if (program === null) {
    gl.deleteShader(vertex);
    gl.deleteShader(fragment);
    throw new Error("WebGL2 could not create a program");
  }
  gl.attachShader(program, vertex);
  gl.attachShader(program, fragment);
  gl.linkProgram(program);
  gl.deleteShader(vertex);
  gl.deleteShader(fragment);
  if (!gl.getProgramParameter(program, gl.LINK_STATUS)) {
    const info = gl.getProgramInfoLog(program) || "unknown program link error";
    gl.deleteProgram(program);
    throw new Error(`WebGL2 program link failed: ${info}`);
  }
  return program;
}

function createQuad(gl, program) {
  const vao = gl.createVertexArray();
  const buffer = gl.createBuffer();
  if (vao === null || buffer === null) {
    if (vao !== null) gl.deleteVertexArray(vao);
    if (buffer !== null) gl.deleteBuffer(buffer);
    throw new Error("WebGL2 could not create the fullscreen quad");
  }
  gl.bindVertexArray(vao);
  gl.bindBuffer(gl.ARRAY_BUFFER, buffer);
  gl.bufferData(
    gl.ARRAY_BUFFER,
    new Float32Array([-1, 1, 1, 1, -1, -1, 1, -1]),
    gl.STATIC_DRAW,
  );
  const location = gl.getAttribLocation(program, "a_position");
  if (location < 0) {
    gl.bindVertexArray(null);
    gl.deleteBuffer(buffer);
    gl.deleteVertexArray(vao);
    throw new Error("WebGL2 fullscreen quad position attribute is unavailable");
  }
  gl.enableVertexAttribArray(location);
  gl.vertexAttribPointer(location, 2, gl.FLOAT, false, 0, 0);
  gl.bindVertexArray(null);
  gl.bindBuffer(gl.ARRAY_BUFFER, null);
  return { vao, buffer };
}

function uint32ByteView(pixels, expectedWords) {
  if (!(pixels instanceof Uint32Array)) {
    throw new TypeError("WebGL2 present pixels must be a Uint32Array");
  }
  validatePixelWords(pixels, expectedWords);
  return new Uint8Array(pixels.buffer, pixels.byteOffset, pixels.byteLength);
}

/**
 * Present the T03 full resource-sized BGRA word view through WebGL2.
 *
 * The source is copied as raw bytes into one private Uint8Array so SharedArrayBuffer-backed guest
 * memory never crosses the WebGL API.  WebGL uploads the damage rectangle with row/skip unpack
 * state, and the fragment shader's `.bgra` swizzle converts the core byte order without a
 * JavaScript loop.  The vertex shader maps texture v=0 to the visual top so guest row zero is
 * not upside down on the canvas.
 */
export class WebGL2Backend extends PresentBackend {
  constructor(canvas, { context = null, contextAttributes = DEFAULT_CONTEXT_ATTRIBUTES } = {}) {
    super();
    if (canvas === null || typeof canvas !== "object" || typeof canvas.getContext !== "function") {
      throw new TypeError("WebGL2Backend requires a canvas-like object");
    }
    const gl = context ?? canvas.getContext("webgl2", contextAttributes);
    if (gl === null || typeof gl !== "object") {
      throw new TypeError("WebGL2 is not available for this canvas");
    }
    const size = validateCanvasSize(canvas.width, canvas.height);
    this.canvas = canvas;
    this.gl = gl;
    this.width = size.width;
    this.height = size.height;
    this._canvasBytes = size.bytes;
    this._staging = new Uint8Array(0);
    this._presentCount = 0;
    this._disposed = false;

    this._program = createProgram(gl);
    this._quad = createQuad(gl, this._program);
    this._texture = gl.createTexture();
    if (this._texture === null) {
      this.dispose();
      throw new Error("WebGL2 could not create the scanout texture");
    }
    this._sampler = gl.getUniformLocation(this._program, "u_texture");
    if (this._sampler === null) {
      this.dispose();
      throw new Error("WebGL2 scanout sampler uniform is unavailable");
    }
    this._configureTexture();
    this._allocateTexture(size.width, size.height);
  }

  _assertAlive() {
    if (this._disposed) throw new Error("WebGL2 presentation backend is disposed");
  }

  _configureTexture() {
    const gl = this.gl;
    gl.bindTexture(gl.TEXTURE_2D, this._texture);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.NEAREST);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.NEAREST);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
    gl.pixelStorei(gl.UNPACK_ALIGNMENT, 1);
    gl.bindTexture(gl.TEXTURE_2D, null);
  }

  _allocateTexture(width, height) {
    const gl = this.gl;
    gl.bindTexture(gl.TEXTURE_2D, this._texture);
    gl.texImage2D(
      gl.TEXTURE_2D,
      0,
      gl.RGBA,
      width,
      height,
      0,
      gl.RGBA,
      gl.UNSIGNED_BYTE,
      null,
    );
    gl.bindTexture(gl.TEXTURE_2D, null);
  }

  /** Resize the canvas and reallocate the texture, releasing old private staging. */
  resize(width, height) {
    this._assertAlive();
    const size = validateCanvasSize(width, height);
    this.canvas.width = size.width;
    this.canvas.height = size.height;
    this.width = size.width;
    this.height = size.height;
    this._canvasBytes = size.bytes;
    this._staging = new Uint8Array(0);
    this.gl.viewport(0, 0, size.width, size.height);
    this._allocateTexture(size.width, size.height);
    return { width: this.width, height: this.height };
  }

  _copySource(pixels) {
    const source = uint32ByteView(pixels, this.width * this.height);
    if (source.byteLength !== this._canvasBytes) {
      throw new RangeError("WebGL2 pixel byte view does not match the current canvas");
    }
    if (this._staging.byteLength !== this._canvasBytes) {
      this._staging = new Uint8Array(this._canvasBytes);
    }
    this._staging.set(source);
  }

  _upload(damage) {
    const gl = this.gl;
    gl.bindTexture(gl.TEXTURE_2D, this._texture);
    gl.pixelStorei(gl.UNPACK_ALIGNMENT, 1);
    gl.pixelStorei(gl.UNPACK_ROW_LENGTH, this.width);
    gl.pixelStorei(gl.UNPACK_SKIP_PIXELS, damage.x);
    gl.pixelStorei(gl.UNPACK_SKIP_ROWS, damage.y);
    try {
      gl.texSubImage2D(
        gl.TEXTURE_2D,
        0,
        damage.x,
        damage.y,
        damage.width,
        damage.height,
        gl.RGBA,
        gl.UNSIGNED_BYTE,
        this._staging,
      );
    } finally {
      gl.pixelStorei(gl.UNPACK_ROW_LENGTH, 0);
      gl.pixelStorei(gl.UNPACK_SKIP_PIXELS, 0);
      gl.pixelStorei(gl.UNPACK_SKIP_ROWS, 0);
      gl.bindTexture(gl.TEXTURE_2D, null);
    }
  }

  _draw() {
    const gl = this.gl;
    gl.viewport(0, 0, this.width, this.height);
    gl.useProgram(this._program);
    gl.bindVertexArray(this._quad.vao);
    gl.activeTexture(gl.TEXTURE0);
    gl.bindTexture(gl.TEXTURE_2D, this._texture);
    gl.uniform1i(this._sampler, 0);
    gl.disable(gl.BLEND);
    gl.drawArrays(gl.TRIANGLE_STRIP, 0, 4);
    gl.bindTexture(gl.TEXTURE_2D, null);
    gl.bindVertexArray(null);
  }

  /** Upload one full-frame BGRA view, update its damage rectangle, and redraw the quad. */
  present(rect, pixels) {
    this._assertAlive();
    const damage = validatePresentRect(rect, this.width, this.height);
    this._copySource(pixels);
    this._upload(damage);
    this._draw();
    this._presentCount += 1;
    return damage;
  }

  /** Release GL objects and the private full-frame byte staging buffer. */
  dispose() {
    if (this._disposed) return;
    const gl = this.gl;
    if (this._texture !== undefined && this._texture !== null) gl.deleteTexture(this._texture);
    if (this._quad?.buffer !== undefined && this._quad.buffer !== null) gl.deleteBuffer(this._quad.buffer);
    if (this._quad?.vao !== undefined && this._quad.vao !== null) gl.deleteVertexArray(this._quad.vao);
    if (this._program !== undefined && this._program !== null) gl.deleteProgram(this._program);
    this._texture = null;
    this._quad = null;
    this._program = null;
    this._sampler = null;
    this._staging = new Uint8Array(0);
    this._disposed = true;
  }

  get stagingCapacity() {
    return this._staging.byteLength;
  }

  get canvasByteBudget() {
    return this._canvasBytes;
  }

  get presentCount() {
    return this._presentCount;
  }
}

// E5-T09d: switch the bounded presentation drain between rAF and a hidden-tab timer.

import { FrameScheduler } from "./frame-scheduler.js";

const DEFAULT_TIMER_MS = 250;

function checkedTimerMs(value) {
  const milliseconds = Number(value);
  if (!Number.isSafeInteger(milliseconds) || milliseconds < 1 || milliseconds > DEFAULT_TIMER_MS) {
    throw new RangeError(`hidden presentation timer must be 1..${DEFAULT_TIMER_MS} ms`);
  }
  return milliseconds;
}

function boundGlobal(name) {
  const callback = globalThis[name];
  if (typeof callback !== "function") throw new Error(`VisibilityFrameScheduler requires ${name}`);
  return callback.bind(globalThis);
}

function defaultNow() {
  return typeof globalThis.performance?.now === "function"
    ? globalThis.performance.now()
    : Date.now();
}

/**
 * Own visibility transitions around the generic one-slot FrameScheduler.
 *
 * A scheduled handle is tagged so the matching cancellation primitive is used. Visibility changes
 * pause the inner scheduler, invalidating delayed callbacks, then immediately resume it against
 * the current mode. The inner scheduler still owns latest-wins, counter, and teardown semantics.
 */
export class VisibilityFrameScheduler {
  constructor({
    present,
    visibilityTarget = globalThis.document,
    isHidden,
    requestAnimationFrame,
    cancelAnimationFrame,
    setTimeout,
    clearTimeout,
    now = defaultNow,
    timerMs = DEFAULT_TIMER_MS,
    onError,
  } = {}) {
    if (typeof present !== "function") {
      throw new TypeError("VisibilityFrameScheduler requires a present function");
    }
    if (typeof isHidden !== "function" && visibilityTarget === null) {
      throw new TypeError("VisibilityFrameScheduler requires a visibility target or isHidden function");
    }
    if (typeof now !== "function") throw new TypeError("VisibilityFrameScheduler now must be a function");
    this._visibilityTarget = visibilityTarget;
    this._isHidden = isHidden ?? (() => Boolean(this._visibilityTarget?.hidden));
    if (typeof this._isHidden !== "function") throw new TypeError("VisibilityFrameScheduler isHidden must be a function");
    this._requestAnimationFrame = requestAnimationFrame ?? boundGlobal("requestAnimationFrame");
    this._cancelAnimationFrame = cancelAnimationFrame ?? boundGlobal("cancelAnimationFrame");
    this._setTimeout = setTimeout ?? boundGlobal("setTimeout");
    this._clearTimeout = clearTimeout ?? boundGlobal("clearTimeout");
    if (typeof this._requestAnimationFrame !== "function") throw new TypeError("requestAnimationFrame must be a function");
    if (typeof this._cancelAnimationFrame !== "function") throw new TypeError("cancelAnimationFrame must be a function");
    if (typeof this._setTimeout !== "function") throw new TypeError("setTimeout must be a function");
    if (typeof this._clearTimeout !== "function") throw new TypeError("clearTimeout must be a function");
    this._now = now;
    this._timerMs = checkedTimerMs(timerMs);
    this._manualPaused = false;
    this._disposed = false;

    this._scheduler = new FrameScheduler({
      present,
      requestFrame: (callback) => this._requestFrame(callback),
      cancelFrame: (handle) => this._cancelFrame(handle),
      onError,
    });
    this._onVisibilityChange = () => this.visibilityChanged();
    if (this._visibilityTarget
      && typeof this._visibilityTarget.addEventListener === "function"
      && typeof this._visibilityTarget.removeEventListener === "function") {
      this._visibilityTarget.addEventListener("visibilitychange", this._onVisibilityChange, false);
    }
  }

  _requestFrame(callback) {
    if (this._isHidden()) {
      return {
        mode: "timer",
        id: this._setTimeout(() => callback(this._now()), this._timerMs),
      };
    }
    return { mode: "raf", id: this._requestAnimationFrame(callback) };
  }

  _cancelFrame(handle) {
    if (!handle || typeof handle !== "object") return;
    if (handle.mode === "timer") this._clearTimeout(handle.id);
    else if (handle.mode === "raf") this._cancelAnimationFrame(handle.id);
  }

  get pendingCount() {
    return this._scheduler.pendingCount;
  }

  get scheduled() {
    return this._scheduler.scheduled;
  }

  enqueue(frame) {
    return this._scheduler.enqueue(frame);
  }

  discardPending() {
    return this._scheduler.discardPending();
  }

  pause() {
    if (this._disposed || this._manualPaused) return false;
    this._manualPaused = true;
    return this._scheduler.pause();
  }

  resume() {
    if (this._disposed || !this._manualPaused) return false;
    this._manualPaused = false;
    return this._scheduler.resume();
  }

  /** Reschedule one pending plan in the current visibility mode. */
  visibilityChanged() {
    if (this._disposed || this._manualPaused) return false;
    const hadWork = this.pendingCount !== 0 || this.scheduled;
    this._scheduler.pause();
    this._scheduler.resume();
    return hadWork;
  }

  dispose() {
    if (this._disposed) return;
    this._disposed = true;
    if (this._visibilityTarget && typeof this._visibilityTarget.removeEventListener === "function") {
      this._visibilityTarget.removeEventListener("visibilitychange", this._onVisibilityChange, false);
    }
    this._scheduler.dispose();
  }

  snapshot() {
    return {
      ...this._scheduler.snapshot(),
      hidden: Boolean(this._isHidden()),
      mode: this._isHidden() ? "timer" : "raf",
      timerMs: this._timerMs,
    };
  }
}

// E5-T15b: bounded cursor-resource conversion shared by the browser sink and its proof fixtures.
//
// The core supplies host-owned u32 words synchronously. This module copies those words into a
// private RGBA/PNG representation and never retains the source view. CSS cursor selection is a
// size decision only; pointer-mode and DOM lifecycle policy belong to E5-T15c.

export const CURSOR_FORMAT_B8G8R8A8_UNORM = 1;
export const CURSOR_FORMAT_B8G8R8X8_UNORM = 2;
export const CURSOR_FORMAT_A8R8G8B8_UNORM = 3;
export const CURSOR_FORMAT_X8R8G8B8_UNORM = 4;
export const CURSOR_FORMAT_R8G8B8A8_UNORM = 67;
export const CURSOR_FORMAT_R8G8B8X8_UNORM = 68;

export const CURSOR_CSS_MAX_DIMENSION = 128;
export const CURSOR_MAX_DIMENSION = 256;
export const CURSOR_MAX_PIXELS = CURSOR_MAX_DIMENSION * CURSOR_MAX_DIMENSION;
export const CURSOR_MAX_RGBA_BYTES = CURSOR_MAX_PIXELS * 4;
export const CURSOR_MAX_RAW_BYTES = CURSOR_MAX_RGBA_BYTES + CURSOR_MAX_DIMENSION;
export const CURSOR_DEFLATE_BLOCK_BYTES = 65_535;
export const CURSOR_MAX_DEFLATE_BLOCKS = Math.ceil(CURSOR_MAX_RAW_BYTES / CURSOR_DEFLATE_BLOCK_BYTES);
// PNG = signature + IHDR chunk + IDAT chunk (zlib header, stored-block headers, raw scanlines,
// Adler-32, CRC) + IEND chunk. The exact bound makes every allocation below auditable.
export const CURSOR_MAX_PNG_BYTES =
  8 + (12 + 13) + 12 + (2 + CURSOR_MAX_RAW_BYTES + CURSOR_MAX_DEFLATE_BLOCKS * 5 + 4) + 12;
export const CURSOR_PNG_DATA_URL_PREFIX = "data:image/png;base64,";
export const CURSOR_MAX_DATA_URL_CHARS =
  CURSOR_PNG_DATA_URL_PREFIX.length + 4 * Math.ceil(CURSOR_MAX_PNG_BYTES / 3);

const PNG_SIGNATURE = Object.freeze([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]);
const PNG_IHDR = "IHDR";
const PNG_IDAT = "IDAT";
const PNG_IEND = "IEND";
const ZLIB_MODULO = 65_521;

function checkedInteger(value, name, { min = 0, max = Number.MAX_SAFE_INTEGER } = {}) {
  const number = Number(value);
  if (!Number.isSafeInteger(number) || number < min || number > max) {
    throw new RangeError(`${name} must be an integer in [${min}, ${max}]`);
  }
  return number;
}

/** Validate a cursor resource's dimensions and return all bounded byte counts. */
export function validateCursorSize(width, height) {
  const checkedWidth = checkedInteger(width, "cursor width", { min: 1, max: CURSOR_MAX_DIMENSION });
  const checkedHeight = checkedInteger(height, "cursor height", { min: 1, max: CURSOR_MAX_DIMENSION });
  const pixels = checkedWidth * checkedHeight;
  const rgbaBytes = pixels * 4;
  const rawBytes = rgbaBytes + checkedHeight;
  if (pixels > CURSOR_MAX_PIXELS || rgbaBytes > CURSOR_MAX_RGBA_BYTES || rawBytes > CURSOR_MAX_RAW_BYTES) {
    throw new RangeError("cursor resource exceeds the bounded pixel budget");
  }
  return Object.freeze({
    width: checkedWidth,
    height: checkedHeight,
    pixels,
    rgbaBytes,
    rawBytes,
  });
}

function checkedHotspot(value, name, limit) {
  return checkedInteger(value, name, { min: 0, max: limit - 1 });
}

/** Validate a hotspot against a previously checked cursor size. */
export function validateCursorHotspot(hotX, hotY, width, height) {
  const size = validateCursorSize(width, height);
  return Object.freeze({
    x: checkedHotspot(hotX, "cursor hot_x", size.width),
    y: checkedHotspot(hotY, "cursor hot_y", size.height),
  });
}

function channelLayout(format) {
  switch (Number(format)) {
    // Packed A/R/G/B formats are B/G/R/A in little-endian guest memory.
    case CURSOR_FORMAT_B8G8R8A8_UNORM:
    case CURSOR_FORMAT_A8R8G8B8_UNORM:
      return "bgra";
    // Packed X/R/G/B formats carry no alpha; the browser must see opaque pixels.
    case CURSOR_FORMAT_B8G8R8X8_UNORM:
    case CURSOR_FORMAT_X8R8G8B8_UNORM:
      return "bgrx";
    // Packed R/G/B/A formats are R/G/B/A in little-endian guest memory.
    case CURSOR_FORMAT_R8G8B8A8_UNORM:
      return "rgba";
    case CURSOR_FORMAT_R8G8B8X8_UNORM:
      return "rgbx";
    default:
      throw new RangeError(`unsupported cursor resource format ${String(format)}`);
  }
}

/**
 * Copy checked cursor words into a private row-major RGBA byte array.
 *
 * The source may be a temporary wasm Uint32Array view. It is read exactly once and never stored
 * by the returned value or by CursorSink.
 */
export function cursorWordsToRgba(words, width, height, format = CURSOR_FORMAT_B8G8R8A8_UNORM) {
  const size = validateCursorSize(width, height);
  const layout = channelLayout(format);
  if (words === null || words === undefined || !Number.isSafeInteger(words.length)) {
    throw new TypeError("cursor pixels must be an array-like value");
  }
  if (words.length !== size.pixels) {
    throw new RangeError(`cursor pixel count ${words.length} does not match ${size.width}x${size.height}`);
  }
  const rgba = new Uint8Array(size.rgbaBytes);
  for (let index = 0; index < size.pixels; index += 1) {
    const word = Number(words[index]);
    if (!Number.isSafeInteger(word) || word < 0 || word > 0xffff_ffff) {
      throw new RangeError(`cursor pixel ${index} is not a u32`);
    }
    const offset = index * 4;
    if (layout === "bgra" || layout === "bgrx") {
      rgba[offset] = (word >>> 16) & 0xff;
      rgba[offset + 1] = (word >>> 8) & 0xff;
      rgba[offset + 2] = word & 0xff;
      rgba[offset + 3] = layout === "bgra" ? (word >>> 24) & 0xff : 0xff;
    } else {
      rgba[offset] = word & 0xff;
      rgba[offset + 1] = (word >>> 8) & 0xff;
      rgba[offset + 2] = (word >>> 16) & 0xff;
      rgba[offset + 3] = layout === "rgba" ? (word >>> 24) & 0xff : 0xff;
    }
  }
  return rgba;
}

function writeU16Le(target, offset, value) {
  target[offset] = value & 0xff;
  target[offset + 1] = (value >>> 8) & 0xff;
}

function writeU32Be(target, offset, value) {
  target[offset] = (value >>> 24) & 0xff;
  target[offset + 1] = (value >>> 16) & 0xff;
  target[offset + 2] = (value >>> 8) & 0xff;
  target[offset + 3] = value & 0xff;
}

function crc32(bytes, start, end) {
  let crc = 0xffff_ffff;
  for (let index = start; index < end; index += 1) {
    crc ^= bytes[index];
    for (let bit = 0; bit < 8; bit += 1) {
      crc = (crc >>> 1) ^ (0xedb8_8320 & -(crc & 1));
    }
  }
  return (~crc) >>> 0;
}

function adler32(bytes) {
  let a = 1;
  let b = 0;
  for (const byte of bytes) {
    a = (a + byte) % ZLIB_MODULO;
    b = (b + a) % ZLIB_MODULO;
  }
  return ((b << 16) | a) >>> 0;
}

function writeChunk(target, offset, type, data) {
  writeU32Be(target, offset, data.length);
  offset += 4;
  const typeStart = offset;
  for (let index = 0; index < 4; index += 1) target[offset + index] = type.charCodeAt(index);
  offset += 4;
  target.set(data, offset);
  offset += data.length;
  writeU32Be(target, offset, crc32(target, typeStart, offset));
  return offset + 4;
}

function writeZlibStoredStream(target, offset, raw) {
  target[offset++] = 0x78;
  target[offset++] = 0x01;
  for (let start = 0; start < raw.length; start += CURSOR_DEFLATE_BLOCK_BYTES) {
    const length = Math.min(CURSOR_DEFLATE_BLOCK_BYTES, raw.length - start);
    const final = start + length === raw.length;
    // Stored DEFLATE blocks are byte-aligned. BTYPE=00 plus the final bit is 0x00/0x01.
    target[offset++] = final ? 0x01 : 0x00;
    writeU16Le(target, offset, length);
    offset += 2;
    writeU16Le(target, offset, (~length) & 0xffff);
    offset += 2;
    target.set(raw.subarray(start, start + length), offset);
    offset += length;
  }
  writeU32Be(target, offset, adler32(raw));
  return offset + 4;
}

/** Encode RGBA bytes as a deterministic PNG with bounded stored-DEFLATE blocks. */
export function encodeCursorPng(rgba, width, height) {
  const size = validateCursorSize(width, height);
  if (rgba === null || rgba === undefined || rgba.byteLength !== size.rgbaBytes) {
    throw new RangeError(`cursor RGBA byte length must be ${size.rgbaBytes}`);
  }
  const source = rgba instanceof Uint8Array
    ? rgba
    : new Uint8Array(rgba.buffer, rgba.byteOffset, rgba.byteLength);
  const raw = new Uint8Array(size.rawBytes);
  const rowBytes = size.width * 4;
  for (let row = 0; row < size.height; row += 1) {
    const rawOffset = row * (rowBytes + 1);
    raw[rawOffset] = 0; // PNG filter type None; checkerboard/alpha bytes remain untouched.
    raw.set(source.subarray(row * rowBytes, (row + 1) * rowBytes), rawOffset + 1);
  }

  const blocks = Math.ceil(raw.length / CURSOR_DEFLATE_BLOCK_BYTES);
  const zlibBytes = 2 + raw.length + blocks * 5 + 4;
  const idatBytes = zlibBytes;
  const pngBytes = 8 + (12 + 13) + (12 + idatBytes) + 12;
  if (blocks > CURSOR_MAX_DEFLATE_BLOCKS || pngBytes > CURSOR_MAX_PNG_BYTES) {
    throw new RangeError("cursor PNG exceeds the bounded encoding budget");
  }
  const output = new Uint8Array(pngBytes);
  output.set(PNG_SIGNATURE, 0);
  let offset = PNG_SIGNATURE.length;
  const ihdr = new Uint8Array(13);
  writeU32Be(ihdr, 0, size.width);
  writeU32Be(ihdr, 4, size.height);
  ihdr[8] = 8; // bit depth
  ihdr[9] = 6; // color type RGBA
  ihdr[10] = 0; // compression
  ihdr[11] = 0; // filter
  ihdr[12] = 0; // no interlace
  offset = writeChunk(output, offset, PNG_IHDR, ihdr);

  writeU32Be(output, offset, idatBytes);
  offset += 4;
  const idatTypeStart = offset;
  for (let index = 0; index < 4; index += 1) output[offset + index] = PNG_IDAT.charCodeAt(index);
  offset += 4;
  const idatPayloadEnd = writeZlibStoredStream(output, offset, raw);
  offset = idatPayloadEnd;
  writeU32Be(output, offset, crc32(output, idatTypeStart, idatPayloadEnd));
  offset += 4;
  offset = writeChunk(output, offset, PNG_IEND, new Uint8Array(0));
  if (offset !== output.length) throw new Error("cursor PNG size accounting drifted");
  return output;
}

function bytesToBase64(bytes) {
  if (typeof btoa === "function") {
    const parts = [];
    // Every non-final chunk must be a multiple of three bytes. Otherwise btoa adds padding to
    // each chunk and concatenating those fragments no longer decodes to the original PNG.
    const chunkBytes = 0x7ffe;
    for (let start = 0; start < bytes.length; start += chunkBytes) {
      parts.push(btoa(String.fromCharCode(...bytes.subarray(start, start + chunkBytes))));
    }
    return parts.join("");
  }
  const alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
  let output = "";
  for (let index = 0; index < bytes.length; index += 3) {
    const a = bytes[index];
    const b = index + 1 < bytes.length ? bytes[index + 1] : 0;
    const c = index + 2 < bytes.length ? bytes[index + 2] : 0;
    const value = (a << 16) | (b << 8) | c;
    output += alphabet[(value >>> 18) & 63];
    output += alphabet[(value >>> 12) & 63];
    output += index + 1 < bytes.length ? alphabet[(value >>> 6) & 63] : "=";
    output += index + 2 < bytes.length ? alphabet[value & 63] : "=";
  }
  return output;
}

/** Encode a private RGBA cursor as a self-contained PNG data URL. */
export function cursorPngDataUrl(rgba, width, height) {
  const png = encodeCursorPng(rgba, width, height);
  const dataUrl = `${CURSOR_PNG_DATA_URL_PREFIX}${bytesToBase64(png)}`;
  if (dataUrl.length > CURSOR_MAX_DATA_URL_CHARS) {
    throw new RangeError("cursor data URL exceeds the bounded encoding budget");
  }
  return dataUrl;
}

/** Return the exact CSS cursor declaration for a checked PNG and hotspot. */
export function cssCursorDescriptor(dataUrl, hotX, hotY, width, height) {
  if (typeof dataUrl !== "string" || dataUrl.length === 0 || /["'\\\r\n]/.test(dataUrl)) {
    throw new TypeError("cursor data URL is not CSS-safe");
  }
  const hotspot = validateCursorHotspot(hotX, hotY, width, height);
  return `url("${dataUrl}") ${hotspot.x} ${hotspot.y}, none`;
}

/** Choose CSS for browser-sized cursors and the transform-driven overlay for larger images. */
export function cursorPresentationMode(width, height, cssMaxDimension = CURSOR_CSS_MAX_DIMENSION) {
  const size = validateCursorSize(width, height);
  const max = checkedInteger(cssMaxDimension, "CSS cursor dimension", {
    min: 1,
    max: CURSOR_MAX_DIMENSION,
  });
  return size.width <= max && size.height <= max ? "css" : "overlay";
}

/** Return a DOM-ready overlay asset descriptor; E5-T15c owns its element and transform lifecycle. */
export function overlayCursorDescriptor(dataUrl, hotX, hotY, width, height) {
  if (typeof dataUrl !== "string" || dataUrl.length === 0) {
    throw new TypeError("cursor data URL is missing");
  }
  const size = validateCursorSize(width, height);
  const hotspot = validateCursorHotspot(hotX, hotY, size.width, size.height);
  return Object.freeze({
    kind: "overlay",
    src: dataUrl,
    width: size.width,
    height: size.height,
    hotX: hotspot.x,
    hotY: hotspot.y,
  });
}

function normalizedState(state) {
  if (state === null || typeof state !== "object") throw new TypeError("cursor state is missing");
  const pos = state.pos && typeof state.pos === "object" ? state.pos : state;
  return Object.freeze({
    resourceId: checkedInteger(state.resourceId, "cursor resource id", { min: 0, max: 0xffff_ffff }),
    hotX: checkedInteger(state.hotX ?? state.hot_x, "cursor hot_x", { min: 0, max: 0xffff_ffff }),
    hotY: checkedInteger(state.hotY ?? state.hot_y, "cursor hot_y", { min: 0, max: 0xffff_ffff }),
    scanout: checkedInteger(pos.scanout ?? pos.scanoutId ?? pos.scanout_id, "cursor scanout", {
      min: 0,
      max: 0xffff_ffff,
    }),
    x: checkedInteger(pos.x, "cursor x", { min: 0, max: 0xffff_ffff }),
    y: checkedInteger(pos.y, "cursor y", { min: 0, max: 0xffff_ffff }),
  });
}

function emitSafely(callback, value, sink) {
  try {
    callback(value);
  } catch {
    sink._callbackErrors += 1;
  }
}

/**
 * Convert cursor callbacks into one bounded current descriptor.
 *
 * The sink stores only the current PNG data URL and scalar metadata. It deliberately retains no
 * source Uint32Array, RGBA staging array, or history of prior updates.
 */
export class CursorSink {
  constructor({ onChange = () => {}, cssMaxDimension = CURSOR_CSS_MAX_DIMENSION } = {}) {
    if (typeof onChange !== "function") throw new TypeError("cursor sink onChange must be a function");
    this._onChange = onChange;
    this._cssMaxDimension = checkedInteger(cssMaxDimension, "CSS cursor dimension", {
      min: 1,
      max: CURSOR_MAX_DIMENSION,
    });
    this._descriptor = Object.freeze({ kind: "hidden" });
    this._updates = 0;
    this._callbackErrors = 0;
  }

  /** Consume one synchronous core callback and return the new CSS/overlay/hidden descriptor. */
  update(state, format, width, height, pixels) {
    const current = normalizedState(state);
    this._updates += 1;
    if (current.resourceId === 0) {
      this._descriptor = Object.freeze({ kind: "hidden", state: current });
      emitSafely(this._onChange, this._descriptor, this);
      return this._descriptor;
    }
    const size = validateCursorSize(width, height);
    const hotspot = validateCursorHotspot(current.hotX, current.hotY, size.width, size.height);
    const rgba = cursorWordsToRgba(pixels, size.width, size.height, format);
    const dataUrl = cursorPngDataUrl(rgba, size.width, size.height);
    const mode = cursorPresentationMode(size.width, size.height, this._cssMaxDimension);
    this._descriptor = mode === "css"
      ? Object.freeze({
        kind: "css",
        state: current,
        width: size.width,
        height: size.height,
        hotX: hotspot.x,
        hotY: hotspot.y,
        dataUrl,
        css: cssCursorDescriptor(dataUrl, hotspot.x, hotspot.y, size.width, size.height),
      })
      : Object.freeze({
        ...overlayCursorDescriptor(dataUrl, hotspot.x, hotspot.y, size.width, size.height),
        state: current,
      });
    emitSafely(this._onChange, this._descriptor, this);
    return this._descriptor;
  }

  /** Hide the current cursor without retaining the previous image. */
  hide(state = {
    resourceId: 0,
    hotX: 0,
    hotY: 0,
    scanout: 0,
    x: 0,
    y: 0,
  }) {
    return this.update(state, null, 1, 1, new Uint32Array(1));
  }

  /** Compact diagnostics; no image bytes or source buffers escape. */
  snapshot() {
    const descriptor = this._descriptor;
    return Object.freeze({
      kind: descriptor.kind,
      width: descriptor.width ?? 0,
      height: descriptor.height ?? 0,
      hotX: descriptor.hotX ?? 0,
      hotY: descriptor.hotY ?? 0,
      dataUrlChars: descriptor.dataUrl?.length ?? 0,
      updates: this._updates,
      callbackErrors: this._callbackErrors,
    });
  }
}

// E5-T26f: page-owned transport adapter for the T23d Channel over the worker-safe
// sendAgentInput/onAgentOutput controller seam.

import { Channel } from "./agent-channel.js";

function ownedBytes(value) {
  if (value instanceof Uint8Array) return value.slice();
  if (value instanceof ArrayBuffer) return new Uint8Array(value.slice(0));
  if (ArrayBuffer.isView(value)) {
    return new Uint8Array(value.buffer, value.byteOffset, value.byteLength).slice();
  }
  return Uint8Array.from(value || []);
}

/**
 * Build one reconnectable agent Channel whose transport is the live WasmLinux controller.
 * Guest output is delivered by `receive`; the returned object deliberately owns the copy so the
 * worker's transferred buffer cannot be reused by a decoder or a later restore attempt.
 */
export function createDesktopAgentBridge(controller, { onError = null } = {}) {
  if (!controller || typeof controller.sendAgentInput !== "function") {
    throw new TypeError("desktop agent bridge requires sendAgentInput");
  }

  let active = null;
  const pending = [];
  let bytesReceived = 0;
  let bytesSent = 0;
  let started = false;

  const channel = new Channel({
    reconnect: true,
    onError,
    connect: () => ({
      send(bytes) {
        const copy = ownedBytes(bytes);
        return Promise.resolve(controller.sendAgentInput(copy)).then((accepted) => {
          if (Number(accepted) !== copy.byteLength) {
            throw new Error(`agent input backpressure accepted ${Number(accepted)}/${copy.byteLength} bytes`);
          }
          bytesSent += copy.byteLength;
          return true;
        });
      },
      subscribe(handlers) {
        const transport = { handlers };
        active = transport;
        const queued = pending.splice(0);
        for (const bytes of queued) handlers.data(bytes);
        return () => {
          if (active === transport) active = null;
        };
      },
      close() {
        // Channel owns the reconnect lifecycle. The next connector attempt installs a fresh
        // `active` record; queued guest bytes are flushed only by that fresh listener.
      },
    }),
  });

  return {
    channel,
    start() {
      if (!started) {
        started = true;
        channel.start();
      }
      return channel;
    },
    receive(value) {
      const bytes = ownedBytes(value);
      if (!bytes.byteLength) return 0;
      bytesReceived += bytes.byteLength;
      if (active) active.handlers.data(bytes);
      else pending.push(bytes);
      return bytes.byteLength;
    },
    close(reason = "desktop agent bridge closed") {
      pending.length = 0;
      return channel.close(reason);
    },
    stats() {
      return {
        state: channel.state,
        negotiatedVersion: channel.negotiatedVersion,
        transportGeneration: channel.transportGeneration ?? null,
        bytesReceived,
        bytesSent,
        pendingBytes: pending.reduce((total, bytes) => total + bytes.byteLength, 0),
      };
    },
  };
}

// E5-T23d — host-side agent Channel.
//
// This module deliberately knows nothing about Window, DOM, or the virtio implementation. A
// transport only needs send(bytes), subscribe({ data, close, error }), and optionally close(). That
// shape works in a page, a DedicatedWorker, and Node's deterministic fixtures alike.

export const FRAME_HEADER_BYTES = 8;
export const MAX_PAYLOAD_BYTES = 1 << 20;
export const MAX_CLIPBOARD_BYTES = 256 << 10;
export const PROTOCOL_VERSION = 1;

export const TYPE_HELLO = 0;
export const TYPE_PING = 1;
export const TYPE_PONG = 2;
export const TYPE_NAK = 3;
export const TYPE_CLIP_SET = 4;
export const TYPE_CLIP_GET = 5;

export const FLAG_NONE = 0;
export const NAK_UNKNOWN_TYPE = 1;
export const NAK_INVALID_PAYLOAD = 2;
export const NAK_CAPABILITY = 3;
export const NAK_CLIPBOARD_UNAVAILABLE = 4;

export const CAP_PING = 1n << 0n;
export const CAP_CLIPBOARD = 1n << 1n;
export const CAP_DISPLAY = 1n << 2n;

export const CHANNEL_STATE = Object.freeze({
  IDLE: "idle",
  CONNECTING: "connecting",
  HANDSHAKING: "handshaking",
  READY: "ready",
  DISCONNECTED: "disconnected",
  CLOSED: "closed",
});

const UINT64_MAX = (1n << 64n) - 1n;
const DEFAULT_MAX_PENDING = 1_024;
const DEFAULT_HANDSHAKE_TIMEOUT_MS = 2_000;
const DEFAULT_PING_TIMEOUT_MS = 5_000;
const DEFAULT_RECONNECT_MIN_DELAY_MS = 10;
const DEFAULT_RECONNECT_MAX_DELAY_MS = 800;

export class AgentChannelError extends Error {
  constructor(message, code = "CHANNEL_ERROR", options = {}) {
    super(message, options);
    this.name = new.target.name;
    this.code = code;
  }
}

export class DisconnectedError extends AgentChannelError {
  constructor(message = "agent channel is disconnected", options = {}) {
    super(message, "DISCONNECTED", options);
  }
}

export class BackpressureError extends AgentChannelError {
  constructor(message = "agent channel pending limit reached", options = {}) {
    super(message, "BACKPRESSURE", options);
  }
}

export class CapabilityError extends AgentChannelError {
  constructor(message = "agent channel capability is not negotiated", options = {}) {
    super(message, "CAPABILITY", options);
  }
}

export class NegotiationError extends AgentChannelError {
  constructor(message = "agent channel has no common protocol version", options = {}) {
    super(message, "NO_COMMON_VERSION", options);
  }
}

export class ProtocolError extends AgentChannelError {
  constructor(message = "invalid agent channel frame", code = "PROTOCOL", options = {}) {
    super(message, code, options);
  }
}

export class RequestTimeoutError extends AgentChannelError {
  constructor(message = "agent channel request timed out", options = {}) {
    super(message, "TIMEOUT", options);
  }
}

export class NakError extends AgentChannelError {
  constructor(message = "agent rejected the channel request", options = {}) {
    super(message, "NAK", options);
  }
}

export class ClipboardError extends AgentChannelError {
  constructor(message = "invalid clipboard payload", code = "CLIPBOARD_INVALID_UTF8", options = {}) {
    super(message, code, options);
  }
}

function viewBytes(value, label = "bytes") {
  if (value instanceof Uint8Array) return value;
  if (value instanceof ArrayBuffer) return new Uint8Array(value);
  if (ArrayBuffer.isView(value)) return new Uint8Array(value.buffer, value.byteOffset, value.byteLength);
  if (Array.isArray(value)) return Uint8Array.from(value);
  throw new TypeError(`${label} must be an ArrayBuffer or Uint8Array`);
}

function ownedBytes(value, label = "bytes") {
  return viewBytes(value, label).slice();
}

function integerInRange(value, min, max, label) {
  const number = Number(value);
  if (!Number.isInteger(number) || number < min || number > max) {
    throw new RangeError(`${label} must be an integer between ${min} and ${max}`);
  }
  return number;
}

function asU64(value, label) {
  let number;
  try {
    number = BigInt(value);
  } catch (error) {
    throw new RangeError(`${label} must be an unsigned 64-bit integer`, { cause: error });
  }
  if (number < 0n || number > UINT64_MAX) {
    throw new RangeError(`${label} must be an unsigned 64-bit integer`);
  }
  return number;
}

function writeU64LE(output, offset, value) {
  let remaining = value;
  for (let index = 0; index < 8; index += 1) {
    output[offset + index] = Number(remaining & 0xffn);
    remaining >>= 8n;
  }
}

function readU64LE(input, offset = 0) {
  let value = 0n;
  for (let index = 7; index >= 0; index -= 1) {
    value = (value << 8n) | BigInt(input[offset + index]);
  }
  return value;
}

function frameRecord(type, flags, payload) {
  return Object.freeze({
    type,
    messageType: type,
    flags,
    payload,
  });
}

/** Encode the shared little-endian {u32 len, u16 type, u16 flags, payload} frame. */
export function encodeFrame(typeOrFrame, payload, flags = FLAG_NONE) {
  let type = typeOrFrame;
  let body = payload;
  let frameFlags = flags;
  if (typeOrFrame && typeof typeOrFrame === "object" && !ArrayBuffer.isView(typeOrFrame)
      && !(typeOrFrame instanceof ArrayBuffer)) {
    type = typeOrFrame.type ?? typeOrFrame.messageType;
    body = typeOrFrame.payload ?? new Uint8Array();
    frameFlags = typeOrFrame.flags ?? FLAG_NONE;
  }
  type = integerInRange(type, 0, 0xffff, "message type");
  frameFlags = integerInRange(frameFlags, 0, 0xffff, "frame flags");
  body = ownedBytes(body ?? new Uint8Array(), "frame payload");
  if (body.byteLength > MAX_PAYLOAD_BYTES) {
    throw new RangeError(`frame payload exceeds ${MAX_PAYLOAD_BYTES} bytes`);
  }
  const output = new Uint8Array(FRAME_HEADER_BYTES + body.byteLength);
  const view = new DataView(output.buffer);
  view.setUint32(0, body.byteLength, true);
  view.setUint16(4, type, true);
  view.setUint16(6, frameFlags, true);
  output.set(body, FRAME_HEADER_BYTES);
  return output;
}

function encodeHello(version, capabilities) {
  const payload = new Uint8Array(10);
  const view = new DataView(payload.buffer);
  view.setUint16(0, version, true);
  writeU64LE(payload, 2, capabilities);
  return payload;
}

function decodeHello(payload) {
  if (payload.byteLength !== 10) {
    throw new ProtocolError(`HELLO payload has ${payload.byteLength} bytes; expected 10`, "HELLO_LENGTH");
  }
  const view = new DataView(payload.buffer, payload.byteOffset, payload.byteLength);
  return Object.freeze({
    version: view.getUint16(0, true),
    capabilities: readU64LE(payload, 2),
  });
}

function encodePing(nonce) {
  const payload = new Uint8Array(8);
  writeU64LE(payload, 0, nonce);
  return payload;
}

function decodePing(payload, typeName) {
  if (payload.byteLength !== 8) {
    throw new ProtocolError(`${typeName} payload has ${payload.byteLength} bytes; expected 8`, `${typeName}_LENGTH`);
  }
  return readU64LE(payload, 0);
}

function encodeNak(rejectedType, code = NAK_UNKNOWN_TYPE) {
  const payload = new Uint8Array(4);
  const view = new DataView(payload.buffer);
  view.setUint16(0, rejectedType, true);
  view.setUint16(2, code, true);
  return payload;
}

function decodeNak(payload) {
  if (payload.byteLength !== 4) {
    throw new ProtocolError(`NAK payload has ${payload.byteLength} bytes; expected 4`, "NAK_LENGTH");
  }
  const view = new DataView(payload.buffer, payload.byteOffset, payload.byteLength);
  return Object.freeze({
    rejectedType: view.getUint16(0, true),
    code: view.getUint16(2, true),
  });
}

function assertWellFormedString(value) {
  for (let index = 0; index < value.length; index += 1) {
    const code = value.charCodeAt(index);
    if (code >= 0xd800 && code <= 0xdbff) {
      const next = value.charCodeAt(index + 1);
      if (Number.isNaN(next) || next < 0xdc00 || next > 0xdfff) {
        throw new ClipboardError("clipboard string contains an unpaired UTF-16 surrogate");
      }
      index += 1;
    } else if (code >= 0xdc00 && code <= 0xdfff) {
      throw new ClipboardError("clipboard string contains an unpaired UTF-16 surrogate");
    }
  }
}

/** Encode or validate one text/plain clipboard payload without applying the 1 MiB frame limit. */
export function encodeClipboardText(value) {
  let bytes;
  if (typeof value === "string") {
    assertWellFormedString(value);
    bytes = new TextEncoder().encode(value);
  } else {
    bytes = viewBytes(value, "clipboard payload");
    try {
      new TextDecoder("utf-8", { fatal: true }).decode(bytes);
    } catch (error) {
      throw new ClipboardError("clipboard payload is not valid UTF-8", "CLIPBOARD_INVALID_UTF8", { cause: error });
    }
  }
  if (bytes.byteLength > MAX_CLIPBOARD_BYTES) {
    throw new ClipboardError(
      `clipboard payload exceeds ${MAX_CLIPBOARD_BYTES} bytes`,
      "CLIPBOARD_TOO_LARGE",
    );
  }
  return bytes.slice();
}

/** Decode a text/plain clipboard payload; rejected input is not copied or delivered. */
export function decodeClipboardText(payload) {
  const bytes = viewBytes(payload, "clipboard payload");
  if (bytes.byteLength > MAX_CLIPBOARD_BYTES) {
    throw new ClipboardError(
      `clipboard payload exceeds ${MAX_CLIPBOARD_BYTES} bytes`,
      "CLIPBOARD_TOO_LARGE",
    );
  }
  let text;
  try {
    text = new TextDecoder("utf-8", { fatal: true }).decode(bytes);
  } catch (error) {
    throw new ClipboardError("clipboard payload is not valid UTF-8", "CLIPBOARD_INVALID_UTF8", { cause: error });
  }
  return Object.freeze({ text, bytes: bytes.slice() });
}

/** Encode a CLIP_SET frame carrying exactly one bounded UTF-8 text/plain payload. */
export function encodeClipboardSet(value, flags = FLAG_NONE) {
  return encodeFrame(TYPE_CLIP_SET, encodeClipboardText(value), flags);
}

/** Decode the payload of a CLIP_SET frame into text and owned UTF-8 bytes. */
export function decodeClipboardSet(payload) {
  return decodeClipboardText(payload);
}

/** Encode a CLIP_GET request; its payload is always empty. */
export function encodeClipboardGet(flags = FLAG_NONE) {
  return encodeFrame(TYPE_CLIP_GET, new Uint8Array(), flags);
}

/** Validate the payload of a CLIP_GET request. */
export function decodeClipboardGet(payload) {
  const bytes = viewBytes(payload, "CLIP_GET payload");
  if (bytes.byteLength !== 0) {
    throw new ProtocolError(`CLIP_GET payload has ${bytes.byteLength} bytes; expected 0`, "CLIP_GET_LENGTH");
  }
  return Object.freeze({});
}

/**
 * Incremental parser for one connection. Oversized lengths are rejected before a payload buffer
 * is allocated; malformed or truncated data is connection-fatal because the stream has no magic
 * byte with which to safely resynchronize.
 */
export class AgentFrameDecoder {
  constructor() {
    this._header = new Uint8Array(FRAME_HEADER_BYTES);
    this._headerLength = 0;
    this._payloadLength = null;
    this._payloadFilled = 0;
    this._type = 0;
    this._flags = 0;
    this._payload = null;
  }

  get pendingBytes() {
    return this._headerLength + this._payloadFilled;
  }

  get payloadCapacity() {
    return this._payload?.byteLength ?? 0;
  }

  get idle() {
    return this._headerLength === 0;
  }

  push(input, emit) {
    const bytes = viewBytes(input, "frame input");
    let offset = 0;
    while (offset < bytes.byteLength) {
      if (this._headerLength < FRAME_HEADER_BYTES) {
        const count = Math.min(FRAME_HEADER_BYTES - this._headerLength, bytes.byteLength - offset);
        this._header.set(bytes.subarray(offset, offset + count), this._headerLength);
        this._headerLength += count;
        offset += count;
        if (this._headerLength < FRAME_HEADER_BYTES) break;

        const header = new DataView(this._header.buffer);
        this._payloadLength = header.getUint32(0, true);
        if (this._payloadLength > MAX_PAYLOAD_BYTES) {
          this.reset();
          throw new ProtocolError(
            `frame payload length ${this._payloadLength} exceeds ${MAX_PAYLOAD_BYTES}`,
            "PAYLOAD_TOO_LARGE",
          );
        }
        this._type = header.getUint16(4, true);
        this._flags = header.getUint16(6, true);
        this._payloadFilled = 0;
        this._payload = this._payloadLength === 0 ? new Uint8Array() : new Uint8Array(this._payloadLength);
      }

      const remaining = this._payloadLength - this._payloadFilled;
      const count = Math.min(remaining, bytes.byteLength - offset);
      if (count > 0) {
        this._payload.set(bytes.subarray(offset, offset + count), this._payloadFilled);
        this._payloadFilled += count;
        offset += count;
      }
      if (this._payloadFilled !== this._payloadLength) break;

      const frame = frameRecord(this._type, this._flags, this._payload);
      this._resetFrame();
      emit?.(frame);
    }
    return offset;
  }

  finish() {
    if (!this.idle) {
      throw new ProtocolError(`stream ended with ${this.pendingBytes} pending bytes`, "TRUNCATED");
    }
  }

  reset() {
    this._resetFrame();
  }

  _resetFrame() {
    this._headerLength = 0;
    this._payloadLength = null;
    this._payloadFilled = 0;
    this._type = 0;
    this._flags = 0;
    this._payload = null;
  }
}

function deferred() {
  let resolve;
  let reject;
  const promise = new Promise((resolveValue, rejectValue) => {
    resolve = resolveValue;
    reject = rejectValue;
  });
  // Reconnect and close may settle a promise before a consumer attaches. Keep that lifecycle
  // diagnostic from becoming a process-level unhandled rejection while returning the same promise.
  promise.catch(() => {});
  return { promise, resolve, reject, settled: false };
}

function eventData(value) {
  if (value && typeof value === "object" && !(value instanceof Uint8Array)
      && !(value instanceof ArrayBuffer) && ArrayBuffer.isView(value) === false
      && "data" in value) {
    return value.data;
  }
  return value;
}

/**
 * Adapt a MessagePort, Worker, or compatible endpoint without depending on a main-thread global.
 * The channel owns the endpoint listener and transfers a private frame copy on every send.
 */
export function createMessageTransport(endpoint) {
  if (!endpoint || typeof endpoint.postMessage !== "function") {
    throw new TypeError("message transport endpoint must provide postMessage()");
  }
  return {
    send(bytes) {
      const copy = ownedBytes(bytes, "transport frame");
      endpoint.postMessage(copy, [copy.buffer]);
    },
    subscribe(handlers) {
      const onMessage = (event) => handlers.data?.(eventData(event));
      const onClose = (event) => handlers.close?.(event?.reason ?? event);
      const onError = (event) => handlers.error?.(event?.error ?? event);
      if (typeof endpoint.addEventListener === "function") {
        endpoint.addEventListener("message", onMessage);
        endpoint.addEventListener("close", onClose);
        endpoint.addEventListener("messageerror", onError);
        endpoint.addEventListener("error", onError);
        endpoint.start?.();
        return () => {
          endpoint.removeEventListener?.("message", onMessage);
          endpoint.removeEventListener?.("close", onClose);
          endpoint.removeEventListener?.("messageerror", onError);
          endpoint.removeEventListener?.("error", onError);
        };
      }
      const previousMessage = endpoint.onmessage;
      const previousError = endpoint.onmessageerror;
      endpoint.onmessage = onMessage;
      endpoint.onmessageerror = onError;
      return () => {
        if (endpoint.onmessage === onMessage) endpoint.onmessage = previousMessage ?? null;
        if (endpoint.onmessageerror === onError) endpoint.onmessageerror = previousError ?? null;
      };
    },
    close() {
      endpoint.close?.();
      if (typeof endpoint.close !== "function") endpoint.terminate?.();
    },
  };
}

function subscribeTransport(transport, handlers) {
  if (typeof transport.subscribe === "function") {
    const unsubscribe = transport.subscribe(handlers);
    return typeof unsubscribe === "function" ? unsubscribe : () => {};
  }
  if (typeof transport.addEventListener === "function" && typeof transport.postMessage === "function") {
    return createMessageTransport(transport).subscribe(handlers);
  }
  throw new TypeError("agent transport must provide subscribe() or an event endpoint");
}

function normalizeTransport(candidate) {
  const transport = candidate?.transport ?? candidate;
  if (transport && typeof transport.send === "function") return transport;
  if (transport && typeof transport.postMessage === "function") return createMessageTransport(transport);
  throw new TypeError("agent connector must return a transport");
}

function normalizeMilliseconds(value, fallback, { minimum = 0 } = {}) {
  if (value == null) return fallback;
  const number = Number(value);
  if (!Number.isFinite(number) || number < minimum) {
    throw new RangeError(`timeout must be a finite number >= ${minimum}`);
  }
  return number;
}

/**
 * Host-side Channel for the shared guest-agent protocol.
 *
 * `connect({ attempt })` must return a fresh transport (or a Promise for one). `start()` is
 * non-blocking; await `channel.ready` for the first successful HELLO intersection and
 * `waitUntilReady()` for a later reconnect. User subscriptions survive reconnects, while the
 * transport listener is removed before its old transport is closed.
 */
export class Channel {
  constructor(options = {}) {
    const hasConnector = typeof options.connect === "function";
    const hasTransport = options.transport != null;
    if (!hasConnector && !hasTransport) {
      throw new TypeError("agent Channel requires connect() or transport");
    }
    this._connect = hasConnector ? options.connect : () => options.transport;
    this._reconnectEnabled = options.reconnect ?? hasConnector;
    this._localVersion = integerInRange(options.version ?? PROTOCOL_VERSION, 0, 0xffff, "protocol version");
    this._localCapabilities = asU64(options.capabilities ?? CAP_PING, "capabilities");
    this._maxPending = integerInRange(options.maxPending ?? DEFAULT_MAX_PENDING, 1, 1_000_000, "maxPending");
    this._handshakeTimeoutMs = normalizeMilliseconds(
      options.handshakeTimeoutMs,
      DEFAULT_HANDSHAKE_TIMEOUT_MS,
      { minimum: 1 },
    );
    this._pingTimeoutMs = normalizeMilliseconds(options.pingTimeoutMs, DEFAULT_PING_TIMEOUT_MS, { minimum: 0 });
    this._reconnectMinDelayMs = normalizeMilliseconds(
      options.reconnectMinDelayMs,
      DEFAULT_RECONNECT_MIN_DELAY_MS,
    );
    this._reconnectMaxDelayMs = normalizeMilliseconds(
      options.reconnectMaxDelayMs,
      Math.max(DEFAULT_RECONNECT_MAX_DELAY_MS, this._reconnectMinDelayMs),
    );
    if (this._reconnectMaxDelayMs < this._reconnectMinDelayMs) {
      throw new RangeError("reconnectMaxDelayMs must be >= reconnectMinDelayMs");
    }
    this._maxReconnectAttempts = options.maxReconnectAttempts == null
      ? Infinity
      : integerInRange(options.maxReconnectAttempts, 0, 1_000_000, "maxReconnectAttempts");
    this._onError = typeof options.onError === "function" ? options.onError : null;

    this._state = CHANNEL_STATE.IDLE;
    this._negotiated = null;
    this._peerHello = null;
    this._firstReady = deferred();
    this._readyWaiters = new Set();
    this._stateListeners = new Set();
    this._subscriptions = new Map();
    this._pending = new Map();
    this._nextNonce = 1n;
    this._started = false;
    this._closed = false;
    this._connecting = false;
    this._connectAttempt = 0;
    this._reconnectAttempts = 0;
    this._retryDelayMs = this._reconnectMinDelayMs;
    this._retryTimer = null;
    this._handshakeTimer = null;
    this._generation = 0;
    this._transportGeneration = 0;
    this._transport = null;
    this._transportUnsubscribe = null;
    this._decoder = new AgentFrameDecoder();
    this._writeTail = Promise.resolve();
    this._writeDepth = 0;
    this._lastError = null;
  }

  get state() {
    return this._state;
  }

  get ready() {
    return this._firstReady.promise;
  }

  get negotiated() {
    return this._negotiated;
  }

  get negotiatedVersion() {
    return this._negotiated?.version ?? null;
  }

  get transportGeneration() {
    return this._transportGeneration;
  }

  get negotiatedCapabilities() {
    return this._negotiated?.capabilities ?? 0n;
  }

  get pendingCount() {
    return this._pending.size;
  }

  get maxPending() {
    return this._maxPending;
  }

  get lastError() {
    return this._lastError;
  }

  /** Start connection attempts; returns immediately so callers can attach to `ready`. */
  start() {
    if (this._closed) throw new DisconnectedError("agent channel is closed");
    if (this._started) return this;
    this._started = true;
    void this._attemptConnect();
    return this;
  }

  waitUntilReady() {
    if (this._state === CHANNEL_STATE.READY) return Promise.resolve(this._negotiated);
    if (this._closed) return Promise.reject(new DisconnectedError("agent channel is closed"));
    const waiter = deferred();
    this._readyWaiters.add(waiter);
    return waiter.promise;
  }

  /**
   * Force a new transport generation and resolve only after its peer HELLO has been intersected.
   * Desktop restore uses this instead of treating a still-open transport as application readiness.
   */
  async rehandshake() {
    if (this._closed) throw new DisconnectedError("agent channel is closed");
    if (!this._started) this.start();
    if (this._state !== CHANNEL_STATE.READY) await this.waitUntilReady();
    if (!this._reconnectEnabled) {
      throw new DisconnectedError("agent channel cannot re-handshake without a reconnecting connector");
    }
    const waiter = deferred();
    this._readyWaiters.add(waiter);
    this._failConnection(
      new DisconnectedError("desktop restore requested a fresh agent HELLO"),
      this._transportGeneration,
    );
    const negotiated = await waiter.promise;
    return Object.freeze({
      ...negotiated,
      generation: this._transportGeneration,
    });
  }

  supports(capability) {
    const required = asU64(capability, "capability");
    return (this.negotiatedCapabilities & required) === required;
  }

  /** Subscribe to one numeric message type. The callback receives an owned frame payload. */
  subscribe(type, listener) {
    type = integerInRange(type, 0, 0xffff, "message type");
    if (typeof listener !== "function") throw new TypeError("channel subscription must be a function");
    let listeners = this._subscriptions.get(type);
    if (!listeners) {
      listeners = new Set();
      this._subscriptions.set(type, listeners);
    }
    listeners.add(listener);
    let active = true;
    return () => {
      if (!active) return false;
      active = false;
      listeners.delete(listener);
      if (listeners.size === 0) this._subscriptions.delete(type);
      return true;
    };
  }

  /** Subscribe to state transitions. It is safe to call from either a page or a Worker. */
  subscribeState(listener) {
    if (typeof listener !== "function") throw new TypeError("state subscription must be a function");
    this._stateListeners.add(listener);
    let active = true;
    return () => {
      if (!active) return false;
      active = false;
      return this._stateListeners.delete(listener);
    };
  }

  listenerCount(type) {
    if (type == null) {
      let count = 0;
      for (const listeners of this._subscriptions.values()) count += listeners.size;
      return count;
    }
    return this._subscriptions.get(integerInRange(type, 0, 0xffff, "message type"))?.size ?? 0;
  }

  get transportListenerCount() {
    return this._transportUnsubscribe ? 1 : 0;
  }

  /**
   * Send an extension frame. There is no implicit retry: if the VM is in a restart gap the
   * returned Promise rejects with DisconnectedError, so a caller cannot mistake loss for success.
   */
  send(typeOrFrame, payload, flagsOrOptions = FLAG_NONE) {
    let type = typeOrFrame;
    let body = payload;
    let flags = flagsOrOptions;
    let capability = null;
    if (typeOrFrame && typeof typeOrFrame === "object" && !ArrayBuffer.isView(typeOrFrame)
        && !(typeOrFrame instanceof ArrayBuffer)) {
      type = typeOrFrame.type ?? typeOrFrame.messageType;
      body = typeOrFrame.payload ?? new Uint8Array();
      flags = typeOrFrame.flags ?? FLAG_NONE;
      capability = typeOrFrame.capability ?? null;
    } else if (flagsOrOptions && typeof flagsOrOptions === "object") {
      flags = flagsOrOptions.flags ?? FLAG_NONE;
      capability = flagsOrOptions.capability ?? null;
    }
    if (this._state !== CHANNEL_STATE.READY) {
      return Promise.reject(new DisconnectedError("agent channel is disconnected; send was not queued"));
    }
    if (capability != null && !this.supports(capability)) {
      return Promise.reject(new CapabilityError(`capability ${String(capability)} is not negotiated`));
    }
    let frame;
    try {
      frame = encodeFrame(type, body ?? new Uint8Array(), flags);
    } catch (error) {
      return Promise.reject(error);
    }
    const generation = this._transportGeneration;
    return this._writeFrame(frame, generation).catch((error) => {
      if (error instanceof BackpressureError) throw error;
      const disconnected = error instanceof DisconnectedError
        ? error
        : new DisconnectedError("agent channel disconnected while sending", { cause: error });
      this._failConnection(disconnected, generation);
      throw disconnected;
    }).then(() => true);
  }

  /** Send a typed PING and resolve with exactly the nonce carried by its PONG. */
  ping(nonceOrOptions) {
    let nonce = nonceOrOptions;
    let timeoutMs = this._pingTimeoutMs;
    if (nonceOrOptions && typeof nonceOrOptions === "object" && !(nonceOrOptions instanceof Number)) {
      nonce = nonceOrOptions.nonce;
      timeoutMs = nonceOrOptions.timeoutMs ?? timeoutMs;
    }
    if (nonce == null) {
      nonce = this._nextNonce;
      this._nextNonce = (this._nextNonce + 1n) & UINT64_MAX;
      if (this._nextNonce === 0n) this._nextNonce = 1n;
    }
    try {
      nonce = asU64(nonce, "PING nonce");
      timeoutMs = normalizeMilliseconds(timeoutMs, this._pingTimeoutMs, { minimum: 0 });
    } catch (error) {
      return Promise.reject(error);
    }
    if (this._state !== CHANNEL_STATE.READY) {
      return Promise.reject(new DisconnectedError("agent channel is disconnected; PING was not queued"));
    }
    if (!this.supports(CAP_PING)) {
      return Promise.reject(new CapabilityError("CAP_PING was not negotiated"));
    }
    if (this._pending.size >= this._maxPending) {
      return Promise.reject(new BackpressureError(
        `agent channel has ${this._pending.size} pending requests (limit ${this._maxPending})`,
      ));
    }
    const key = nonce.toString();
    if (this._pending.has(key)) {
      return Promise.reject(new BackpressureError(`PING nonce ${key} is already in flight`));
    }
    const generation = this._transportGeneration;
    const request = deferred();
    const pending = { nonce, request, timer: null, generation };
    this._pending.set(key, pending);
    if (timeoutMs > 0) {
      pending.timer = setTimeout(() => {
        if (this._pending.get(key) !== pending) return;
        this._settlePending(key, pending, "reject", new RequestTimeoutError(`PING ${key} timed out`));
      }, timeoutMs);
      pending.timer.unref?.();
    }
    let frame;
    try {
      frame = encodeFrame(TYPE_PING, encodePing(nonce), FLAG_NONE);
    } catch (error) {
      this._settlePending(key, pending, "reject", error);
      return request.promise;
    }
    this._writeFrame(frame, generation).catch((error) => {
      if (error instanceof BackpressureError) {
        this._settlePending(key, pending, "reject", error);
        return;
      }
      const disconnected = error instanceof DisconnectedError
        ? error
        : new DisconnectedError("agent channel disconnected while sending PING", { cause: error });
      this._failConnection(disconnected, generation);
      this._settlePending(key, pending, "reject", disconnected);
    });
    return request.promise;
  }

  close(reason = "agent channel closed") {
    if (this._closed) return false;
    this._closed = true;
    this._started = false;
    if (this._retryTimer != null) clearTimeout(this._retryTimer);
    this._retryTimer = null;
    this._clearHandshakeTimer();
    const error = reason instanceof DisconnectedError
      ? reason
      : new DisconnectedError(String(reason), { cause: reason instanceof Error ? reason : undefined });
    this._rejectPending(error);
    this._rejectReadyWaiters(error);
    if (!this._firstReady.settled) {
      this._firstReady.settled = true;
      this._firstReady.reject(error);
    }
    this._cleanupTransport();
    this._transition(CHANNEL_STATE.CLOSED, { error });
    this._subscriptions.clear();
    this._stateListeners.clear();
    return true;
  }

  destroy(reason) {
    return this.close(reason);
  }

  async _attemptConnect() {
    if (this._closed || !this._started || this._connecting) return;
    this._connecting = true;
    this._connectAttempt += 1;
    this._transition(CHANNEL_STATE.CONNECTING, { attempt: this._connectAttempt });
    let candidate;
    try {
      candidate = await this._connect({ attempt: this._connectAttempt });
    } catch (error) {
      this._connecting = false;
      this._failConnection(error, null);
      return;
    }
    this._connecting = false;
    if (this._closed || !this._started) {
      try { normalizeTransport(candidate).close?.(); } catch { /* caller closed during connect */ }
      return;
    }
    let transport;
    try {
      transport = normalizeTransport(candidate);
      const generation = ++this._generation;
      this._transport = transport;
      this._transportGeneration = generation;
      this._decoder.reset();
      this._peerHello = null;
      this._negotiated = null;
      this._transition(CHANNEL_STATE.HANDSHAKING, { generation });
      this._transportUnsubscribe = subscribeTransport(transport, {
        data: (data) => this._receive(data, generation),
        close: (reason) => this._failConnection(
          new DisconnectedError("agent transport closed", { cause: reason instanceof Error ? reason : undefined }),
          generation,
        ),
        error: (reason) => this._failConnection(
          new DisconnectedError("agent transport reported an error", { cause: reason instanceof Error ? reason : undefined }),
          generation,
        ),
      });
      this._armHandshakeTimer(generation);
      const hello = encodeFrame(TYPE_HELLO, encodeHello(this._localVersion, this._localCapabilities), FLAG_NONE);
      this._writeFrame(hello, generation, true).catch((error) => this._failConnection(error, generation));
    } catch (error) {
      try { transport?.close?.(); } catch { /* failed transport setup */ }
      this._failConnection(error, this._transportGeneration || null);
    }
  }

  _receive(value, generation) {
    if (this._closed || generation !== this._transportGeneration) return;
    try {
      this._decoder.push(eventData(value), (frame) => this._receiveFrame(frame, generation));
    } catch (error) {
      this._failConnection(error, generation);
    }
  }

  _receiveFrame(frame, generation) {
    if (this._closed || generation !== this._transportGeneration) return;
    try {
      if (frame.type === TYPE_HELLO) {
        this._receiveHello(frame, generation);
        this._dispatch(frame);
        return;
      }
      if (this._state !== CHANNEL_STATE.READY) {
        throw new ProtocolError("agent frame arrived before HELLO negotiation", "FRAME_BEFORE_HELLO");
      }
      switch (frame.type) {
        case TYPE_PING: {
          const nonce = decodePing(frame.payload, "PING");
          this._writeFrame(encodeFrame(TYPE_PONG, encodePing(nonce), FLAG_NONE), generation)
            .catch((error) => this._failConnection(error, generation));
          this._dispatch(frame);
          break;
        }
        case TYPE_PONG: {
          const nonce = decodePing(frame.payload, "PONG");
          const key = nonce.toString();
          const pending = this._pending.get(key);
          if (pending) this._settlePending(key, pending, "resolve", nonce);
          this._dispatch(frame);
          break;
        }
        case TYPE_NAK: {
          const nak = decodeNak(frame.payload);
          if (nak.rejectedType === TYPE_PING) {
            for (const [key, pending] of [...this._pending]) {
              this._settlePending(
                key,
                pending,
                "reject",
                new NakError(`agent rejected PINGs with NAK code ${nak.code}`),
              );
            }
          }
          this._dispatch(frame);
          break;
        }
        default: {
          if (!this._subscriptions.has(frame.type)) {
            this._writeFrame(
              encodeFrame(TYPE_NAK, encodeNak(frame.type, NAK_UNKNOWN_TYPE), FLAG_NONE),
              generation,
            ).catch((error) => this._failConnection(error, generation));
          } else {
            this._dispatch(frame);
          }
          break;
        }
      }
    } catch (error) {
      this._failConnection(error, generation);
    }
  }

  _receiveHello(frame, generation) {
    const peer = decodeHello(frame.payload);
    if (this._state === CHANNEL_STATE.READY) {
      if (this._peerHello?.version === peer.version && this._peerHello?.capabilities === peer.capabilities) return;
      throw new ProtocolError("peer HELLO changed after negotiation", "STALE_HELLO");
    }
    if (this._state !== CHANNEL_STATE.HANDSHAKING) {
      throw new ProtocolError("HELLO arrived outside the handshake", "HELLO_STATE");
    }
    const version = Math.min(this._localVersion, peer.version);
    if (version === 0) {
      throw new NegotiationError(
        `no common agent protocol version (local=${this._localVersion}, peer=${peer.version})`,
      );
    }
    this._peerHello = peer;
    this._negotiated = Object.freeze({
      version,
      capabilities: this._localCapabilities & peer.capabilities,
      peerVersion: peer.version,
      peerCapabilities: peer.capabilities,
    });
    this._clearHandshakeTimer();
    this._reconnectAttempts = 0;
    this._retryDelayMs = this._reconnectMinDelayMs;
    this._transition(CHANNEL_STATE.READY, { generation, negotiated: this._negotiated });
    if (!this._firstReady.settled) {
      this._firstReady.settled = true;
      this._firstReady.resolve(this._negotiated);
    }
    for (const waiter of this._readyWaiters) {
      if (!waiter.settled) {
        waiter.settled = true;
        waiter.resolve(this._negotiated);
      }
    }
    this._readyWaiters.clear();
  }

  _dispatch(frame) {
    const listeners = this._subscriptions.get(frame.type);
    if (!listeners) return;
    for (const listener of [...listeners]) {
      try {
        listener(frameRecord(frame.type, frame.flags, frame.payload.slice()));
      } catch (error) {
        this._reportError(error);
      }
    }
  }

  _writeFrame(bytes, generation, allowHandshaking = false) {
    if (this._closed || generation !== this._transportGeneration || !this._transport
        || (this._state !== CHANNEL_STATE.READY && !(allowHandshaking && this._state === CHANNEL_STATE.HANDSHAKING))) {
      return Promise.reject(new DisconnectedError("agent channel is disconnected; frame was not queued"));
    }
    if (this._writeDepth >= this._maxPending) {
      return Promise.reject(new BackpressureError("agent channel outbound queue is full"));
    }
    const transport = this._transport;
    this._writeDepth += 1;
    const prior = this._writeTail.catch(() => {});
    const operation = prior.then(() => {
      if (this._closed || generation !== this._transportGeneration || transport !== this._transport) {
        throw new DisconnectedError("agent channel disconnected before frame write");
      }
      return transport.send(bytes);
    });
    this._writeTail = operation.catch(() => {});
    return operation.finally(() => {
      this._writeDepth -= 1;
    });
  }

  _settlePending(key, pending, method, value) {
    if (this._pending.get(key) !== pending || pending.request.settled) return false;
    this._pending.delete(key);
    if (pending.timer != null) clearTimeout(pending.timer);
    pending.request.settled = true;
    pending.request[method](value);
    return true;
  }

  _rejectPending(error) {
    for (const [key, pending] of [...this._pending]) this._settlePending(key, pending, "reject", error);
  }

  _rejectReadyWaiters(error) {
    for (const waiter of this._readyWaiters) {
      if (!waiter.settled) {
        waiter.settled = true;
        waiter.reject(error);
      }
    }
    this._readyWaiters.clear();
  }

  _failConnection(reason, generation) {
    if (this._closed) return;
    if (generation != null && generation !== this._transportGeneration) return;
    const cause = reason instanceof Error ? reason : undefined;
    const error = reason instanceof DisconnectedError
      ? reason
      : new DisconnectedError("agent channel disconnected; reconnecting", { cause });
    this._lastError = reason instanceof Error ? reason : error;
    this._clearHandshakeTimer();
    this._cleanupTransport();
    this._decoder.reset();
    this._peerHello = null;
    this._negotiated = null;
    this._rejectPending(error);
    this._transition(CHANNEL_STATE.DISCONNECTED, { error });
    this._reportError(error);
    this._scheduleReconnect();
  }

  _scheduleReconnect() {
    if (!this._reconnectEnabled || this._closed || !this._started || this._retryTimer != null
        || this._connecting || this._reconnectAttempts >= this._maxReconnectAttempts) return;
    const delay = this._retryDelayMs;
    this._reconnectAttempts += 1;
    this._retryDelayMs = Math.min(
      this._reconnectMaxDelayMs,
      Math.max(this._reconnectMinDelayMs, delay === 0 ? this._reconnectMinDelayMs : delay * 2),
    );
    this._retryTimer = setTimeout(() => {
      this._retryTimer = null;
      void this._attemptConnect();
    }, delay);
    this._retryTimer.unref?.();
  }

  _armHandshakeTimer(generation) {
    this._clearHandshakeTimer();
    this._handshakeTimer = setTimeout(() => {
      if (generation === this._transportGeneration && this._state === CHANNEL_STATE.HANDSHAKING) {
        this._failConnection(new ProtocolError("agent HELLO handshake timed out", "HELLO_TIMEOUT"), generation);
      }
    }, this._handshakeTimeoutMs);
    this._handshakeTimer.unref?.();
  }

  _clearHandshakeTimer() {
    if (this._handshakeTimer != null) clearTimeout(this._handshakeTimer);
    this._handshakeTimer = null;
  }

  _cleanupTransport() {
    const unsubscribe = this._transportUnsubscribe;
    const transport = this._transport;
    this._transportUnsubscribe = null;
    this._transport = null;
    this._transportGeneration = 0;
    try { unsubscribe?.(); } catch (error) { this._reportError(error); }
    try { transport?.close?.(); } catch (error) { this._reportError(error); }
  }

  _transition(state, details = {}) {
    const previous = this._state;
    this._state = state;
    const event = Object.freeze({
      state,
      previous,
      generation: this._transportGeneration || null,
      negotiated: this._negotiated,
      ...details,
    });
    for (const listener of [...this._stateListeners]) {
      try { listener(event); } catch (error) { this._reportError(error); }
    }
  }

  _reportError(error) {
    try { this._onError?.(error); } catch { /* diagnostics must not break the channel */ }
  }
}

export function createAgentChannel(options) {
  return new Channel(options);
}

// Local diagnostic only: arm after restore, before the first execution slice.
// Never enables profiling, changes admission policy, or exposes a mutation RPC.
export function applyAdmissionProbe(machine, requested = false) {
  if (typeof requested !== "boolean") throw new TypeError("jitAdmissionProbe must be boolean");
  if (!requested) return;
  for (const method of ["setAdmissionProbe", "jitStats"]) {
    if (typeof machine?.[method] !== "function") throw new Error(`jitAdmissionProbe requires WASM ${method}`);
  }
  if (machine.jitStats()?.hasExecutor !== true) throw new Error("jitAdmissionProbe requires an actual JIT executor");
  machine.setAdmissionProbe(true);
  if (machine.jitStats()?.admissionProbe?.enabled !== true) {
    throw new Error("jitAdmissionProbe did not reach the actual machine");
  }
}

// E5-T21c: allocation-free AudioWorklet producer for the reversed capture SAB ring.

import { CHANNELS } from "./ring.js";
import {
  AudioCaptureRingBuffer,
} from "./capture-ring.js";

export const AUDIO_CAPTURE_WORKLET_PROCESSOR_NAME = "wasm-vm-audio-capture-producer";
export const AUDIO_CAPTURE_QUANTUM_FRAMES = 128;
export const SUPPORTED_CAPTURE_SAMPLE_RATES_HZ = Object.freeze([44_100, 48_000]);

const WorkletProcessorBase = typeof AudioWorkletProcessor === "function"
  ? AudioWorkletProcessor
  : class AudioWorkletProcessorFallback {};

function validateSampleRate(sampleRateHz) {
  const value = Number(sampleRateHz);
  if (!SUPPORTED_CAPTURE_SAMPLE_RATES_HZ.includes(value)) {
    throw new RangeError("capture worklet sample rate must be 44100 or 48000 Hz");
  }
  return value;
}

function configuredSampleRate(options) {
  const explicit = options?.processorOptions?.sampleRateHz;
  if (explicit !== undefined) return validateSampleRate(explicit);
  const ambient = Number(globalThis.sampleRate);
  return validateSampleRate(Number.isFinite(ambient) ? ambient : 48_000);
}

function makeClock(clockBuffer) {
  if (clockBuffer === undefined || clockBuffer === null) return null;
  if (typeof SharedArrayBuffer === "undefined"
    || !(clockBuffer instanceof SharedArrayBuffer)
    || clockBuffer.byteLength < Int32Array.BYTES_PER_ELEMENT) {
    throw new TypeError("capture worklet clock requires a one-word SharedArrayBuffer");
  }
  return new Int32Array(clockBuffer, 0, 1);
}

export class AudioCaptureWorkletProcessor extends WorkletProcessorBase {
  constructor(options = {}) {
    super();
    const processorOptions = options?.processorOptions ?? {};
    const sharedBuffer = processorOptions.captureBuffer ?? processorOptions.sharedBuffer;
    if (typeof SharedArrayBuffer === "undefined" || !(sharedBuffer instanceof SharedArrayBuffer)) {
      throw new TypeError("capture worklet requires processorOptions.captureBuffer");
    }
    const ring = AudioCaptureRingBuffer.fromSharedBuffer(sharedBuffer);
    this._ring = ring;
    this._producer = ring.producer();
    this._sampleRateHz = configuredSampleRate(options);
    this._clock = makeClock(processorOptions.clockBuffer);
    this._processedFrames = 0;
    // The rendering thread reuses this interleaved stereo block on every process call.
    this._scratch = new Float32Array(AUDIO_CAPTURE_QUANTUM_FRAMES * CHANNELS);
  }

  get sampleRateHz() {
    return this._sampleRateHz;
  }

  get channels() {
    return CHANNELS;
  }

  get processedFrames() {
    return this._processedFrames;
  }

  get processedDurationNs() {
