    this._invalidateFrame();
    this.discardPending();
  }

  /** Return only scalar, JSON-safe scheduler state. */
  snapshot() {
    return {
      enqueued: this._enqueued,
      coalesced: this._coalesced,
      presented: this._presented,
      skipped: this._skipped,
      overruns: this._overruns,
